class WireType(IntEnum):
    VARINT = 0
    FIXED64 = 1
    LENGTH_DELIMITED = 2
    SGROUP = 3
    EGROUP = 4
    FIXED32 = 5

class ProtoValue:
    def __init__(self, value: Any, wire_type: WireType, raw_bytes: bytes):
        self.value = value
        self.wire_type = wire_type
        self.raw_bytes = raw_bytes

class ProtoVarint(ProtoValue):
    def __init__(self, value: int, raw_bytes: bytes):
        super().__init__(value, WireType.VARINT, raw_bytes)

class ProtoFixed64(ProtoValue):
    def __init__(self, value: int, raw_bytes: bytes):
        super().__init__(value, WireType.FIXED64, raw_bytes)

class ProtoFixed32(ProtoValue):
    def __init__(self, value: int, raw_bytes: bytes):
        super().__init__(value, WireType.FIXED32, raw_bytes)

class ProtoBytes(ProtoValue):
    def __init__(self, value: bytes, raw_bytes: bytes):
        super().__init__(value, WireType.LENGTH_DELIMITED, raw_bytes)

class ProtoString(ProtoValue):
    def __init__(self, value: str, raw_bytes: bytes):
        super().__init__(value, WireType.LENGTH_DELIMITED, raw_bytes)

class ProtoMessage(ProtoValue):
    def __init__(self, value: Dict[int, List[ProtoValue]], raw_bytes: bytes):
        super().__init__(value, WireType.LENGTH_DELIMITED, raw_bytes)

class ProtobufDecoder:
    @staticmethod
    def Zesty_decode_varint(buffer: bytes, offset: int) -> Tuple[int, int]:
        result = 0
        shift = 0
        while True:
            if offset >= len(buffer):
                raise ValueError("Unexpected end of buffer")
            byte = buffer[offset]
            result |= (byte & 0x7F) << shift
            offset += 1
            if not (byte & 0x80):
                break
            shift += 7
        return result, offset

    @staticmethod
    def Zesty_decode_fixed64(buffer: bytes, offset: int) -> Tuple[int, int]:
        if offset + 8 > len(buffer):
            raise ValueError("Insufficient data")
        val = struct.unpack_from('<Q', buffer, offset)[0]
        return val, offset + 8

    @staticmethod
    def Zesty_decode_fixed32(buffer: bytes, offset: int) -> Tuple[int, int]:
        if offset + 4 > len(buffer):
            raise ValueError("Insufficient data")
        val = struct.unpack_from('<I', buffer, offset)[0]
        return val, offset + 4

    @classmethod
    def Zesty_decode(cls, data: bytes) -> Dict[int, List[ProtoValue]]:
        buffer = data
        offset = 0
        message: Dict[int, List[ProtoValue]] = {}
        length = len(buffer)

        while offset < length:
            field_start_offset = offset
            tag, offset = cls.Zesty_decode_varint(buffer, offset)
            field_num = tag >> 3
            wire_type = tag & 0x7
            field_header_bytes = buffer[field_start_offset:offset]
            field_value_start = offset

            if wire_type == WireType.VARINT:
                value, offset = cls.Zesty_decode_varint(buffer, offset)
                field_raw_bytes = field_header_bytes + buffer[field_value_start:offset]
                proto_value = ProtoVarint(value, field_raw_bytes)
            elif wire_type == WireType.FIXED64:
                value, offset = cls.Zesty_decode_fixed64(buffer, offset)
                field_raw_bytes = field_header_bytes + buffer[field_value_start:offset]
                proto_value = ProtoFixed64(value, field_raw_bytes)
            elif wire_type == WireType.LENGTH_DELIMITED:
                size, offset = cls.Zesty_decode_varint(buffer, offset)
                if offset + size > length:
                    raise ValueError("Length exceeds buffer")
                chunk = buffer[offset:offset + size]
                field_raw_bytes = field_header_bytes + buffer[field_value_start:offset + size]
                offset += size
                try:
                    nested = cls.Zesty_decode(chunk)
                    proto_value = ProtoMessage(nested, field_raw_bytes)
                except Exception:
                    try:
                        string_value = chunk.decode('utf-8')
                        proto_value = ProtoString(string_value, field_raw_bytes)
                    except UnicodeDecodeError:
                        proto_value = ProtoBytes(chunk, field_raw_bytes)
            elif wire_type == WireType.FIXED32:
                value, offset = cls.Zesty_decode_fixed32(buffer, offset)
                field_raw_bytes = field_header_bytes + buffer[field_value_start:offset]
                proto_value = ProtoFixed32(value, field_raw_bytes)
            elif wire_type in (WireType.SGROUP, WireType.EGROUP):
                # Protobuf group start/end — skip, no payload bytes consumed
                field_raw_bytes = field_header_bytes
                proto_value = ProtoBytes(b"", field_raw_bytes)
            else:
                # Unknown wire type — skip 1 byte and continue rather than crash
                field_raw_bytes = field_header_bytes
                proto_value = ProtoBytes(b"", field_raw_bytes)
                if offset < length:
                    offset += 1

            if field_num not in message:
                message[field_num] = []
            message[field_num].append(proto_value)

        return message

def Zesty_hex_to_json(hex_string: str) -> dict:
    hex_clean = hex_string.replace(" ", "").replace("\n", "")
    data = bytes.fromhex(hex_clean)
    decoded_message = ProtobufDecoder.Zesty_decode(data)
    return Zesty_message_to_json(decoded_message)

def Zesty_message_to_json(message: Dict[int, List[ProtoValue]]) -> dict:
    json_obj = {}
    for field_num, values in message.items():
        if len(values) == 1:
            json_obj[str(field_num)] = Zesty_proto_value_to_json(values[0])
        else:
            json_obj[str(field_num)] = [Zesty_proto_value_to_json(v) for v in values]
    return json_obj

def Zesty_proto_value_to_json(proto_value: ProtoValue) -> Any:
    if isinstance(proto_value, ProtoVarint):
        return proto_value.value
    elif isinstance(proto_value, ProtoFixed32):
        return proto_value.value
    elif isinstance(proto_value, ProtoFixed64):
        return proto_value.value
    elif isinstance(proto_value, ProtoString):
        return proto_value.value
    elif isinstance(proto_value, ProtoBytes):
        return proto_value.value.hex()
    elif isinstance(proto_value, ProtoMessage):
        return Zesty_message_to_json(proto_value.value)
    else:
        return str(proto_value.value)

class WireType(IntEnum):
    VARINT = 0
    FIXED64 = 1
    LENGTH_DELIMITED = 2
    SGROUP = 3
    EGROUP = 4
    FIXED32 = 5
    SIGNED_VARINT = 8

class ProtobufEncoder:
    @staticmethod
    def Zesty_encode_varint(value: int) -> bytes:
        result = bytearray()
        while value > 0x7F:
            result.append((value & 0x7F) | 0x80)
            value >>= 7
        result.append(value & 0x7F)
        return bytes(result)

    @staticmethod
    def Zesty_encode_fixed64(value: int) -> bytes:
        return struct.pack('<Q', value)

    @staticmethod
    def Zesty_encode_fixed32(value: int) -> bytes:
        return struct.pack('<I', value)

    @staticmethod
    def Zesty_encode_zigzag(value: int) -> bytes:
        zigzag = (value << 1) ^ (value >> 63)
        return ProtobufEncoder.Zesty_encode_varint(zigzag & 0xFFFFFFFFFFFFFFFF)

    @staticmethod
    def Zesty_encode_tag(field_num: int, wire_type: int) -> bytes:
        return ProtobufEncoder.Zesty_encode_varint((field_num << 3) | wire_type)

    @classmethod
    def Zesty_encode(cls, message: Dict[int, Any]) -> bytes:
        result = bytearray()
        for field_num, value in message.items():
            if isinstance(value, list):
                for item in value:
                    result.extend(cls.Zesty_encode_field(field_num, item))
            else:
                result.extend(cls.Zesty_encode_field(field_num, value))
        return bytes(result)

    @classmethod
    def Zesty_encode_field(cls, field_num: int, value: Any) -> bytes:
        if isinstance(value, int):
            if value < 0:
                return cls.Zesty_encode_tag(field_num, WireType.VARINT) + cls.Zesty_encode_zigzag(value)
            else:
                return cls.Zesty_encode_tag(field_num, WireType.VARINT) + cls.Zesty_encode_varint(value)
        elif isinstance(value, str):
            encoded_str = value.encode('utf-8')
            return (cls.Zesty_encode_tag(field_num, WireType.LENGTH_DELIMITED) + 
                    cls.Zesty_encode_varint(len(encoded_str)) + encoded_str)
        elif isinstance(value, bytes):
            return (cls.Zesty_encode_tag(field_num, WireType.LENGTH_DELIMITED) + 
                    cls.Zesty_encode_varint(len(value)) + value)
        elif isinstance(value, dict):
            nested_data = cls.Zesty_encode(value)
            return (cls.Zesty_encode_tag(field_num, WireType.LENGTH_DELIMITED) + 
                    cls.Zesty_encode_varint(len(nested_data)) + nested_data)
        elif isinstance(value, bool):
            return cls.Zesty_encode_tag(field_num, WireType.VARINT) + cls.Zesty_encode_varint(1 if value else 0)
        else:
            raise ValueError(f"Unsupported type: {type(value)}")

def Zesty_fields_to_protobuf(fields: Dict[str, Any]) -> bytes:
    converted = {}
    for key, value in fields.items():
        field_num = int(key)
        converted[field_num] = value
    return ProtobufEncoder.Zesty_encode(converted)

