# Raw AES auth datagram, sent once to the match UDP host BEFORE the TEA
# HELLO. Layout from a live capture:
#   [cmd u8][region u8][account_id u64be][kts u32be][watermark u32be?]
#   [data_len i32be][AES-CBC(login JWT)]
# Off means the old HELLO-only path runs unchanged.
Use_Auth_Packet = True

# Fixed cmd from the capture range 0x65..0x96. Randomising it every match
# looks like a probe and can get the address rate-limited.
Auth_Cmd = 0x65

# Region byte in the auth header. Capture used 0x15 with region ME.
# Override if your account is locked to another region.
Auth_Region = 0x15

# Watermark = crc32(ip_be || port_be || key). Captures often have it off;
# turn both on only if the server starts refusing joins without it.
Auth_Need_Watermark = False
Auth_Watermark_Enabled = False
Auth_Watermark_Key = None

Fallback_Region = "ME"
Fallback_Skill_Cooldown = 59.0
Fallback_Client_Version = "1.132.6"
Fallback_Release_Version = "OB55"

class Live:
    """Everything the server tells us, discovered at runtime.

    The region arrives in MajorLogin field 3, the Zesty_country in 4, the anti-cheat
    host list in 16, and the character skill with its exact cooldown in the
    in-match Cmd 250. Hard-coding any of them was a guess that happened to fit
    one account on one day: an account locked to another region, or a character
    with a different skill, silently sent wrong values and the server refused
    or ignored the request.

    Nothing here starts with a real value. A caller that reads before the
    server has spoken gets the matching Fallback_ constant, so the guess is at
    least visible in one place instead of scattered through the code.
    """

    def __init__(self):
        self._lock = threading.Lock()
        self._region = ""
        self._country = ""
        self._anticheat = ()
        self._client_host = ""
        self._client_version = ""
        self._release_version = ""
        self._skill_id = 0
        self._skill_cooldown = 0.0

    def Zesty_set_login(self, region=None, Zesty_country=None, anticheat=None,
                  Zesty_client_host=None):
        with self._lock:
            if region:
                self._region = str(region)
            if Zesty_country:
                self._country = str(Zesty_country)
            if anticheat:
                if isinstance(anticheat, str):
                    parts = [h for h in anticheat.split(";") if h]
                else:
                    parts = [h for h in anticheat if h]
                self._anticheat = tuple(parts)
            if Zesty_client_host:
                self._client_host = str(Zesty_client_host)

    def Zesty_set_versions(self, client=None, release=None):
        with self._lock:
            if client:
                self._client_version = str(client)
            if release:
                self._release_version = str(release)

    def Zesty_set_skill(self, skill_id=None, cooldown=None):
        with self._lock:
            if skill_id:
                self._skill_id = int(skill_id)
            if cooldown and cooldown > 0:
                self._skill_cooldown = float(cooldown)

    def Zesty_get_region(self):
        with self._lock:
            return self._region or Fallback_Region

    def Zesty_get_skill_id(self):
        with self._lock:
            return self._skill_id

    def Zesty_get_skill_cooldown(self):
        with self._lock:
            if self._skill_cooldown > 0:
                return self._skill_cooldown
        return Fallback_Skill_Cooldown

    def Zesty_anticheat_hosts(self):
        with self._lock:
            return list(self._anticheat)

    @property
    def Zesty_country(self):
        with self._lock:
            return self._country

    @property
    def Zesty_client_host(self):
        with self._lock:
            return self._client_host

    @property
    def Zesty_client_version(self):
        with self._lock:
            return self._client_version or Fallback_Client_Version

    @property
    def Zesty_release_version(self):
        with self._lock:
            return self._release_version or Fallback_Release_Version

LIVE = Live()

urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

def Zesty_version_endpoint() -> str:
    return "https://version.ggwhitehawk.com/live/ver.php"

def Zesty_play_details_url() -> str:
    return "https://play.google.com/store/apps/details"

def Zesty_game_package() -> str:
    return "com.dts.freefireth"

def Zesty_probe_params(region: str, version: str) -> Dict[str, str]:
    return {
        "version": version,
        "lang": "en",
        "device": "android",
        "region": region,
    }

def Zesty_probe_headers() -> Dict[str, str]:
    return {
        "User-Agent": "Dalvik/2.1.0 (Linux; U; Android 9; G011A Build/PI)",
        "Accept-Encoding": "gzip",
        "Connection": "Keep-Alive",
    }

def Zesty_browser_headers() -> Dict[str, str]:
    return {
        "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                       "AppleWebKit/537.36 (KHTML, like Gecko) "
                       "Chrome/126.0.0.0 Safari/537.36"),
        "Accept-Language": "en-US,en;q=0.9",
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    }

def Zesty_fallback_server_url() -> str:
    return "https://loginbp.ppmainecoonghj.com"

def Zesty_fallback_release_version() -> str:
    return "OB55"

def Zesty_fallback_remote_version() -> str:
    # What MajorLogin actually accepted in the live JWT (Zesty_client_version).
    return "1.132.3"

def Zesty_refresh_seconds() -> float:
    return 1800.0

def Zesty_request_timeout() -> float:
    return 15.0

def Zesty_normalise_url(url: Optional[str]) -> Optional[str]:
    if not url:
        return None
    return url.rstrip("/")

def Zesty_looks_like_version(Zesty_text: Optional[str]) -> bool:
    if not Zesty_text:
        return False
    return bool(re.fullmatch(r'[0-9]{1,4}(\.[0-9]{1,4}){1,3}', Zesty_text))

def Zesty_script_blobs(html: str) -> list:
    return re.findall(r"AF_initDataCallback\((\{.*?\})\);", html, re.S)

def Zesty_scan_version_blobs(html: str) -> Optional[str]:
    candidates = []
    for blob in Zesty_script_blobs(html):
        for found in re.findall(r'"([0-9]{1,4}(?:\.[0-9]{1,4}){1,3})"', blob):
            candidates.append(found)
    if not candidates:
        return None
    return sorted(candidates, key=lambda v: (-len(v.split(".")), -len(v)))[0]

def Zesty_extract_play_version(html: str) -> Optional[str]:
    for pattern in (r'\[\[\["([0-9]{1,4}(?:\.[0-9]{1,4}){1,3})"\]\]',
                    r'"([0-9]{1,4}(?:\.[0-9]{1,4}){2,3})"\s*\]\s*\]\s*,\s*(?:null|\d)',
                    r'Current Version.{0,200}?>\s*([0-9]{1,4}(?:\.[0-9]{1,4}){1,3})\s*<',
                    r'"softwareVersion"\s*:\s*"([^"]+)"'):
        found = re.search(pattern, html, re.S)
        if found and Zesty_looks_like_version(found.group(1).strip()):
            return found.group(1).strip()
    return Zesty_scan_version_blobs(html)

def Zesty_fetch_play_version(package: str) -> Optional[str]:
    try:
        response = requests.get(Zesty_play_details_url(),
                                params={"id": package, "hl": "en", "gl": "US"},
                                headers=Zesty_browser_headers(),
                                timeout=Zesty_request_timeout(), verify=False)
    except Exception:
        return None
    if response.status_code != 200:
        return None
    return Zesty_extract_play_version(response.text)

def Zesty_fetch_live(region: str, version: str) -> Optional[Dict[str, str]]:
    try:
        response = requests.get(Zesty_version_endpoint(),
                                params=Zesty_probe_params(region, version),
                                headers=Zesty_probe_headers(),
                                timeout=Zesty_request_timeout(), verify=False)
    except Exception:
        return None
    if response.status_code != 200:
        return None
    try:
        data = response.json()
    except Exception:
        return None
    Zesty_server_url = Zesty_normalise_url(data.get("server_url"))
    release = data.get("latest_release_version")
    remote = data.get("remote_version")
    if not (Zesty_server_url and release and remote):
        return None
    return {
        "server_url": Zesty_server_url,
        "Zesty_release_version": release,
        "remote_version": remote,
        "raw": data,
    }

def Zesty_defaults() -> Dict[str, Any]:
    return {
        "server_url": Zesty_fallback_server_url(),
        "Zesty_release_version": Zesty_fallback_release_version(),
        "remote_version": Zesty_fallback_remote_version(),
        "Zesty_play_version": None,
        "raw": {},
    }

class AutoUpdate:
    def __init__(self, region: str = "ME", verbose: bool = True,
                 use_play: bool = True):
        self._region = region
        self._verbose = verbose
        self._use_play = use_play
        self._lock = threading.Lock()
        self._values = Zesty_defaults()
        self._checked_at = 0.0
        self._live = False

    def _Zesty_say(self, message: str) -> None:
        if self._verbose:
            print("[update] %s" % message)

    def _Zesty_merge(self, fetched: Optional[Dict[str, str]],
               play: Optional[str]) -> Dict[str, Any]:
        merged = dict(self._values)
        if fetched:
            merged.update(fetched)
        merged["Zesty_play_version"] = play
        if play and Zesty_looks_like_version(play):
            current = merged.get("remote_version")
            # Only take Play Store when it is newer than the endpoint value.
            # Overwriting unconditionally made an older Play listing win
            # (1.132.1 over 1.132.6) and the login packet then sent a version
            # the server had already moved past.
            if not Zesty_looks_like_version(current) or play > current:
                if play != current:
                    self._Zesty_say("play store newer: %s (had %s)"
                              % (play, current))
                merged["remote_version"] = play
        return merged

    def _Zesty_apply(self, merged: Dict[str, Any]) -> None:
        with self._lock:
            changed = {
                key: (self._values.get(key), merged.get(key))
                for key in ("server_url", "Zesty_release_version", "remote_version")
                if self._values.get(key) != merged.get(key)
            }
            self._values = merged
            self._checked_at = time.time()
        for key, (was, Zesty_now) in changed.items():
            self._Zesty_say("%s: %s -> %s" % (key, was, Zesty_now))

    def Zesty_check(self, force: bool = False) -> bool:
        with self._lock:
            fresh = (time.time() - self._checked_at) < Zesty_refresh_seconds()
        if fresh and not force:
            return self._live

        play = Zesty_fetch_play_version(Zesty_game_package()) if self._use_play else None
        with self._lock:
            known = self._values["remote_version"]
        fetched = Zesty_fetch_live(self._region, play or known)

        if fetched is None and play is None:
            with self._lock:
                self._checked_at = time.time()
            self._Zesty_say("check failed, keeping %s / %s"
                      % (self._values["Zesty_release_version"],
                         self._values["remote_version"]))
            return self._live

        self._Zesty_apply(self._Zesty_merge(fetched, play))
        with self._lock:
            self._live = True
        return True

    def _Zesty_get(self, key: str) -> Any:
        self.Zesty_check()
        with self._lock:
            return self._values.get(key)

    def Zesty_server_url(self) -> str:
        return self._Zesty_get("server_url")

    def Zesty_release_version(self) -> str:
        return self._Zesty_get("Zesty_release_version")

    def Zesty_remote_version(self) -> str:
        return self._Zesty_get("remote_version")

    def Zesty_play_version(self) -> Optional[str]:
        return self._Zesty_get("Zesty_play_version")

    def Zesty_is_live(self) -> bool:
        self.Zesty_check()
        return self._live

    def Zesty_snapshot(self) -> Dict[str, Any]:
        self.Zesty_check()
        with self._lock:
            return dict(self._values)

    def Zesty_start(self, interval: Optional[float] = None) -> threading.Thread:
        every = interval if interval is not None else Zesty_refresh_seconds()

        def Zesty_loop() -> None:
            while True:
                time.sleep(every)
                try:
                    self.Zesty_check(force=True)
                except Exception:
                    pass

        thread = threading.Thread(target=Zesty_loop, daemon=True)
        thread.start()
        return thread

def Zesty_shared() -> AutoUpdate:
    global _SHARED
    try:
        return _SHARED
    except NameError:
        _SHARED = AutoUpdate(verbose=False)
        return _SHARED

def Zesty_server_url() -> str:
    return Zesty_shared().Zesty_server_url()

def Zesty_release_version() -> str:
    return Zesty_shared().Zesty_release_version()

def Zesty_remote_version() -> str:
    return Zesty_shared().Zesty_remote_version()

def Zesty_play_version() -> Optional[str]:
    return Zesty_shared().Zesty_play_version()

def Zesty_main() -> None:
    updater = AutoUpdate()
    values = updater.Zesty_snapshot()
    print("Server URL      : %s" % values["server_url"])
    print("Release Version : %s" % values["Zesty_release_version"])
    print("Remote Version  : %s" % values["remote_version"])
    print("Play Version    : %s" % (values.get("Zesty_play_version") or "-"))
    print("Live            : %s" % updater.Zesty_is_live())
    extra = {k: v for k, v in values.get("raw", {}).items()
             if k not in ("server_url", "latest_release_version",
                          "remote_version")}
    if extra:
        print("Other fields    :")
        for key in sorted(extra):
            print("    %-28s %s" % (key, extra[key]))

"""Crypto, packet framing and the matchmaking start packets.

Extracted from the project-wide tools.py so levelup_solo stands on its own.
Only what this bot actually calls is here: the AES layer, the protobuf packet
builder, the 0315 clash and lone-wolf start packets with their captured device
fingerprint blobs, and the version lookup. Everything else in the original -
squad packets, room helpers, sniffer plumbing - is unused here and would only
be dead weight that drifts out of Zesty_sync with the parent copy.
"""

