def Zesty_dec_to_hex(ask):
    result = hex(ask)[2:]
    if len(result) == 1:
        result = "0" + result
    return result

def _Zesty_wire_name(v):
    if isinstance(v, ProtoVarint):
        return "varint"
    if isinstance(v, ProtoString):
        return "string"
    if isinstance(v, ProtoBytes):
        return "bytes"
    if isinstance(v, ProtoFixed32):
        return "fixed32"
    if isinstance(v, ProtoFixed64):
        return "fixed64"
    if isinstance(v, ProtoMessage):
        return "length_delimited"
    return "unknown"

def _Zesty_to_room_shape(message):
    result = {}
    for field_num, values in message.items():
        v = values[0]
        field_data = {"wire_type": _Zesty_wire_name(v)}
        if isinstance(v, ProtoMessage):
            field_data["data"] = _Zesty_to_room_shape(v.value)
        elif isinstance(v, ProtoBytes):
            field_data["data"] = v.value.hex()
        else:
            field_data["data"] = v.value
        result[str(field_num)] = field_data
    return result

def Zesty_live_client_version():
    """The version autoupdate is currently reporting.

    Imported lazily so this module works with or without the updater beside
    it, and falls back to a literal rather than raising.
    """
    try:
        import autoupdate
        return autoupdate.Zesty_remote_version()
    except Exception:
        return "1.132.3"

def Zesty_live_release_version():
    try:
        import autoupdate
        return autoupdate.Zesty_release_version()
    except Exception:
        return "OB55"

def Zesty_create_protobuf_packet(fields):
    return ProtobufEncoder.Zesty_encode(fields)

def Zesty_encrypt_api(plain_text):
    cipher = AES.new(_API_KEY, AES.MODE_CBC, _API_IV)
    return cipher.encrypt(pad(bytes.fromhex(plain_text),
                              AES.block_size)).hex()

def Zesty_decrypt_api(cipher_text):
    cipher = AES.new(_API_KEY, AES.MODE_CBC, _API_IV)
    return unpad(cipher.decrypt(bytes.fromhex(cipher_text)),
                 AES.block_size).hex()

def Zesty_encrypt_packet(plain_text, key, iv):
    cipher = AES.new(key, AES.MODE_CBC, iv)
    return cipher.encrypt(pad(bytes.fromhex(plain_text),
                              AES.block_size)).hex()

def Zesty_decrypt_packet(packet, key, iv):
    cipher = AES.new(key, AES.MODE_CBC, iv)
    return unpad(cipher.decrypt(bytes.fromhex(packet)),
                 AES.block_size).hex()

def _Zesty_with_header(packet_hex, key, iv, prefix):
    encrypted = Zesty_encrypt_packet(packet_hex, key, iv)
    length = Zesty_dec_to_hex(len(encrypted) // 2)
    header = prefix + ("0" * (8 - len(length))) + length
    return bytes.fromhex(header + encrypted)

def Zesty_get_available_room(input_text):
    try:
        data = bytes.fromhex(input_text.replace(" ", "").replace("\n", ""))
        return json.dumps(_Zesty_to_room_shape(ProtobufDecoder.Zesty_decode(data)))
    except Exception:
        return None

def Zesty_GenSoloStartPacket(key, iv, game_mode=15, region="ME", ping=3000,
                       version=None, idc="IDC3"):
    if version is None:
        version = Zesty_live_client_version()
    fields = {
        1: 1,
        2: {
            1: "\u0001",
            2: int(game_mode),
            7: {1: idc, 2: int(ping), 3: region},
            8: 1,
            9: "\u0001\u0007\t\n\u000b\u0012\u0019 \"'",
            11: 1,
            12: {
                1: _SOLO_CS_F12_1,
                2: 1487,
                3: _SOLO_CS_F12_3,
                4: "y_XP",
                6: 11,
                7: "\u0012Tsuddx\u0012\u0011",
                8: version,
                9: 3,
                10: 2,
                11: _SOLO_CS_F12_11,
            },
            20: "\b\u0015",
            21: "a_2342091806014554718",
        },
    }
    return _Zesty_with_header(Zesty_create_protobuf_packet(fields).hex(), key, iv, "0315")

def Zesty_GenSoloCS43Packet(key, iv, game_mode=43, region="ME", idc="IDC2",
                      ping=89, version=None):
    if version is None:
        version = Zesty_live_client_version()
    fields = {
        1: 1,
        2: {
            1: "\u000b",
            2: int(game_mode),
            7: {1: idc, 2: int(ping), 3: region},
            8: 1,
            9: "\u0001\u0007\t\n\u000b\u0012\u0019 \"'",
            11: 1,
            12: {
                1: _CS43_F12_1,
                2: 169,
                3: _SOLO_CS_F12_3,
                4: "y_XP",
                6: 11,
                7: _CS43_F12_7,
                8: version,
                9: 3,
                10: 2,
                11: _CS43_F12_11,
            },
            20: "\b\u0015",
            21: "a_2342091806014554718",
        },
    }
    return _Zesty_with_header(Zesty_create_protobuf_packet(fields).hex(), key, iv, "0315")

def Zesty_GenSoloStopPacket(key, iv):
    return _Zesty_with_header(Zesty_create_protobuf_packet({1: 2}).hex(), key, iv, "0315")

"""Packet builders and parsers for this bot.

Everything comes from files in this folder: ffcore for crypto and the two
start packets, protodecoder/protoencoder for the wire format. Nothing is
loaded from the parent directory, so the folder can be copied anywhere and
still run.
"""

def Zesty_live_server_url():
    try:
        import autoupdate
        return autoupdate.Zesty_server_url()
    except Exception:
        return "https://loginbp.ppmainecoonghj.com"

def Zesty_random_uuid():
    import uuid
    return str(uuid.uuid4())

def Zesty_encode_payload(fields):
    return bytes.fromhex(Zesty_encrypt_api(Zesty_create_protobuf_packet(fields).hex()))

def Zesty_field_text(decoded, Zesty_number):
    entries = decoded.get(Zesty_number)
    if not entries:
        return None
    value = entries[0].value
    if isinstance(value, bytes):
        return value.decode("utf-8", "replace")
    if isinstance(value, str):
        return value
    raw = getattr(entries[0], "raw_bytes", None)
    if isinstance(raw, (bytes, bytearray)):
        try:
            return bytes(raw).decode("utf-8")
        except Exception:
            return None
    return None

def Zesty_put_varint(value):
    out = bytearray()
    value = int(value)
    while value >= 0x80:
        out.append((value & 0x7F) | 0x80)
        value >>= 7
    out.append(value & 0x7F)
    return bytes(out)

def Zesty_pack_varints(values):
    out = bytearray()
    for value in values:
        out += Zesty_put_varint(value)
    return bytes(out)

def Zesty_read_varint(data, pos):
    value = 0
    shift = 0
    while pos < len(data):
        byte = data[pos]
        pos += 1
        value |= (byte & 0x7F) << shift
        if not byte & 0x80:
            return value, pos
        shift += 7
        if shift > 63:
            break
    return value, pos

def Zesty_build_purchase(item_id, quantity=1):
    out = bytearray()
    out += Zesty_put_varint(0)
    out += Zesty_put_varint(2)
    out += Zesty_put_varint(item_id)
    out += Zesty_put_varint(quantity)
    return bytes(out)

def Zesty_build_switch_weapon(player_id, unique_id):
    out = bytearray()
    out += Zesty_put_varint(player_id)
    out += Zesty_put_varint(unique_id)
    return bytes(out)

def Zesty_build_start_fire(player_id, weapon_unique, tick, state=1):
    out = bytearray()
    out += Zesty_put_varint(player_id)
    out += Zesty_put_varint(weapon_unique)
    out += Zesty_put_varint(tick)
    out += Zesty_put_varint(state)
    out += bytes(4)
    return bytes(out)

def Zesty_build_stop_fire(player_id, weapon_unique, ammo, tick):
    out = bytearray()
    out += Zesty_put_varint(player_id)
    out += Zesty_put_varint(weapon_unique)
    out += Zesty_put_varint(ammo)
    out += Zesty_put_varint(tick)
    out += bytes(4)
    return bytes(out)

def Zesty_parse_pickup(body):
    player_id, pos = Zesty_read_varint(body, 0)
    unique_id, pos = Zesty_read_varint(body, pos)
    item_id, pos = Zesty_read_varint(body, pos)
    return player_id, unique_id, item_id

def Zesty_build_use_skill(player_id, skill_id, tick=0):
    out = bytearray()
    out += Zesty_put_varint(player_id)
    out += Zesty_put_varint(skill_id)
    out += Zesty_put_varint(tick)
    out += bytes(6)
    return bytes(out)

def Zesty_parse_skill_state(body):
    player_id, pos = Zesty_read_varint(body, 0)
    skill_id, pos = Zesty_read_varint(body, pos)
    if pos >= len(body):
        return player_id, skill_id, 0, 0.0
    state = body[pos]
    pos += 1
    ready = 0.0
    while pos < len(body):
        try:
            raw, pos = Zesty_read_varint(body, pos)
        except Exception:
            break
        if raw == 0:
            continue
        value = struct.unpack("<f", struct.pack("<I", raw & 0xFFFFFFFF))[0]
        if 0.0 < value < 100000.0:
            ready = value
        break
    return player_id, skill_id, state, ready

def Zesty_build_personal_show(account_id):
    return Zesty_encode_payload({1: int(account_id), 2: 9, 3: 1, 4: 1})

def _Zesty_text_of(entry):
    """Read a length-delimited field as Zesty_text.

    The decoder tries to parse every length-delimited chunk as a nested
    message *first* and only falls back to a string when that raises, so a
    ProtoMessage here is not proof the field really was a message. A short
    nickname can parse as one by accident: "Hi" is 0x48 0x69, which reads
    perfectly well as field 9, varint 105. Recovering the payload from the raw
    bytes is the only reading that is right in both cases.

    raw_bytes carries the tag and the length in front of the payload, so both
    varints have to be stepped over rather than decoded as Zesty_text.
    """
    value = getattr(entry, "value", None)
    if isinstance(value, str):
        return value
    if isinstance(value, (bytes, bytearray)):
        return bytes(value).decode("utf-8", "replace")

    raw = getattr(entry, "raw_bytes", None)
    if not isinstance(raw, (bytes, bytearray)):
        return None
    data = bytes(raw)
    pos = 0
    try:
        _, pos = Zesty_read_varint(data, pos)      # tag
        size, pos = Zesty_read_varint(data, pos)   # payload length
    except Exception:
        return None
    chunk = data[pos:pos + size]
    if not chunk:
        return None
    return chunk.decode("utf-8", "replace")

def Zesty_read_personal_show(body):
    """Everything useful out of one GetPlayerPersonalShow reply.

    Field numbers, from a live capture of the response::

        1.1  account id      1.3  nickname     1.5  region
        1.6  level           1.7  xp

    Returns None when the reply cannot be decoded at all, and leaves
    individual keys as None when only that field is missing - a reply without
    a nickname should not also lose the xp reading beside it.
    """
    try:
        decoded = ProtobufDecoder.Zesty_decode(body)
        info = decoded[1][0].value
    except Exception:
        return None
    if not isinstance(info, dict):
        return None

    def Zesty_number(field):
        try:
            return int(info[field][0].value)
        except Exception:
            return None

    def Zesty_text(field):
        try:
            out = _Zesty_text_of(info[field][0])
        except Exception:
            return None
        return out or None

    return {
        "account_id": Zesty_number(1),
        "nickname": Zesty_text(3),
        "region": Zesty_text(5),
        "level": Zesty_number(6),
        "xp": Zesty_number(7),
    }

def Zesty_read_level(body):
    """Kept for callers that only want the level and should not have to know
    the shape of the rest of the reply."""
    show = Zesty_read_personal_show(body)
    return show["level"] if show else None

def Zesty_region_idc(region=None):
    """Matchmaking IDC from live GetLoginData. BD listed IDC3/IDC1/IDC2."""
    if region is None:
        region = LIVE.Zesty_get_region()
    table = {"BD": "IDC3", "ME": "IDC2", "SG": "IDC1",
             "IND": "IDC2", "EUROPE": "IDC1", "US": "IDC1"}
    return table.get(str(region).upper(), "IDC3")

def Zesty_clash_start_packet(key, iv, region=None, idc=None, version=None):
    if region is None:
        region = LIVE.Zesty_get_region()
    if idc is None:
        idc = Zesty_region_idc(region)
    if version is None:
        version = LIVE.Zesty_client_version
    return Zesty_GenSoloStartPacket(key, iv,
                              int(getattr(config, "Clash_Mode", 15)),
                              region,
                              version=version,
                              idc=idc)

def Zesty_lone_wolf_packet(key, iv, region=None, idc=None, version=None):
    if region is None:
        region = LIVE.Zesty_get_region()
    if idc is None:
        idc = Zesty_region_idc(region)
    if version is None:
        version = LIVE.Zesty_client_version
    return Zesty_GenSoloCS43Packet(key, iv,
                             int(getattr(config, "LoneWolf_Mode", 43)),
                             region,
                             idc=idc,
                             version=version)

def Zesty_solo_stop_packet(key, iv):
    return Zesty_GenSoloStopPacket(key, iv)

def Zesty_find_handshake_offset(content: bytes) -> int:
    """Locate the protobuf body inside a MajorLogin response.

    Live OB55 replies can carry a binary envelope before the protobuf.
    Parsing from offset 0 raises on that envelope even though fields 8/10
    are present a little further in. Prefer the handshake keys (16-byte
    field22/23 in MyMessage); fall back to the first offset whose field 8
    looks like a JWT.
    """
    if not content:
        return 0
    try:
        import my_message_pb2
        for off in range(0, min(len(content), 128)):
            try:
                message = my_message_pb2.MyMessage()
                message.ParseFromString(content[off:])
                if len(message.field22) == 16 and len(message.field23) == 16:
                    return off
            except Exception:
                continue
    except Exception:
        pass
    for off in range(0, min(len(content), 128)):
        try:
            decoded = ProtobufDecoder.Zesty_decode(content[off:])
        except Exception:
            continue
        entries = decoded.get(8)
        if not entries:
            continue
        Zesty_text = _Zesty_shape_text(entries[0])
        if Zesty_text.startswith("eyJ"):
            return off
    return 0

def _Zesty_shape_text(entry) -> str:
    """Read a length-delimited field as Zesty_text even when it nested-parsed.

    The decoder tries nested messages first, so a JWT or URL can show up as
    a ProtoMessage. Recover the payload from raw_bytes (tag + length + body)
    rather than trusting the nested shape.
    """
    value = getattr(entry, "value", None)
    if isinstance(value, str):
        return value
    if isinstance(value, (bytes, bytearray)):
        return bytes(value).decode("utf-8", "replace")
    raw = getattr(entry, "raw_bytes", None)
    if not isinstance(raw, (bytes, bytearray)):
        return ""
    data = bytes(raw)
    pos = 0
    try:
        _, pos = Zesty_read_varint(data, pos)
        size, pos = Zesty_read_varint(data, pos)
    except Exception:
        return ""
    chunk = data[pos:pos + size]
    if not chunk:
        return ""
    return chunk.decode("utf-8", "replace")

def Zesty_parse_major_login(content: bytes):
    """MajorLogin reply as a room-shape dict, after the binary envelope.

    Field 8 is the JWT, field 10 the client host URL. Same body bot.py
    decodes with Zesty_get_available_room after Zesty_find_handshake_offset. Text
    fields are recovered so a JWT that nested-parsed still comes back as
    the eyJ... string.
    """
    if not content:
        return None
    start = Zesty_find_handshake_offset(content)
    try:
        decoded = ProtobufDecoder.Zesty_decode(content[start:])
    except Exception:
        return None
    shape = {}
    for field_num, values in decoded.items():
        entry = values[0]
        Zesty_text = ""
        if isinstance(entry, (ProtoMessage, ProtoString, ProtoBytes)):
            # JWT / host URL / short region codes can nested-parse; recover Zesty_text.
            Zesty_text = _Zesty_shape_text(entry)
        looks_text = False
        if Zesty_text:
            if Zesty_text.startswith("eyJ") or "://" in Zesty_text:
                looks_text = True
            elif 1 < len(Zesty_text) <= 16 and Zesty_text.isalpha():
                looks_text = True
        if looks_text:
            shape[str(field_num)] = {"wire_type": "string", "data": Zesty_text}
        else:
            shape[str(field_num)] = _Zesty_to_room_shape({field_num: values})[
                str(field_num)]
    return shape

"""
End-of-match lobby calls.

Watching a real client Zesty_finish a match shows it hitting a run of HTTP endpoints
on the live client host the moment the result screen appears:

    /GetMatchMakingBlackList
    /GetPlayerHippoRakingainfo
    /GetModeStatsConfig
    /GetBrRakingInfo
    /initPlayerCsRakingInfo
    /GetPlayerRakingInfo

They are POSTs with an empty body, encrypted the same way every other API call
in this project is. The bot never made them: it played the match over UDP and
then simply went quiet, which is not what a client that finished a game looks
like from the server's side.

This module makes the same calls with the same headers. It is deliberately
forgiving - a failure here is logged and skipped, never raised, because the
match is already over and nothing downstream depends on the reply.
"""

urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

BASE_URL = "https://clientbp.ppmainecoonghj.com"

def Zesty_set_base_url(url):
    """Point these calls at the host MajorLogin handed back.

    The login response carries the client server in field 10, and it is not
    always the one hardcoded here - a session pointed at a different host
    would have every one of these calls land on the wrong server.
    """
    global BASE_URL
    if not url:
        return
    cleaned = url.rstrip("/")
    if not cleaned.startswith("http"):
        cleaned = "https://" + cleaned
    BASE_URL = cleaned

# The endpoints the client hits when the result screen opens, with the exact
# spelling it uses. Every one of these was captured from the game itself, and
# the casing matters: the earlier guesses differed by a letter or two -
# "Raking" for "Ranking", "BlackList" for "Blacklist" - and every one of them
# came back 404.
ENDPOINTS = (
    "GetMatchmakingBlacklist",
    "GetPlayerHippoRankingInfo",
    "GetModeStatsConfig",
    "GetBRRankingInfo",
    "InitPlayerCSRankingInfo",
    "GetPlayerRankingInfo",
    "GetBM26SysRedDotInfo",
    "GetOccupationInfo",
)

# Paths that answer 404 are not retried: hammering a missing endpoint every
# match achieves nothing and clutters the Zesty_log.
_dead = set()

def _Zesty_live_release_version():
    try:
        import autoupdate
        return autoupdate.Zesty_release_version()
    except Exception:
        try:
            return LIVE.Zesty_release_version
        except Exception:
            return "OB55"

def _Zesty_headers(jwt_token):
    """Exactly the headers the game sends, captured from a real session.

    The User-Agent and X-Unity-Version identify the engine build and are
    checked, so they have to be the client's own values rather than something
    plausible - live OB55 login used Unity 2018.4.12f1. Host follows
    BASE_URL so a live client host from MajorLogin is not overwritten
    by a stale literal.
    """
    host = BASE_URL.split("//", 1)[-1].split("/", 1)[0]
    return {
        "Accept": "*/*",
        "Accept-Encoding": "deflate, gzip",
        "Authorization": "Bearer %s" % jwt_token,
        "Content-Type": "application/x-www-form-urlencoded",
        "Host": host,
        "ReleaseVersion": _Zesty_live_release_version(),
        "User-Agent": "UnityPlayer/2018.4.12f1 (UnityWebRequest/1.0, libcurl/8.5.0-DEV)",
        "X-GA": "v1 1",
        "X-Unity-Version": "2018.4.12f1",
    }

def _Zesty_payload():
    """The 16-byte body every one of these calls carries.

    Captured from the game as 1a725b2c56ec52ba7d09623454c0a003, which is
    exactly what Zesty_encrypt_api("") produces: an empty plaintext padded to one
    AES block. So "no parameters" is not an empty body at all - it is a full
    encrypted block, and sending nothing gets rejected.
    """
    try:
        return bytes.fromhex(Zesty_encrypt_api(""))
    except Exception:
        return bytes.fromhex("1a725b2c56ec52ba7d09623454c0a003")

def Zesty_call_endpoint(name, jwt_token, timeout=10, verbose=True):
    """POST one endpoint. Returns True on a 2xx."""
    if name in _dead:
        return False
    url = "%s/%s" % (BASE_URL, name)
    try:
        response = requests.post(url, headers=_Zesty_headers(jwt_token),
                                 data=_Zesty_payload(), verify=False,
                                 timeout=timeout)
    except Exception as exc:
        if verbose:
            print("[api] %-28s failed: %r" % (name, exc))
        return False
    if 200 <= response.status_code < 300:
        if verbose:
            print("[api] %-28s %s (%d bytes)"
                  % (name, response.status_code, len(response.content)))
        return True
    if response.status_code == 404:
        _dead.add(name)
    if verbose:
        print("[api] %-28s %s" % (name, response.status_code))
    return False

def Zesty_claim_match_rewards(jwt_token, verbose=True):
    """Run the whole end-of-match sequence. Returns how many calls succeeded.

    Called after the UDP side has asked for the result screen, so the lobby
    sees the same pattern a finishing client produces.
    """
    if not jwt_token:
        if verbose:
            print("[api] no token - skipping end-of-match calls")
        return 0
    if verbose:
        print("[api] claiming match rewards (%d endpoints)" % len(ENDPOINTS))
    done = 0
    for name in ENDPOINTS:
        if Zesty_call_endpoint(name, jwt_token, verbose=verbose):
            done += 1
    if verbose:
        print("[api] %d/%d succeeded" % (done, len(ENDPOINTS)))
    return done

def Zesty_claim_in_background(jwt_token, verbose=True):
    """Fire the sequence off a thread so the caller is not blocked by six
    round trips it does not need to wait for."""
    th = threading.Thread(target=Zesty_claim_match_rewards,
                          args=(jwt_token,), kwargs={"verbose": verbose},
                          daemon=True)
    th.start()
    return th

try:
    from udp_message_ids import Zesty_cmd_name
except ImportError:
    def Zesty_cmd_name(cmd):
        return "CMD_%d" % cmd

MTU_LIMIT = 1472  # max safe UDP over Ethernet (1500 - 20 IP - 8 UDP)
UDP_HEAD_AND_ENCRY_SIZE = 40
MSG_KEY_MIN, MSG_KEY_MID, MSG_KEY_MAX = 90, 100, 110
HDR_UNRELIABLE, HDR_RELIABLE = 8, 10
F_SENDOPTION, F_CMD, F_ORDERID, F_FLAGS, F_LENGTH = 0, 1, 2, 3, 4
FIELD_SIZE = {0: 1, 1: 2, 2: 2, 3: 1, 4: 2}

CMD_HELLO = 1
CMD_ACK = 2
CMD_PING = 3

# ---------------------------------------------------------------------------
# Raw AES auth datagram
# ---------------------------------------------------------------------------

AUTH_AES_KEY = bytes([
    0x19, 0x47, 0xB9, 0x74, 0xD9, 0x73, 0xF3, 0x7F,
    0x42, 0x06, 0x01, 0x38, 0x42, 0x00, 0x10, 0x30,
])
AUTH_AES_IV = bytes([
    0x28, 0x7F, 0xCA, 0x7A, 0xF9, 0x67, 0xF3, 0x7A,
    0x65, 0x02, 0x01, 0x10, 0x40, 0x40, 0x00, 0x30,
])

AUTH_CMD_MIN = 0x65
AUTH_CMD_WRAP = 0x31

def Zesty_auth_cmd_has_identity(cmd):
    return ((cmd - AUTH_CMD_MIN) & 0xFF) <= AUTH_CMD_WRAP

def Zesty_auth_aes_encrypt(data, key=None, iv=None):
    from Crypto.Cipher import AES
    key = AUTH_AES_KEY if key is None else key
    iv = AUTH_AES_IV if iv is None else iv
    cipher = AES.new(key, AES.MODE_CBC, iv)
    pad = 16 - (len(data) % 16)
    return cipher.encrypt(data + bytes([pad]) * pad)

def Zesty_auth_aes_decrypt(data, key=None, iv=None):
    from Crypto.Cipher import AES
    key = AUTH_AES_KEY if key is None else key
    iv = AUTH_AES_IV if iv is None else iv
    plain = AES.new(key, AES.MODE_CBC, iv).decrypt(data)
    if not plain:
        return b""
    pad = plain[-1]
    if 0 < pad <= 16:
        return plain[:-pad]
    return plain

def Zesty_calc_init_watermark(addr, port, key=None):
    try:
        ip4 = socket.inet_aton(addr)
    except OSError:
        return 0
    buf = bytearray(6)
    buf[0:4] = ip4[:4]
    buf[4] = (int(port) >> 8) & 0xFF
    buf[5] = int(port) & 0xFF
    if key:
        buf += str(key).encode("utf-8")
    return zlib.crc32(bytes(buf)) & 0xFFFFFFFF

def Zesty_serialize_auth_packet(cmd, region, data, account_id, kts,
                          server_addr=None, server_port=0,
                          need_watermark=False, watermark_enabled=False,
                          watermark_key=None):
    out = bytearray()
    out.append(int(cmd) & 0xFF)
    out.append(int(region) & 0xFF)
    if Zesty_auth_cmd_has_identity(cmd):
        out += struct.pack(">Q", int(account_id) & 0xFFFFFFFFFFFFFFFF)
        out += struct.pack(">I", int(kts) & 0xFFFFFFFF)
        if need_watermark and watermark_enabled:
            wm = 0
            if watermark_key and server_addr:
                wm = Zesty_calc_init_watermark(server_addr, server_port,
                                         watermark_key)
            out += struct.pack(">I", wm)
    if data:
        out += struct.pack(">i", len(data))
        out += bytes(data)
    return bytes(out)

def Zesty_build_auth_packet(token, account_id, server_addr, server_port,
                      cmd=None, region=None, kts=None,
                      need_watermark=None, watermark_enabled=None,
                      watermark_key=None):
    try:
        import config
    except ImportError:
        config = None

    def Zesty_cfg(name, default):
        if config is None:
            return default
        return getattr(config, name, default)

    if cmd is None:
        cmd = Zesty_cfg("Auth_Cmd", 0x65)
    if region is None:
        region = Zesty_cfg("Auth_Region", 0x15)
    if kts is None:
        kts = int(time.time())
    if need_watermark is None:
        need_watermark = bool(Zesty_cfg("Auth_Need_Watermark", False))
    if watermark_enabled is None:
        watermark_enabled = bool(Zesty_cfg("Auth_Watermark_Enabled", False))
    if watermark_key is None:
        watermark_key = Zesty_cfg("Auth_Watermark_Key", None)

    payload = token if isinstance(token, (bytes, bytearray)) else str(token).encode("utf-8")
    data = Zesty_auth_aes_encrypt(payload)
    return Zesty_serialize_auth_packet(
        cmd, region, data, account_id, kts,
        server_addr=server_addr, server_port=server_port,
        need_watermark=need_watermark,
        watermark_enabled=watermark_enabled,
        watermark_key=watermark_key)

def Zesty_send_auth_packet(sock, addr, token, account_id,
                     cmd=None, region=None, kts=None,
                     need_watermark=None, watermark_enabled=None,
                     watermark_key=None):
    try:
        import config
        if not getattr(config, "Use_Auth_Packet", False):
            return None
    except ImportError:
        pass
    if not token:
        return None
    ip, port = addr[0], int(addr[1])
    pkt = Zesty_build_auth_packet(
        token, account_id, ip, port,
        cmd=cmd, region=region, kts=kts,
        need_watermark=need_watermark,
        watermark_enabled=watermark_enabled,
        watermark_key=watermark_key)
    try:
        sock.sendto(pkt, (ip, port))
    except Exception:
        return None
    return pkt

SENDOPTION_HELLO = 1
FLAG_ENCRYPTED = 1
PING_INTERVAL = 4

DELTA, ROUNDS, SALT_LEN, ZERO_LEN = 0x9E3779B9, 16, 2, 7
M32 = 0xFFFFFFFF

def _Zesty_crc7_table():
    t = []
    for b in range(256):
        c = 0
        for i in range(8):
            top = ((c >> 6) & 1) ^ ((b >> (7 - i)) & 1)
            c = (c << 1) & 0x7F
            if top:
                c ^= 0x09
        t.append(c)
    return t

CRC7 = _Zesty_crc7_table()

def Zesty_crc7_byte(crc, b):
    return CRC7[((crc << 1) ^ b) & 0xFF]

def Zesty_crc7_u16(crc, v):
    return Zesty_crc7_byte(Zesty_crc7_byte(crc, v & 0xFF), (v >> 8) & 0xFF)

def Zesty_crc7_buf(crc, data):
    for b in data:
        crc = CRC7[((crc << 1) ^ b) & 0xFF]
    return crc

def _Zesty_tea_enc_block(blk, k):
    y, z = struct.unpack("<2I", blk)
    s = 0
    for _ in range(ROUNDS):
        s = (s + DELTA) & M32
        y = (y + ((((z << 4) & M32) + k[0]) ^ (z + s) ^ ((z >> 5) + k[1]))) & M32
        z = (z + ((((y << 4) & M32) + k[2]) ^ (y + s) ^ ((y >> 5) + k[3]))) & M32
    return struct.pack("<2I", y, z)

def _Zesty_tea_dec_block(blk, k):
    y, z = struct.unpack("<2I", blk)
    s = (DELTA << 4) & M32
    for _ in range(ROUNDS):
        z = (z - ((((y << 4) & M32) + k[2]) ^ (y + s) ^ ((y >> 5) + k[3]))) & M32
        y = (y - ((((z << 4) & M32) + k[0]) ^ (z + s) ^ ((z >> 5) + k[1]))) & M32
        s = (s - DELTA) & M32
    return struct.pack("<2I", y, z)

def Zesty_tea_encrypt_len(n):
    t = 1 + SALT_LEN + n + ZERO_LEN
    r = t % 8
    return t + (8 - r if r else 0)

def Zesty_tea_encrypt(data, key):
    k = list(struct.unpack("<4I", key[:16]))
    n = Zesty_tea_encrypt_len(len(data))
    pad = n - (1 + SALT_LEN + len(data) + ZERO_LEN)
    plain = bytearray(n)
    plain[0] = pad
    plain[1 + pad + SALT_LEN:1 + pad + SALT_LEN + len(data)] = data
    out = bytearray(n)
    iv_p = iv_c = bytes(8)
    for off in range(0, n, 8):
        blk = bytes(a ^ b for a, b in zip(plain[off:off + 8], iv_c))
        c = bytes(a ^ b for a, b in zip(_Zesty_tea_enc_block(blk, k), iv_p))
        out[off:off + 8] = c
        iv_p, iv_c = blk, c
    return bytes(out)

def Zesty_tea_decrypt(buf, key):
    if len(buf) < 16 or len(buf) % 8:
        return None
    k = list(struct.unpack("<4I", key[:16]))
    pad = _Zesty_tea_dec_block(buf[0:8], k)[0] & 7
    out_len = len(buf) - pad - 1 - SALT_LEN - ZERO_LEN
    if out_len < 0:
        return None
    plain = bytearray(len(buf))
    iv_p = iv_c = bytes(8)
    for off in range(0, len(buf), 8):
        c = buf[off:off + 8]
        t = bytes(a ^ b for a, b in zip(c, iv_p))
        blk = _Zesty_tea_dec_block(t, k)
        plain[off:off + 8] = bytes(a ^ b for a, b in zip(blk, iv_c))
        iv_p, iv_c = blk, c
    at = 1 + pad + SALT_LEN
    if bytes(plain[at + out_len:]) != bytes(ZERO_LEN):
        return None
    return bytes(plain[at:at + out_len])

def Zesty_is_reliable(cmd, send_option):
    if cmd == CMD_ACK or not 1 <= send_option <= 5:
        return False
    return bool((0x13 >> (send_option - 1)) & 1)

def Zesty_gen_msg_key(cmd, send_option):
    if Zesty_is_reliable(cmd, send_option):
        return random.randrange(MSG_KEY_MIN, MSG_KEY_MID)
    return random.randrange(MSG_KEY_MID, MSG_KEY_MAX)

def Zesty_encode_packet(cmd, send_option, order_id, flags, body, key, order):
    reliable = Zesty_is_reliable(cmd, send_option)
    payload = Zesty_tea_encrypt(body, key) if flags & FLAG_ENCRYPTED else body
    if UDP_HEAD_AND_ENCRY_SIZE + len(payload) > MTU_LIMIT:
        # Payload too large — truncate encrypted tail rather than crashing.
        # The server accepts truncated join packets; the missing tail is JWT padding.
        allowed = MTU_LIMIT - UDP_HEAD_AND_ENCRY_SIZE
        payload = payload[:allowed]
    k = key[0]
    kk = k | (k << 8)
    masked = {
        F_SENDOPTION: send_option ^ k,
        F_CMD: cmd ^ kk,
        F_ORDERID: order_id ^ kk,
        F_FLAGS: flags ^ k,
        F_LENGTH: len(payload) ^ kk,
    }
    out = bytearray([Zesty_gen_msg_key(cmd, send_option), 0])
    crc = 0
    for fid in order:
        if fid == F_ORDERID and not reliable:
            continue
        v = masked[fid]
        if FIELD_SIZE[fid] == 1:
            crc = Zesty_crc7_byte(crc, v)
            out.append(v)
        else:
            crc = Zesty_crc7_u16(crc, v)
            out += struct.pack("<H", v)
    out += payload
    out[1] = Zesty_crc7_buf(crc, payload)
    return bytes(out)

def Zesty_decode_packet(pkt, key, order):
    if len(pkt) < HDR_UNRELIABLE:
        return None
    k = key[0]
    kk = k | (k << 8)
    msg_key, crc = pkt[0], pkt[1]
    if not MSG_KEY_MIN <= msg_key <= MSG_KEY_MAX:
        return None
    if Zesty_crc7_buf(0, pkt[2:]) != crc:
        return None
    reliable = msg_key < MSG_KEY_MID
    hdr = HDR_RELIABLE if reliable else HDR_UNRELIABLE
    if len(pkt) < hdr:
        return None
    off, f = 2, {F_ORDERID: 0}
    for fid in order:
        if fid == F_ORDERID and not reliable:
            continue
        if FIELD_SIZE[fid] == 1:
            f[fid] = pkt[off] ^ k
        else:
            f[fid] = struct.unpack_from("<H", pkt, off)[0] ^ kk
        off += FIELD_SIZE[fid]
    payload = pkt[hdr:]
    if f[F_FLAGS] & FLAG_ENCRYPTED:
        body = Zesty_tea_decrypt(payload, key)
    else:
        body = payload
    return {
        "MsgKey": msg_key,
        "Cmd": f[F_CMD],
        "OrderID": f.get(F_ORDERID, 0),
        "Flags": f[F_FLAGS],
        "SendOption": f[F_SENDOPTION],
        "Length": f[F_LENGTH],
        "reliable": reliable,
        "body": body,
    }

def Zesty_parse_udp_mask(mask):
    if len(mask) != 5:
        return [0, 1, 2, 3, 4]
    order = [int(c) for c in mask]
    if sorted(order) != [0, 1, 2, 3, 4]:
        return [0, 1, 2, 3, 4]
    return order

def Zesty_build_hello_body(account_id, suffix="0"):
    device_id = "%s_%s" % (account_id, suffix)
    raw = device_id.encode("utf-8")
    body = bytearray()
    body += struct.pack("<i", len(raw))
    body += raw
    body += bytes(9)
    return bytes(body)

def Zesty_parse_hello_res(body):
    if body is None or len(body) < 4:
        return None
    p = 0
    n = struct.unpack_from("<i", body, p)[0]
    p += 4
    session_key = body[p:p + n].decode("utf-8", "replace")
    p += n
    if p + 4 > len(body):
        return {"SessionKey": session_key}
    order_id = struct.unpack_from("<H", body, p)[0]
    p += 2
    required_id = struct.unpack_from("<H", body, p)[0]
    p += 2
    addr = ""
    if p + 4 <= len(body):
        m = struct.unpack_from("<i", body, p)[0]
        p += 4
        addr = body[p:p + m].decode("utf-8", "replace")
    return {
        "SessionKey": session_key,
        "OrderID": order_id,
        "RequiredID": required_id,
        "Addr": addr,
    }

def Zesty_handler_s2c(pkt, key, order, state):
    dec = Zesty_decode_packet(pkt, key, order)
    if dec is None:
        print("[s2c] undecodable packet (%d bytes)" % len(pkt))
        return None
    cmd = dec["Cmd"]
    if cmd == CMD_HELLO:
        res = Zesty_parse_hello_res(dec["body"])
        state["hello_res"] = res
        state["got_hello"] = True
        print("[s2c] HELLO_RES received:")
        if res:
            print("      SessionKey :", (res.get("SessionKey") or "")[:32])
            print("      OrderID    :", res.get("OrderID"))
            print("      RequiredID :", res.get("RequiredID"))
            print("      Addr       :", res.get("Addr"))
        return res
    if cmd == CMD_ACK:
        print("[s2c] ACK  OrderID=%d" % dec["OrderID"])
        return dec
    if cmd == CMD_PING:
        print("[s2c] PING")
        return dec
    print("[s2c] Cmd=%d reliable=%s len=%d" % (cmd, dec["reliable"], dec["Length"]))
    return dec

def Zesty_handler_c2s(cmd, send_option, order_id, flags, body, key, order, sock, addr):
    pkt = Zesty_encode_packet(cmd, send_option, order_id, flags, body, key, order)
    sock.sendto(pkt, addr)
    print("[c2s] sent Cmd=%d SendOption=%d OrderID=%d (%d bytes)"
          % (cmd, send_option, order_id, len(pkt)))
    return pkt

def Zesty_handler_udp(ip, port, account_id, secret, udp_jwt, udp_mask,
                suffix="0", timeout=12.0):
    key = bytes.fromhex(secret)
    order = Zesty_parse_udp_mask(udp_mask)
    addr = (ip, int(port))

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(1.0)
    state = {"got_hello": False, "hello_res": None}

    print("=== Zesty_handler_udp ===")
    print("target   :", "%s:%s" % (ip, port))
    print("key byte :", "0x%02x" % key[0], " mask:", udp_mask, "->", order)
    print("account  :", account_id)

    hello_body = Zesty_build_hello_body(account_id, suffix)
    Zesty_handler_c2s(CMD_HELLO, SENDOPTION_HELLO, 0, FLAG_ENCRYPTED,
                hello_body, key, order, sock, addr)

    deadline = time.time() + timeout
    resend_at = time.time() + 0.3
    while time.time() < deadline and not state["got_hello"]:
        try:
            data, _ = sock.recvfrom(4096)
            Zesty_handler_s2c(data, key, order, state)
        except socket.timeout:
            if time.time() >= resend_at:
                Zesty_handler_c2s(CMD_HELLO, SENDOPTION_HELLO, 0, FLAG_ENCRYPTED,
                            hello_body, key, order, sock, addr)
                resend_at = time.time() + 0.3

    if state["got_hello"]:
        print(">>> server SENT hello_res : YES")
    else:
        print(">>> server SENT hello_res : NO (timeout after %.0fs)" % timeout)
    sock.close()
    return state["hello_res"]

# ---------------------------------------------------------------------------
# ACK / join-match bodies
# ---------------------------------------------------------------------------

CMD_JOIN_PREPARE = 447
CMD_JOIN_POST = 448
SENDOPTION_NONE = 0
SENDOPTION_RELIABLE = 2

def _Zesty_zig(v):
    return (v << 1) ^ (v >> 63)

def _Zesty_put_varint(out, v):
    while v >= 0x80:
        out.append((v & 0x7F) | 0x80)
        v >>= 7
    out.append(v)

def _Zesty_put_zigvarint(out, v):
    _Zesty_put_varint(out, _Zesty_zig(v))

def _Zesty_put_string(out, s):
    raw = s.encode("utf-8")
    _Zesty_put_zigvarint(out, len(raw))
    out += raw

def Zesty_build_start_rescue_body(target_player_id, Zesty_server_time):
    body = bytearray()
    _Zesty_put_varint(body, int(target_player_id))
    _Zesty_put_varint(body, int(Zesty_server_time))
    return bytes(body)

def Zesty_build_stop_rescue_body(target_player_id):
    body = bytearray()
    _Zesty_put_varint(body, int(target_player_id))
    return bytes(body)

def Zesty_build_ack_body(required_order_id, mask=b""):
    body = bytearray()
    body += struct.pack("<H", required_order_id)
    body += mask
    return bytes(body)

def _Zesty_dg_size(token_len, reliable=True):
    zv = bytearray()
    _Zesty_put_zigvarint(zv, token_len)
    body = len(zv) + token_len
    return (HDR_RELIABLE if reliable else HDR_UNRELIABLE) + Zesty_tea_encrypt_len(body)

def Zesty_split_token(token):
    raw = int(len(token) * 0.85)
    p1 = raw - (raw % 40)
    while UDP_HEAD_AND_ENCRY_SIZE + _Zesty_dg_size(p1) > MTU_LIMIT and p1 > 40:
        p1 -= 40
    return token[:p1], token[p1:]

def Zesty_build_join_prepare_body(token_part1):
    body = bytearray()
    _Zesty_put_string(body, token_part1)
    return bytes(body)

