def _Zesty_print_reply(dec):
    if dec is None:
        print("cmd = <undecodable>")
        return
    print("cmd = %d (%s)" % (dec["Cmd"], Zesty_cmd_name(dec["Cmd"])))
    print("send_option =", dec["SendOption"])
    body = dec["body"]
    if body is None:
        print("decrypted_payload = <decrypt failed>")
        return
    print("decrypted_payload =", body.hex())
    if dec["Cmd"] == CMD_PLAYER_STATE_SYNC:
        Zesty_print_player_state(body)

def Zesty_handler_full(ip, port, account_id, secret, udp_jwt, udp_mask,
                 suffix="0", timeout=15.0,
                 game_mode=15, map_id=1, match_mode=1, sleep_ms=0,
                 match_id=0):
    key = bytes.fromhex(secret)
    order = Zesty_parse_udp_mask(udp_mask)
    addr = (ip, int(port))

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    sock.settimeout(1.0)
    delay = sleep_ms / 1000.0

    print("=== Zesty_handler_full ===")
    print("target :", "%s:%s" % (ip, port), " key byte 0x%02x  order %s" % (key[0], order))
    print("match  : game_mode=%d map_id=%d match_mode=%d sleep_ms=%d"
          % (game_mode, map_id, match_mode, sleep_ms))

    hello_body = Zesty_build_hello_body(account_id, suffix)
    Zesty_handler_c2s(CMD_HELLO, SENDOPTION_HELLO, 0, FLAG_ENCRYPTED, hello_body, key, order, sock, addr)

    hello_res = None
    deadline = time.time() + timeout
    resend = time.time() + 0.3
    while time.time() < deadline and hello_res is None:
        try:
            data, _ = sock.recvfrom(4096)
            dec = Zesty_decode_packet(data, key, order)
            if dec and dec["Cmd"] == CMD_HELLO:
                hello_res = Zesty_parse_hello_res(dec["body"])
                print("[1] HELLO_RES: OrderID=%s RequiredID=%s Addr=%s"
                      % (hello_res.get("OrderID"), hello_res.get("RequiredID"), hello_res.get("Addr")))
        except socket.timeout:
            if time.time() >= resend:
                Zesty_handler_c2s(CMD_HELLO, SENDOPTION_HELLO, 0, FLAG_ENCRYPTED, hello_body, key, order, sock, addr)
                resend = time.time() + 0.3
    if hello_res is None:
        print(">>> no HELLO_RES, aborting")
        sock.close()
        return

    required = (hello_res.get("OrderID", 0) + 1) & 0xFFFF
    ack_body = Zesty_build_ack_body(required)
    Zesty_handler_c2s(CMD_ACK, SENDOPTION_NONE, 0, FLAG_ENCRYPTED, ack_body, key, order, sock, addr)
    print("[2] sent ACK RequiredOrderID=%d" % required)

    part1, part2 = Zesty_split_token(udp_jwt)
    body447 = Zesty_build_join_prepare_body(part1)
    if delay > 0:
        time.sleep(delay)
    Zesty_handler_c2s(CMD_JOIN_PREPARE, SENDOPTION_RELIABLE, 0, FLAG_ENCRYPTED, body447, key, order, sock, addr)
    print("[3] sent Cmd 447 OrderID=0 (token part1=%d chars)" % len(part1))

    got_447_ack = False
    deadline = time.time() + timeout
    resend = time.time() + 0.3
    while time.time() < deadline and not got_447_ack:
        try:
            data, _ = sock.recvfrom(4096)
            dec = Zesty_decode_packet(data, key, order)
            if dec is None:
                continue
            if dec["Cmd"] == CMD_ACK:
                got_447_ack = True
                print("[4] server ACK for 447 received")
            else:
                print("[4] server reply while waiting 447-ack:")
                _Zesty_print_reply(dec)
        except socket.timeout:
            if time.time() >= resend:
                Zesty_handler_c2s(CMD_JOIN_PREPARE, SENDOPTION_RELIABLE, 0, FLAG_ENCRYPTED, body447, key, order, sock, addr)
                resend = time.time() + 0.3
    if not got_447_ack:
        print(">>> no ACK for 447, aborting before 448")
        sock.close()
        return

    body448 = Zesty_build_join_post_body(account_id, part2, game_mode=game_mode,
                                   match_mode=match_mode, map_id=map_id,
                                   match_id=match_id)
    if delay > 0:
        time.sleep(delay)
    Zesty_handler_c2s(CMD_JOIN_POST, SENDOPTION_RELIABLE, 1, FLAG_ENCRYPTED, body448, key, order, sock, addr)
    print("[5] sent Cmd 448 OrderID=1 (token part2=%d chars)" % len(part2))

    import os
    log_path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                            "udp_capture.txt")
    Zesty_log = open(log_path, "w", encoding="utf-8")
    Zesty_log.write("# Free Fire UDP capture\n")
    Zesty_log.write("# target=%s:%s account=%s secret=%s mask=%s\n"
              % (ip, port, account_id, secret, udp_mask))
    Zesty_log.write("# seq\tt\tcmd\tname\tso\trel\toid\tlen\tpayload_hex\n")
    Zesty_log.flush()

    follower = PlayerFollower(step=200)
    chase = FollowHandler()
    clock = ServerClock()
    move_interval = 0.1

    stop_moving = threading.Event()
    move_lock = threading.Lock()

    def Zesty_movement_loop():
        next_tick = time.time()
        while not stop_moving.is_set():
            try:
                Zesty_now = time.time()
                if Zesty_now < next_tick:
                    time.sleep(min(0.02, next_tick - Zesty_now))
                    continue
                next_tick += move_interval
                if next_tick < Zesty_now:
                    next_tick = Zesty_now + move_interval
                with move_lock:
                    my_pos = follower.my_pos
                    target_pos = follower.Zesty_predicted_target(Zesty_now)
                    my_pid = follower.my_player_id
                    t_yrot = follower.target_yrot
                    t_aim_y = follower.target_aim_y
                    t_aim_xz = follower.target_aim_xz
                    t_state = follower.target_state
                    t_pose = follower.target_pose
                if my_pid is None or my_pos is None or target_pos is None:
                    continue
                result = chase.Zesty_next_position(my_pos, target_pos, Zesty_now,
                                             dt=move_interval)
                if result is None:
                    continue
                new_pos, dist, yaw = result
                with move_lock:
                    follower.my_pos = new_pos
                Zesty_send_position(sock, addr, key, order, my_pid, my_pos, new_pos,
                              clock.Zesty_now(Zesty_now), aim_yaw=yaw,
                              target_yrot=t_yrot, target_aim_y=t_aim_y,
                              target_aim_xz=t_aim_xz,
                              copy_state=t_state, copy_pose=t_pose)
            except Exception:
                try:
                    time.sleep(move_interval)
                except Exception:
                    pass
                continue

    mover = threading.Thread(target=Zesty_movement_loop, daemon=True)
    mover.start()

    counts = {}
    seq = 0
    t0 = time.time()
    next_ping = time.time()
    next_move = time.time()
    sock.settimeout(move_interval)

    print("following whoever sends a quick chat - logging to %s" % log_path)
    print("press Ctrl+C to stop")
    try:
        while True:
            Zesty_now = time.time()
            if Zesty_now >= next_ping:
                try:
                    Zesty_send_ping(sock, addr, key, order)
                except OSError:
                    pass
                next_ping = Zesty_now + PING_INTERVAL
            try:
                data, _ = sock.recvfrom(4096)
            except socket.timeout:
                continue
            except OSError:
                continue
            try:
                dec = Zesty_decode_packet(data, key, order)
            except (ValueError, IndexError, struct.error):
                continue
            if dec is None:
                continue
            if dec["reliable"]:
                try:
                    req = (dec["OrderID"] + 1) & 0xFFFF
                    ack = Zesty_encode_packet(CMD_ACK, SENDOPTION_NONE, 0,
                                        FLAG_ENCRYPTED, Zesty_build_ack_body(req),
                                        key, order)
                    sock.sendto(ack, addr)
                except OSError:
                    pass
            cmd = dec["Cmd"]
            body = dec["body"]
            counts[cmd] = counts.get(cmd, 0) + 1
            seq += 1
            Zesty_log.write("%04d\t%.3f\t%d\t%s\t%d\t%d\t%d\t%d\t%s\n"
                      % (seq, Zesty_now - t0, cmd, Zesty_cmd_name(cmd), dec["SendOption"],
                         1 if dec["reliable"] else 0, dec["OrderID"],
                         len(body) if body is not None else 0,
                         body.hex() if body is not None else "<decrypt-failed>"))
            Zesty_log.flush()

            if cmd == CMD_SYNC_SERVER_TIME:
                st = Zesty_decode_server_time(body)
                if st is not None:
                    tick, phase = st
                    clock.Zesty_sync(tick, phase, Zesty_now)
                    try:
                        ackpkt = Zesty_encode_packet(CMD_SYNC_SERVER_TIME,
                                               SENDOPTION_NONE, 0,
                                               FLAG_ENCRYPTED,
                                               Zesty_build_server_time_ack(tick),
                                               key, order)
                        sock.sendto(ackpkt, addr)
                    except OSError:
                        pass
            elif cmd == CMD_PLAYER_JOIN:
                info = Zesty_parse_player_join(body)
                if info is not None:
                    uid, full_pid, name = info
                    follower.Zesty_add_player(full_pid, name)
                    print("PlayerJoin: short=%-3d PlayerID=0x%08X team=%-2d %s"
                          % (full_pid & 0xFF, full_pid, (full_pid >> 24) & 0xFF, name))
                    if uid == int(account_id):
                        follower.Zesty_set_me(full_pid)
                        print(">>> that is ME: PlayerID=0x%08X short=%d"
                              % (full_pid, full_pid & 0xFF))
            elif cmd == CMD_PLAYER_STATE_SYNC and body is not None and len(body) > 3:
                try:
                    p = 2
                    _sid = body[p]; p += 1
                    x, p = _Zesty_rd_varint(body, p)
                    y, p = _Zesty_rd_varint(body, p)
                    z, p = _Zesty_rd_varint(body, p)
                    follower.Zesty_set_my_position((_Zesty_zag(x), _Zesty_zag(y), _Zesty_zag(z)))
                except (IndexError, ValueError):
                    pass
            elif cmd == CMD_PLAYER_STATE_V2:
                follower.Zesty_on_players(Zesty_decode_players_v2(body))
            elif cmd == CMD_QUICK_CHAT:
                qc = Zesty_decode_quick_chat(body)
                if qc is not None:
                    chat_id, short_id, raw, team = qc
                    name = QUICK_CHAT_NAMES.get(chat_id, "chat_%d" % chat_id)
                    who = follower.roster.get(short_id, (0, "?"))[1]
                    print("QUICK CHAT '%s' from 0x%08X -> short=%d (%s)"
                          % (name, raw, short_id, who))
                    if follower.Zesty_on_quick_chat(chat_id, short_id):
                        chase.Zesty_reset()
                        print(">>> Zesty_now following player %d (%s)" % (short_id, who))
    except KeyboardInterrupt:
        print("\nstopping...")
    finally:
        stop_moving.set()
        Zesty_log.write("# --- summary: %d packets ---\n" % seq)
        for c in sorted(counts):
            Zesty_log.write("# cmd %-5d %-45s x%d\n" % (c, Zesty_cmd_name(c), counts[c]))
        Zesty_log.close()
        print("=== %d packets logged to %s ===" % (seq, log_path))
        sock.close()

# ---------------------------------------------------------------------------
# S2C_UDP_PlayerState_Res (Cmd 2001)
# ---------------------------------------------------------------------------

CMD_PLAYER_STATE_SYNC = 2001

def _Zesty_rd_varint(b, p):
    v = i = 0
    while True:
        c = b[p + i]
        v |= (c & 0x7F) << (7 * i)
        i += 1
        if not c & 0x80:
            return v, p + i

def _Zesty_zag(v):
    return (v >> 1) ^ -(v & 1)

def _Zesty_read_vec3(b, p):
    x, p = _Zesty_rd_varint(b, p)
    y, p = _Zesty_rd_varint(b, p)
    z, p = _Zesty_rd_varint(b, p)
    return (_Zesty_zag(x), _Zesty_zag(y), _Zesty_zag(z)), p

def _Zesty_read_vec2(b, p):
    x, p = _Zesty_rd_varint(b, p)
    y, p = _Zesty_rd_varint(b, p)
    return (_Zesty_zag(x), _Zesty_zag(y)), p

def _Zesty_decode_player(b, p):
    pid = b[p]; p += 1
    pos, p = _Zesty_read_vec3(b, p)
    rot, p = _Zesty_read_vec3(b, p)
    tdir, p = _Zesty_read_vec2(b, p)
    vel, p = _Zesty_read_vec3(b, p)
    physx_state = b[p]; p += 1
    physx_pose = b[p]; p += 1
    aim, p = _Zesty_read_vec3(b, p)
    platform, p = _Zesty_rd_varint(b, p)
    custom = b[p]; p += 1
    return {
        "pid": pid, "pos": pos, "rot": rot, "tdir": tdir, "vel": vel,
        "physx_state": physx_state, "physx_pose": physx_pose,
        "aim": aim, "platform": platform, "custom": custom,
    }, p

def Zesty_decode_player_state(body):
    p = 0
    mt, p = _Zesty_rd_varint(body, p)
    match_time = _Zesty_zag(mt)
    cnt, p = _Zesty_rd_varint(body, p)
    count = _Zesty_zag(cnt)
    players = []
    for _ in range(count):
        pl, p = _Zesty_decode_player(body, p)
        players.append(pl)
    self_replay = body[p] if p < len(body) else 0
    p += 1
    tick = 0
    if p < len(body):
        tick, p = _Zesty_rd_varint(body, p)
    return {
        "match_time": match_time, "count": count, "players": players,
        "self_replay": self_replay, "tick": tick,
    }

def Zesty_print_player_state(body):
    try:
        st = Zesty_decode_player_state(body)
    except (IndexError, ValueError):
        print("   <player-state decode failed>")
        return
    pids = [pl["pid"] for pl in st["players"]]
    print("PLAYERS: count=%d  ShortPlayerIDs=%s" % (st["count"], pids))
    print("   MatchTime=%d TickCount=%d players=%d SelfForReplay=%d"
          % (st["match_time"], st["tick"], st["count"], st["self_replay"]))
    for pl in st["players"]:
        print("   ShortPlayerID=%-3d pos=%s rot=%s vel=%s aim=%s tdir=%s platform=%d physx=%d/%d custom=%d"
              % (pl["pid"], pl["pos"], pl["rot"], pl["vel"], pl["aim"],
                 pl["tdir"], pl["platform"], pl["physx_state"], pl["physx_pose"], pl["custom"]))

# ---------------------------------------------------------------------------
# C2S_UDP_Ping_Req (Cmd 3)
# ---------------------------------------------------------------------------

def Zesty_build_ping_body(send_tick, average_ping=0, ping_a500=0, rudp_resend_rate=0):
    o = bytearray()
    _Zesty_put_zigvarint(o, send_tick & 0xFFFFFFFF)
    _Zesty_put_zigvarint(o, average_ping)
    _Zesty_put_zigvarint(o, ping_a500)
    _Zesty_put_zigvarint(o, rudp_resend_rate)
    return bytes(o)

def Zesty_send_ping(sock, addr, key, order, average_ping=0):
    tick = int(time.time() * 1000) & 0xFFFFFFFF
    body = Zesty_build_ping_body(tick, average_ping)
    pkt = Zesty_encode_packet(CMD_PING, SENDOPTION_NONE, 0, 0, body, key, order)
    sock.sendto(pkt, addr)
    return tick

# ---------------------------------------------------------------------------
# S2C_RUDP_PlayerJoin_Res (Cmd 101)
# ---------------------------------------------------------------------------

CMD_PLAYER_JOIN = 101

def Zesty_extract_my_player_id(body, account_id):
    if body is None or len(body) < 3:
        return None
    try:
        p = 0
        user_id, p = _Zesty_rd_varint(body, p)
        _samo_id, p = _Zesty_rd_varint(body, p)
        player_id, p = _Zesty_rd_varint(body, p)
    except (IndexError, ValueError):
        return None
    if user_id == int(account_id):
        return player_id
    return None

def Zesty_parse_player_join(body):
    if body is None or len(body) < 4:
        return None
    try:
        p = 0
        user_id, p = _Zesty_rd_varint(body, p)
        _samo_id, p = _Zesty_rd_varint(body, p)
        player_id, p = _Zesty_rd_varint(body, p)
        raw_len, p = _Zesty_rd_varint(body, p)
        n = _Zesty_zag(raw_len)
        name = body[p:p + n].decode("utf-8", "replace")
    except (IndexError, ValueError):
        return None
    return user_id, player_id, name

# ---------------------------------------------------------------------------
# C2S_UDP_PlayerState_Req (Cmd 2001)
# ---------------------------------------------------------------------------

CMD_PLAYER_STATE_UPLOAD = 2001

def _Zesty_put_float_bits(o, f):
    bits = struct.unpack("<I", struct.pack("<f", f))[0]
    _Zesty_put_varint(o, bits)

def Zesty_build_player_state_upload(player_id, pos, rot, tdir, vel, aim_float,
                              physx_state=0, physx_pose=0, platform=0,
                              low_grav=0, ping=0, jump=0, slide=0, custom=0):
    o = bytearray()
    _Zesty_put_varint(o, player_id)
    _Zesty_put_zigvarint(o, pos[0]); _Zesty_put_zigvarint(o, pos[1]); _Zesty_put_zigvarint(o, pos[2])
    _Zesty_put_zigvarint(o, rot[0]); _Zesty_put_zigvarint(o, rot[1]); _Zesty_put_zigvarint(o, rot[2])
    _Zesty_put_zigvarint(o, tdir[0]); _Zesty_put_zigvarint(o, tdir[1])
    _Zesty_put_zigvarint(o, vel[0]); _Zesty_put_zigvarint(o, vel[1]); _Zesty_put_zigvarint(o, vel[2])
    o.append(physx_state & 0xFF)
    o.append(physx_pose & 0xFF)
    _Zesty_put_float_bits(o, aim_float[0]); _Zesty_put_float_bits(o, aim_float[1]); _Zesty_put_float_bits(o, aim_float[2])
    _Zesty_put_varint(o, platform)
    o.append(1 if low_grav else 0)
    _Zesty_put_varint(o, ping)
    o.append(jump & 0xFF)
    _Zesty_put_varint(o, slide)
    o.append(custom & 0xFF)
    return bytes(o)

def Zesty_build_c2s_player_state(player_id, pos, rot, tdir, vel, aim_float,
                           Zesty_server_time, **kw):
    o = bytearray()
    o += Zesty_build_player_state_upload(player_id, pos, rot, tdir, vel, aim_float, **kw)
    _Zesty_put_varint(o, Zesty_server_time & 0xFFFFFFFF)
    return bytes(o)

def Zesty_send_my_movement(sock, addr, key, order, my_player_id, other_players,
                     Zesty_server_time, ping=0, offset=(100, 100, 100)):
    if not other_players or my_player_id is None:
        return
    ref = None
    for pl in other_players:
        if pl["pid"] != my_player_id:
            ref = pl
            break
    if ref is None:
        return
    new_pos = (
        ref["pos"][0] + offset[0],
        ref["pos"][1] + offset[1],
        ref["pos"][2] + offset[2],
    )
    aim = tuple(float(v) for v in ref["aim"])
    body = Zesty_build_c2s_player_state(
        player_id=my_player_id,
        pos=new_pos,
        rot=ref["rot"],
        tdir=ref["tdir"],
        vel=ref["vel"],
        aim_float=aim,
        Zesty_server_time=Zesty_server_time,
        platform=ref["platform"],
        physx_state=ref["physx_state"],
        physx_pose=ref["physx_pose"],
        custom=ref["custom"],
        ping=ping,
    )
    pkt = Zesty_encode_packet(CMD_PLAYER_STATE_UPLOAD, SENDOPTION_NONE, 0,
                        FLAG_ENCRYPTED, body, key, order)
    sock.sendto(pkt, addr)

# ---------------------------------------------------------------------------
# S2C_RUDP_SafeZone_Changed (Cmd 117)
# ---------------------------------------------------------------------------

CMD_SAFE_ZONE_CHANGE = 117

def _Zesty_read_vec2pos(b, p):
    x, p = _Zesty_rd_varint(b, p)
    z, p = _Zesty_rd_varint(b, p)
    return (_Zesty_zag(x), _Zesty_zag(z)), p

def _Zesty_read_float(b, p):
    bits, p = _Zesty_rd_varint(b, p)
    return struct.unpack("<f", struct.pack("<I", bits))[0], p

def Zesty_decode_safezone(body):
    p = 0
    stage = body[p]; p += 1
    outer_center, p = _Zesty_read_vec2pos(body, p)
    outer_radius, p = _Zesty_rd_varint(body, p)
    inner_center, p = _Zesty_read_vec2pos(body, p)
    inner_radius, p = _Zesty_rd_varint(body, p)
    time_span_type = body[p]; p += 1
    start_time, p = _Zesty_rd_varint(body, p)
    end_time, p = _Zesty_rd_varint(body, p)
    quick_preshrink = body[p]; p += 1
    random_inner = body[p]; p += 1
    minimap_scale, p = _Zesty_read_float(body, p)
    return {
        "stage": stage,
        "outer_center": outer_center, "outer_radius": outer_radius,
        "inner_center": inner_center, "inner_radius": inner_radius,
        "time_span_type": time_span_type,
        "start_time": start_time, "end_time": end_time,
        "quick_preshrink": quick_preshrink, "random_inner": random_inner,
        "minimap_scale": minimap_scale,
    }

def Zesty_print_safezone(body):
    try:
        z = Zesty_decode_safezone(body)
    except (IndexError, ValueError):
        print("   <safezone decode failed>")
        return
    print("SAFE ZONE (Cmd 117):")
    print("   StageID       =", z["stage"])
    print("   OuterCenter   =", z["outer_center"], " OuterRadius =", z["outer_radius"])
    print("   InnerCenter   =", z["inner_center"], " InnerRadius =", z["inner_radius"])
    print("   TimeSpanType  =", z["time_span_type"])
    print("   StartTime     =", z["start_time"], " EndTime =", z["end_time"])
    print("   QuickPreShrink=", z["quick_preshrink"], " RandomInner =", z["random_inner"])
    print("   MiniMapScale  =", z["minimap_scale"])

# ---------------------------------------------------------------------------
# Safe-zone navigation
# ---------------------------------------------------------------------------

class ZoneNavigator:
    def __init__(self, ticks_per_sec=20, min_step=50):
        self.ticks_per_sec = ticks_per_sec
        self.min_step = min_step
        self.step = 250
        self.center = None
        self.start_time = None
        self.end_time = None
        self.my_pos = None
        self.round_num = 0
        self.active = False
        self.last_yaw = 0

    def Zesty_ensure_start(self, ref_player):
        if self.my_pos is None and ref_player is not None:
            self.my_pos = ref_player["pos"]

    def Zesty_on_zone(self, zone):
        self.round_num += 1
        self.center = zone["inner_center"]
        self.start_time = zone["start_time"]
        self.end_time = zone["end_time"]
        self.active = True
        if self.my_pos is not None:
            dx = self.center[0] - self.my_pos[0]
            dz = self.center[1] - self.my_pos[2]
            dist = math.sqrt(dx * dx + dz * dz)
            window = max(1, self.end_time - self.start_time)
            total_ticks = window * self.ticks_per_sec
            self.step = max(self.min_step, int(dist / total_ticks) + 1)
        window = self.end_time - self.start_time
        print("ROUND %d: new zone center=%s window=%ds -> step=%d/tick"
              % (self.round_num, self.center, window, self.step))

    def Zesty_step_toward(self):
        if not self.active or self.center is None or self.my_pos is None:
            return None
        old_pos = self.my_pos
        cx, cz = self.center
        dx = cx - self.my_pos[0]
        dz = cz - self.my_pos[2]
        dist = math.sqrt(dx * dx + dz * dz)
        if dist >= 1:
            self.last_yaw = int(math.degrees(math.atan2(dx, dz)))
        yaw = self.last_yaw
        if dist <= self.step:
            self.my_pos = (cx, self.my_pos[1], cz)
        else:
            nx = self.my_pos[0] + dx / dist * self.step
            nz = self.my_pos[2] + dz / dist * self.step
            self.my_pos = (int(nx), self.my_pos[1], int(nz))
        return old_pos, self.my_pos, dist, yaw

# ---------------------------------------------------------------------------
# FollowHandler
# ---------------------------------------------------------------------------

class FollowHandler:
    def __init__(self, base_step=515, max_step=650, ramp=50,
                 far_dist=8000, stick_dist=150, lead=0.2):
        self.base_step = base_step
        self.max_step = max_step
        self.ramp = ramp
        self.far_dist = far_dist
        self.stick_dist = stick_dist
        self.lead = lead
        self.step = base_step
        self._last_target = None
        self._last_time = None
        self._velocity = (0.0, 0.0)

    def Zesty_reset(self):
        self.step = self.base_step
        self._last_target = None
        self._last_time = None
        self._velocity = (0.0, 0.0)

    def Zesty_track(self, target_pos, Zesty_now):
        if target_pos is None:
            return
        if self._last_target is not None and self._last_time is not None:
            dt = Zesty_now - self._last_time
            if dt > 0.01:
                vx = (target_pos[0] - self._last_target[0]) / dt
                vz = (target_pos[2] - self._last_target[2]) / dt
                if abs(vx) < 20000 and abs(vz) < 20000:
                    self._velocity = (vx, vz)
                else:
                    self._velocity = (0.0, 0.0)
        self._last_target = target_pos
        self._last_time = Zesty_now

    def Zesty_next_position(self, my_pos, target_pos, Zesty_now, dt=0.05):
        if my_pos is None or target_pos is None:
            return None
        self.Zesty_track(target_pos, Zesty_now)

        rdx = target_pos[0] - my_pos[0]
        rdz = target_pos[2] - my_pos[2]
        raw_dist = math.sqrt(rdx * rdx + rdz * rdz)

        ty = target_pos[1] if len(target_pos) > 1 else my_pos[1]
        new_y = int(my_pos[1] + (ty - my_pos[1]) * 0.35)

        if raw_dist > self.far_dist:
            vx, vz = self._velocity
            aim = (target_pos[0] + vx * self.lead, target_pos[2] + vz * self.lead)
        else:
            aim = (target_pos[0], target_pos[2])

        dx = aim[0] - my_pos[0]
        dz = aim[1] - my_pos[2]
        dist = math.sqrt(dx * dx + dz * dz)
        yaw = int(math.degrees(math.atan2(dx, dz))) if dist >= 1 else 0

        if raw_dist > self.far_dist:
            self.step = min(self.max_step, self.step + self.ramp * dt)
        else:
            self.step = self.base_step

        if dist <= self.stick_dist or dist < 1e-6:
            return (my_pos[0], new_y, my_pos[2]), raw_dist, yaw

        move = self.step if dist > self.step else dist
        nx = my_pos[0] + dx / dist * move
        nz = my_pos[2] + dz / dist * move
        return (int(nx), new_y, int(nz)), raw_dist, yaw

def Zesty_send_position(sock, addr, key, order, my_player_id, old_pos, new_pos,
                  Zesty_server_time, aim_yaw=0, speed=500, ping=90,
                  target_yrot=None, target_aim_y=None, target_aim_xz=None,
                  copy_state=None, copy_pose=None):
    """Send our new position as an unreliable C2S player-state (Cmd 2001).

    Extracted from C2S_MOVE_RUN / C2S_MOVE_LAND captures:
      * running → physx_state=0 (WALKING), physx_pose=2 (DASHING)
      * standing → physx_state=0, physx_pose=0 (STANDING)
    Rotation is the heading as a unit vector scaled by 100.
    TargetDirection is that vector without Y.
    AimRotation is the same direction as a true unit vector.
    """
    PHYSX_WALKING = 0
    PHYSX_POSE_DASHING = 4
    PHYSX_POSE_STANDING = 7
    new_pos = (int(new_pos[0]), int(new_pos[1]), int(new_pos[2]))
    old_pos = (int(old_pos[0]), int(old_pos[1]), int(old_pos[2]))
    dx = new_pos[0] - old_pos[0]
    dz = new_pos[2] - old_pos[2]
    dist = math.sqrt(dx * dx + dz * dz)
    if dist >= 1:
        ux, uz = dx / dist, dz / dist
        velocity = (int(ux * speed), 0, int(uz * speed))
        rotation = (int(ux * 100), 0, int(uz * 100))
        tdir = (int(ux * 100), int(uz * 100))
        aim = (ux, 0.0, uz)
        pose = PHYSX_POSE_DASHING
    else:
        velocity = (0, 0, 0)
        if target_aim_xz is not None or target_aim_y is not None:
            fx = float(target_aim_xz or 0)
            fz = float(target_aim_y or 0)
            n = math.sqrt(fx * fx + fz * fz)
            if n > 0:
                fx, fz = fx / n, fz / n
        else:
            fx = fz = 0.0
        if fx == 0.0 and fz == 0.0:
            rad = math.radians(aim_yaw)
            fx, fz = math.sin(rad), math.cos(rad)
        rotation = (int(fx * 100), 0, int(fz * 100))
        tdir = (int(fx * 100), int(fz * 100))
        aim = (fx, 0.0, fz)
        pose = PHYSX_POSE_STANDING
    state = PHYSX_WALKING
    if copy_state is not None:
        state = copy_state
    if copy_pose is not None and copy_pose != PHYSX_POSE_DASHING:
        pose = copy_pose
    body = Zesty_build_c2s_player_state(
        player_id=my_player_id, pos=new_pos, rot=rotation,
        tdir=tdir, vel=velocity, aim_float=aim,
        Zesty_server_time=Zesty_server_time, physx_state=state,
        physx_pose=pose, ping=ping)
    pkt = Zesty_encode_packet(CMD_PLAYER_STATE_UPLOAD, SENDOPTION_NONE, 0,
                        FLAG_ENCRYPTED, body, key, order)
    sock.sendto(pkt, addr)
    return velocity

def Zesty_send_airborne_position(sock, addr, key, order, my_player_id, pos,
                           Zesty_server_time, horizontal_vel=(0.0, 0.0),
                           yaw=0, ping=90):
    """Send Cmd 2001 with physx_state=4, physx_pose=0 — airborne.

    Extracted from C2S_MOVE_JUMP_START / C2S_MOVE_PARACHUTE_OPEN captures:
      JUMP_START      : ... 04 00 ...   (state=4, pose=0, jump byte 0)
      PARACHUTE_OPEN  : ... 04 00 ...   (state=4, pose=0, jump byte 0)

    So the airborne trigger is state=4, not a jump flag. This is what makes
    the server accept jump and parachute phases; without it the bot appears
    to be running in mid-air and gets snapped back to the ground.
    """
    PHYSX_STATE_JUMPING = 4
    PHYSX_POSE_STANDING = 0

    new_pos = (int(pos[0]), int(pos[1]), int(pos[2]))
    vx, vz = horizontal_vel
    speed = math.sqrt(vx * vx + vz * vz)

    if speed > 1:
        ux, uz = vx / speed, vz / speed
        velocity = (int(ux * speed), 0, int(uz * speed))
        rotation = (int(ux * 100), 0, int(uz * 100))
        tdir = (int(ux * 100), int(uz * 100))
        aim = (ux, 0.0, uz)
    elif yaw:
        rad = math.radians(yaw)
        fx, fz = math.sin(rad), math.cos(rad)
        velocity = (0, 0, 0)
        rotation = (int(fx * 100), 0, int(fz * 100))
        tdir = (int(fx * 100), int(fz * 100))
        aim = (fx, 0.0, fz)
    else:
        velocity = (0, 0, 0)
        rotation = (0, 0, 0)
        tdir = (0, 0)
        aim = (0.0, 0.0, 1.0)

    body = Zesty_build_c2s_player_state(
        player_id=my_player_id, pos=new_pos, rot=rotation,
        tdir=tdir, vel=velocity, aim_float=aim,
        Zesty_server_time=Zesty_server_time,
        physx_state=PHYSX_STATE_JUMPING,
        physx_pose=PHYSX_POSE_STANDING,
        ping=ping)
    pkt = Zesty_encode_packet(CMD_PLAYER_STATE_UPLOAD, SENDOPTION_NONE, 0,
                        FLAG_ENCRYPTED, body, key, order)
    sock.sendto(pkt, addr)
    return velocity

# ---------------------------------------------------------------------------
# GRI Zesty_sync (Cmd 1901)
# ---------------------------------------------------------------------------

CMD_GRI_SYNC = 1901

def Zesty_parse_gri_block(body):
    if body is None or len(body) < 2:
        return {}
    block_len = struct.unpack_from("<H", body, 0)[0]
    p = 2
    end = min(2 + block_len, len(body))
    fields = {}
    while p < end:
        field_id = body[p]; p += 1
        if p >= end:
            break
        try:
            value, p = _Zesty_rd_varint(body, p)
        except (IndexError, ValueError):
            break
        fields[field_id] = value
    return fields

GRI_FIELD_ROUND = 2
GRI_FIELD_PHASE = 3

PHASE_PREPARE = 1
PHASE_FIGHT = 3
PHASE_ROUND_END = 5
PHASE_NAMES = {1: "PREPARE", 2: "phase2", 3: "FIGHT", 4: "phase4",
               5: "ROUND_END"}

def Zesty_get_match_phase(body):
    fields = Zesty_parse_gri_block(body)
    if GRI_FIELD_PHASE not in fields:
        return None
    value = fields[GRI_FIELD_PHASE]
    if value < 0x10000:
        return None
    phase = (value >> 16) & 0xFFFF
    start = (value >> 32) & 0xFFFFFFFF
    end = value & 0xFFFF
    return phase, fields.get(GRI_FIELD_ROUND), start, end

# ---------------------------------------------------------------------------
# Cmd 2012 - UDP_PLAYER_STATE_SYNC_V2
# ---------------------------------------------------------------------------

CMD_PLAYER_STATE_V2 = 2012
PLAYER_RECORD_SIZE = 20

CMD_SYNC_SERVER_TIME = 2000
SERVER_TICKS_PER_SECOND = 30.0

class ServerClock:
    def __init__(self):
        self.base_tick = None
        self.base_local = None
        self.phase = 0
        self.rate = SERVER_TICKS_PER_SECOND

    def Zesty_sync(self, tick, phase, Zesty_now):
        if self.base_tick is not None and self.base_local is not None:
            dt = Zesty_now - self.base_local
            dtick = tick - self.base_tick
            if dt > 0.5 and 0 < dtick < 10000:
                measured = dtick / dt
                self.rate = self.rate * 0.7 + measured * 0.3
        self.base_tick = tick
        self.base_local = Zesty_now
        self.phase = phase

    def Zesty_now(self, Zesty_now):
        if self.base_tick is None:
            return 0
        elapsed = Zesty_now - self.base_local
        ticks = self.base_tick + elapsed * self.rate
        return int(ticks * 1000.0 / self.rate) & 0xFFFFFFFF

def Zesty_decode_server_time(body):
    if body is None or len(body) < 1:
        return None
    try:
        tick, p = _Zesty_rd_varint(body, 0)
        phase = body[p] if p < len(body) else 0
    except (IndexError, ValueError):
        return None
    return tick, phase

def Zesty_build_server_time_ack(tick):
    o = bytearray()
    _Zesty_put_varint(o, tick & 0xFFFFFFFF)
    return bytes(o)

def Zesty_decode_players_v2(body):
    players = {}
    if body is None or len(body) < 4:
        return players
    p = 2
    while p < len(body) - 1:
        try:
            short_id = body[p]; p += 1
            x, p = _Zesty_rd_varint(body, p)
            y, p = _Zesty_rd_varint(body, p)
            z, p = _Zesty_rd_varint(body, p)
            vx, p = _Zesty_rd_varint(body, p)
            vy, p = _Zesty_rd_varint(body, p)
            vz, p = _Zesty_rd_varint(body, p)
            yrot = body[p]; p += 1
            aim_y = body[p]; p += 1
            aim_xz = body[p]; p += 1
            physx_state = body[p]; p += 1
            physx_pose = body[p]; p += 1
            platform, p = _Zesty_rd_varint(body, p)
            custom = body[p]; p += 1
        except (IndexError, ValueError):
            break
        pos = (_Zesty_zag(x), _Zesty_zag(y), _Zesty_zag(z))
        if not (1 <= short_id <= 64) or any(abs(v) > 4000000 for v in pos):
            break
        players[short_id] = {
            "pos": pos,
            "vel": (_Zesty_zag(vx), _Zesty_zag(vy), _Zesty_zag(vz)),
            "yrot": yrot, "aim_y": aim_y, "aim_xz": aim_xz,
            "physx_state": physx_state, "physx_pose": physx_pose,
            "platform": platform, "custom": custom,
        }
    return players

# ---------------------------------------------------------------------------
# Cmd 551 - QUICK_CHAT
# ---------------------------------------------------------------------------

CMD_QUICK_CHAT = 551
QUICK_CHAT_FOLLOW_ME = 1
QUICK_CHAT_HELP_ME = 2
QUICK_CHAT_NAMES = {1: "follow me", 2: "help me"}

QUICK_CHAT_FOLLOW_TRIGGERS = (QUICK_CHAT_FOLLOW_ME, QUICK_CHAT_HELP_ME)

def Zesty_decode_quick_chat(body):
    if body is None or len(body) < 3:
        return None
    try:
        p = 0
        chat_id, p = _Zesty_rd_varint(body, p)
        _item_id, p = _Zesty_rd_varint(body, p)
        sender, p = _Zesty_rd_varint(body, p)
    except (IndexError, ValueError):
        return None
    return chat_id, sender & 0xFF, sender, (sender >> 24) & 0xFF

# ---------------------------------------------------------------------------
# PlayerFollower (secondary follower - used in Zesty_handler_full)
# ---------------------------------------------------------------------------

class PlayerFollower:
    def __init__(self, step=200, resync_dist=400000):
        self.step = step
        self.resync_dist = resync_dist
        self.target_short = None
        self.target_pos = None
        self.my_player_id = None
        self.my_short = None
        self.my_pos = None
        self.last_yaw = 0
        self.roster = {}
        self.target_yrot = 0
        self.target_aim_y = 0
        self.target_aim_xz = 0
        self.target_seen_at = None
        self.target_vel = (0.0, 0.0)
        self.target_state = 0
        self.target_pose = 0

    def Zesty_add_player(self, full_player_id, name):
        self.roster[full_player_id & 0xFF] = (full_player_id, name)

    def Zesty_set_me(self, full_player_id):
        self.my_player_id = full_player_id
        self.my_short = full_player_id & 0xFF

    def Zesty_on_quick_chat(self, chat_id, sender_short_id):
        if chat_id not in QUICK_CHAT_FOLLOW_TRIGGERS:
            return False
        if self.my_short is not None and sender_short_id == self.my_short:
            return False
        if sender_short_id != self.target_short:
            self.target_pos = None
        self.target_vel = (0.0, 0.0)
        self.target_seen_at = None
        self.target_short = sender_short_id
        return True

    def Zesty_on_players(self, players):
        if self.target_short is None or self.target_short not in players:
            return
        t = players[self.target_short]
        prev_pos = self.target_pos
        prev_seen = self.target_seen_at
        self.target_pos = t["pos"]
        self.target_seen_at = time.time()
        if prev_pos is not None and prev_seen is not None:
            dt = self.target_seen_at - prev_seen
            if 0.01 < dt < 2.0:
                vx = (self.target_pos[0] - prev_pos[0]) / dt
                vz = (self.target_pos[2] - prev_pos[2]) / dt
                if abs(vx) < 30000 and abs(vz) < 30000:
                    self.target_vel = (vx, vz)
        self.target_yrot = t["yrot"]
        self.target_aim_y = t["aim_y"]
        self.target_aim_xz = t["aim_xz"]
        self.target_state = t.get("physx_state", self.target_state)
        self.target_pose = t.get("physx_pose", self.target_pose)

    def Zesty_predicted_target(self, Zesty_now, max_coast=3.0):
        if self.target_pos is None:
            return None
        if self.target_seen_at is None:
            return self.target_pos
        gap = Zesty_now - self.target_seen_at
        if gap <= 0.05 or gap > max_coast:
            return self.target_pos
        vx, vz = self.target_vel
        return (int(self.target_pos[0] + vx * gap),
                self.target_pos[1],
                int(self.target_pos[2] + vz * gap))

    def Zesty_set_my_position(self, pos):
        if self.my_pos is None:
            self.my_pos = pos
            return
        dx = pos[0] - self.my_pos[0]
        dz = pos[2] - self.my_pos[2]
        if math.sqrt(dx * dx + dz * dz) > self.resync_dist:
            self.my_pos = pos

    def Zesty_step_toward_target(self):
        if self.target_pos is None or self.my_pos is None:
            return None
        old_pos = self.my_pos
        dx = self.target_pos[0] - self.my_pos[0]
        dz = self.target_pos[2] - self.my_pos[2]
        dist = math.sqrt(dx * dx + dz * dz)
        if dist >= 1:
            self.last_yaw = int(math.degrees(math.atan2(dx, dz)))
        yaw = self.last_yaw
        if dist <= self.step:
            self.my_pos = (self.target_pos[0], self.my_pos[1], self.target_pos[2])
        else:
            nx = self.my_pos[0] + dx / dist * self.step
            nz = self.my_pos[2] + dz / dist * self.step
            self.my_pos = (int(nx), self.my_pos[1], int(nz))
        return old_pos, self.my_pos, dist, yaw

"""
Match session: a layered rewrite of the follow bot.
"""

