# ==================== STATE ====================
class BotState:
    def __init__(self):
        self.accounts: Dict[str, dict] = {}
        self.account_credentials: Dict[str, dict] = {}
        self.account_workers: Dict[str, asyncio.Task] = {}
        self.auth_to_game_id: Dict[str, str] = {}
        self.game_to_auth_id: Dict[str, str] = {}
        self.account_token_map: Dict[str, str] = {}
        self.paused: set = set()
        self.writers: Dict[str, list] = {}
        self.logs: List[dict] = []
        self.total_matches = 0
        self.matches_started = 0
        self.total_exp_gained = 0
        self.create_progress: List[str] = []
        self.creating = False
        self.start_time = time.time()
        self._writer_lock = asyncio.Lock()
        self._clan_cache = {}

    def Zesty_log(self, msg, level="info"):
        try:
            t = datetime.now().strftime("%H:%M:%S")
            self.logs.append({"t": time.time(), "time": t, "message": str(msg), "level": level})
            if len(self.logs) > 500:
                self.logs = self.logs[-500:]
        except Exception:
            pass

    def Zesty_register_account(self, uid, nickname, region="BD", level=1, exp=0,
                         likes=0, token=None, auth_uid=None):
        uid = str(uid)
        existing = self.accounts.get(uid, {})
        _ps = getattr(self, "_persisted_account_stats", {}).get(uid, {})
        self.accounts[uid] = {
            "uid": uid, "nickname": nickname, "region": region,
            "level": level, "exp": exp, "likes": likes,
            "token": token, "auth_uid": auth_uid,
            "status": "ONLINE",
            "current_exp": exp,
            "initial_exp": existing.get("initial_exp", _ps.get("initial_exp", exp)),
            "gained_exp": existing.get("gained_exp", _ps.get("gained_exp", 0)),
            "matches": existing.get("matches", _ps.get("matches", 0)),
            "active_matches": 0,
            "uptime_seconds": existing.get("uptime_seconds", 0),
            "last_match_time": existing.get("last_match_time", _ps.get("last_match_time", "Running...")),
            "Zesty_is_paused": False,
        }

    def Zesty_update_status(self, uid, status, matches=0):
        uid = str(uid)
        if uid in self.accounts:
            self.accounts[uid]["status"] = status
            self.accounts[uid]["active_matches"] = matches
            self.accounts[uid]["Zesty_is_paused"] = (status == "PAUSED")

    def Zesty_update_exp(self, uid, exp, level=None):
        uid = str(uid)
        if uid in self.accounts:
            a = self.accounts[uid]
            old = a.get("current_exp", 0)
            if exp > old:
                a["gained_exp"] = a.get("gained_exp", 0) + (exp - old)
                self.total_exp_gained += (exp - old)
            a["current_exp"] = exp
            a["exp"] = exp
            if level: a["level"] = level

    def Zesty_increment_match(self, uid):
        self.total_matches += 1
        uid = str(uid)
        if uid in self.accounts:
            self.accounts[uid]["matches"] = self.accounts[uid].get("matches", 0) + 1
            self.accounts[uid]["last_match_time"] = datetime.now().strftime("%H:%M:%S")

    def Zesty_increment_match_started(self):
        self.matches_started += 1

    def Zesty_register_writer(self, uid, w):
        self.writers.setdefault(str(uid), []).append(w)

    def Zesty_unregister_writer(self, uid, w):
        try: self.writers.get(str(uid), []).remove(w)
        except Exception: pass

    def Zesty_close_writers_for_account(self, uid):
        for w in list(self.writers.get(str(uid), [])):
            try: w.close()
            except Exception: pass
        self.writers[str(uid)] = []

    def Zesty_is_paused(self, uid):
        return str(uid) in self.paused

    def Zesty_toggle_pause(self, uid, state):
        uid = str(uid)
        if state:
            self.paused.add(uid)
            if uid in self.accounts:
                self.accounts[uid]["Zesty_is_paused"] = True
                self.accounts[uid]["status"] = "PAUSED"
        else:
            self.paused.discard(uid)
            if uid in self.accounts:
                self.accounts[uid]["Zesty_is_paused"] = False
                if self.accounts[uid].get("status") == "PAUSED":
                    self.accounts[uid]["status"] = "ONLINE"

bot_state = BotState()

def _Zesty_save_stats():
    """Persist match history to disk before restart."""
    try:
        data = {
            "total_matches": bot_state.total_matches,
            "matches_started": bot_state.matches_started,
            "total_exp_gained": bot_state.total_exp_gained,
            "accounts": {
                uid: {
                    "matches": a.get("matches", 0),
                    "gained_exp": a.get("gained_exp", 0),
                    "initial_exp": a.get("initial_exp", 0),
                    "last_match_time": a.get("last_match_time", ""),
                }
                for uid, a in bot_state.accounts.items()
            }
        }
        with open(STATS_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f)
    except Exception as e:
        Zesty_print_warning(f"[STATS] save failed: {e}")

def _Zesty_load_stats():
    """Load persisted match history into bot_state on startup."""
    try:
        if not os.path.exists(STATS_FILE):
            return
        with open(STATS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        bot_state.total_matches   = int(data.get("total_matches", 0))
        bot_state.matches_started = int(data.get("matches_started", 0))
        bot_state.total_exp_gained = int(data.get("total_exp_gained", 0))
        # Merge per-account history — will be applied when account registers
        bot_state._persisted_account_stats = data.get("accounts", {})
        Zesty_print_success(f"[STATS] Loaded history: {bot_state.total_matches} matches, "
                             f"{bot_state.total_exp_gained} exp")
    except Exception as e:
        Zesty_print_warning(f"[STATS] load failed: {e}")


# ==================== FULL SCRIPT RESTART ====================
RESTART_MARKER = "restart.marker"
STATS_FILE = "Zesty_stats.json"  # persists match history across restarts
_group_match_done: Dict[str, int] = {}
_group_launched:   Dict[str, int] = {}  # matches launched per group
_group_restart_lock = asyncio.Lock()
_restart_scheduled: Dict[str, bool] = {}

# ==================== MATCH START WATCHDOG ====================
# If no 0300 (match found) is observed for this many seconds across the group,
# the WHOLE process restarts. Default 20 min — app.py overrides at startup.
MATCH_START_WATCHDOG = 20 * 60  # 1200 seconds
_group_last_match_start: Dict[str, float] = {}
_group_in_match: Dict[str, bool] = {}
_watchdog_tasks: Dict[str, asyncio.Task] = {}

def _Zesty_full_script_restart(reason: str = ""):
    """Nuclear option: kill and replace the whole Python process."""
    _Zesty_save_stats()
    try:
        with open(RESTART_MARKER, "w", encoding="utf-8") as f:
            f.write(f"{datetime.now().isoformat()} | {reason}\n")
    except Exception:
        pass
    Zesty_print_warning("=" * 60)
    Zesty_print_warning(f"[RESTART] FULL SCRIPT RESTART")
    Zesty_print_warning(f"[RESTART] reason: {reason}")
    Zesty_print_warning(f"[RESTART] exec: {sys.executable} {' '.join(sys.argv)}")
    Zesty_print_warning("=" * 60)
    try:
        sys.stdout.flush()
        sys.stderr.flush()
    except Exception:
        pass
    time.sleep(0.8)
    # On Railway/containers os.execv doesn't reload properly.
    # sys.exit(0) triggers Railway's "always" restart policy cleanly.
    try:
        os.execv(sys.executable, [sys.executable] + sys.argv)
    except Exception:
        pass
    # Fallback: clean exit so Railway/supervisor restarts us
    try: sys.exit(0)
    except SystemExit: raise
    except Exception: os._exit(0)

async def _Zesty_on_match_complete(group_id: str, uid: str):
    """Count completions. Restart after HowManyMatch when not unlimited."""
    gid = str(group_id or "default")
    _group_in_match[gid] = False
    _group_last_match_start[gid] = time.time()
    async with _group_restart_lock:
        _group_match_done[gid] = _group_match_done.get(gid, 0) + 1
        count  = _group_match_done[gid]
        already = _restart_scheduled.get(gid, False)
    Zesty_print_warning(
        f"[MATCH] {uid} → group {gid}: {count} completed "
        f"(limit={HowManyMatch} unlimited={UnlimitedMatch})"
    )
    if UnlimitedMatch:
        # Keep launching indefinitely — never restart
        return
    if count >= HowManyMatch and not already:
        async with _group_restart_lock:
            _restart_scheduled[gid] = True
        Zesty_print_warning(
            f"[RESTART] group {gid}: {count}/{HowManyMatch} target reached → restarting"
        )
        asyncio.create_task(_Zesty_wait_and_restart_group(gid))

async def _Zesty_wait_and_restart_group(group_id: str):
    """Wait for in-flight matches to drain (up to 60s), then restart."""
    gid = str(group_id or "default")
    deadline = time.time() + 60
    while time.time() < deadline:
        async with _group_restart_lock:
            count = _group_match_done.get(gid, 0)
        if count >= HowManyMatch:
            break
        await asyncio.sleep(2.0)
    async with _group_restart_lock:
        final = _group_match_done.get(gid, 0)
    _Zesty_full_script_restart(
        reason=f"group {gid}: {final}/{HowManyMatch} matches completed"
    )

# ==================== MATCH START WATCHDOG ====================
def _Zesty_on_match_start(group_id: str, uid: str):
    """Called the instant a 0300 (match found) packet arrives for any bot."""
    gid = str(group_id or "default")
    _group_last_match_start[gid] = time.time()
    _group_in_match[gid] = True
    Zesty_print_info(f"[WATCHDOG] {uid} → group {gid}: timer Zesty_reset (match started)")

async def _Zesty_watchdog_loop(group_id: str):
    """Restart the whole script if no match starts within MATCH_START_WATCHDOG."""
    gid = str(group_id or "default")
    _group_last_match_start.setdefault(gid, time.time())
    try:
        while True:
            await asyncio.sleep(30)
            # Skip while a match is actively running
            if _group_in_match.get(gid, False):
                continue
            last = _group_last_match_start.get(gid, 0.0)
            if last <= 0:
                _group_last_match_start[gid] = time.time()
                continue
            idle = time.time() - last
            if idle >= MATCH_START_WATCHDOG:
                Zesty_print_warning(
                    f"[WATCHDOG] group {gid}: no match started for {idle:.0f}s "
                    f"(≥ {MATCH_START_WATCHDOG:.0f}s) → FULL SCRIPT RESTART"
                )
                _Zesty_full_script_restart(
                    reason=f"watchdog: group {gid} no match start for {int(idle)}s"
                )
                return
    except asyncio.CancelledError:
        raise
    except Exception as e:
        Zesty_print_error(f"[WATCHDOG] Zesty_loop error: {e}")

def _Zesty_ensure_watchdog(group_id: str):
    """Start (or confirm running) the watchdog task for this group."""
    gid = str(group_id or "default")
    if gid in _watchdog_tasks and not _watchdog_tasks[gid].done():
        return
    _group_last_match_start.setdefault(gid, time.time())
    _group_in_match.setdefault(gid, False)
    _watchdog_tasks[gid] = asyncio.create_task(_Zesty_watchdog_loop(gid))
    Zesty_print_info(f"[WATCHDOG] armed for group {gid} (timeout {MATCH_START_WATCHDOG:.0f}s)")

# ==================== PER-GROUP TEAM STATE ====================
_team_states: Dict[str, dict] = {}
_team_states_lock = asyncio.Lock()

def Zesty_get_team_state(group_id: str) -> dict:
    gid = str(group_id or "default")
    if gid not in _team_states:
        _team_states[gid] = {
            "peers": {},
            "leader_uid": None,
            "team_code": None,
            "lock": asyncio.Lock(),
        }
    return _team_states[gid]

def Zesty_drop_team_state(group_id: str):
    gid = str(group_id or "default")
    ts = _team_states.get(gid)
    if ts and not ts["peers"]:
        _team_states.pop(gid, None)

# ==================== PRINT HELPERS ====================
class C:
    GREEN='\033[92m'; FAIL='\033[91m'; WARNING='\033[93m'
    CYAN='\033[96m'; MAGENTA='\033[95m'; WHITE='\033[97m'; ENDC='\033[0m'

def Zesty_print_success(t): print(f"{C.GREEN}[+] {t}{C.ENDC}"); bot_state.Zesty_log(t, "success")
def Zesty_print_error(t):   print(f"{C.FAIL}[-] {t}{C.ENDC}");   bot_state.Zesty_log(t, "error")
def Zesty_print_warning(t): print(f"{C.WARNING}[!] {t}{C.ENDC}"); bot_state.Zesty_log(t, "warning")
def Zesty_print_info(t):    print(f"{C.CYAN}[i] {t}{C.ENDC}");   bot_state.Zesty_log(t, "info")

GGRE_RAW = bytes.fromhex(
    "47475245010101006d020000b260ee08e1f86b4c57f9c70f86bba26ed5d1436bcf52e142db3249d905eded757764991ca31a8373cdd26eab91b80f3f1f6f262f4f10b895d7b6937ddba30a27197453890e9da49373f736c679b8254e2f8e1623e91084a5fdd5374fe478ff99e010834553fddeb0bec4018d142e49df9bb236675b67e852f92a43586f7a7d4d0d7a197a1d4da32714dab4d069ad53214e2c33b3877420a12459738c4c619cbd815fa878bbd104776bb3e1ac7818d5397b04a666ac57f682763ff2df31bc2f846ddc7904f3dce1bda0c4b01f9698e9166f98c84f92640abe3f6317834a42e5c12573b46842c1a6ea8fe6ca9c006dca48a2087e1f983dfb5692771e4a0b15b337ad669b1d08b40862b176bace5331b49a767375b1a8469012aa70a67b55fe71b72478201d0b3ac7269c064c960361e92ee7ba8a42cc6b582bf9b965fb388fa9172ad44c4b073ac23c02080a6bcd106b691ffdf4c7cf71e42f2063fcf196e9bddc5e85be1fe5048eb1b31b460efbb46d76195eef9904c4cba326f2e17ff51fec17dd965aa06dadd4ab07d6966e4a7c38e8afd66dfde56c872bb87516a8f7313c797e4d80e5ad4a5f7afad95c1e0449254adae052e71a3fb98399f93ab30848e0d23252dd45e6fd41bc5fa7303dfb846a8fd713a0032a0b0ae96dfba1bbe41d20abd8099e2cb7fccc329d25bd153029139ef05d090a5093ea557693c0a8d491395b8a23ca844b3887dd5dfc29ac06f4b9be87883a793211b973465e2644c4f5de02b8ab01571401203fc2740423826858cc6da0194c195d27aac4ec4b9d23d506c1501d06440aca3fc180926d75d4a004d3dff21eb4ea1e8c86e6c9627248eff953e1d192d5c8efc006a7e512388ef2ebdb72ee3ad42d719f28e8f994e12ebf4c79f2ffe3abd7408ccd2236a7b89b2606247a732c10c4"
)

def _Zesty_encode_proto_std(fields):
    out = b""
    for f in sorted(fields.keys()):
        v = fields[f]
        if isinstance(v, bool):
            out += Zesty_encode_varint((f << 3) | 0) + Zesty_encode_varint(int(v))
        elif isinstance(v, int):
            out += Zesty_encode_varint((f << 3) | 0) + Zesty_encode_varint(v)
        elif isinstance(v, (str, bytes)):
            if isinstance(v, str): v = v.encode()
            out += Zesty_encode_varint((f << 3) | 2) + Zesty_encode_varint(len(v)) + v
    return out

async def Zesty_major_register(release_v, access_token, open_id, name, game_version,
                          login_url, lang_code="en"):
    field14 = bytes(ord(c) ^ KEYSTREAM[i % 32] for i, c in enumerate(open_id))
    fields = {
        1: name, 2: access_token, 3: open_id,
        5: 102000007, 6: 4, 7: 1, 13: 1, 14: field14, 15: lang_code,
        16: 2, 20: game_version, 21: 1, 22: GGRE_RAW,
    }
    proto = _Zesty_encode_proto_std(fields)
    payload = AES.new(AES_KEY, AES.MODE_CBC, AES_IV).encrypt(pad(proto, 16))
    url = f"{login_url.rstrip('/')}/MajorRegister"
    hdrs = {
        "Accept": "*/*", "Authorization": "Bearer ",
        "Content-Type": "application/x-www-form-urlencoded",
        "ReleaseVersion": f"{release_v}",
        "User-Agent": "UnityPlayer/2018.4.12f1 (UnityWebRequest/1.0, libcurl/8.5.0-DEV)",
        "X-GA": "v1 1", "X-GA-SV": str(int(time.time())),
        "X-Unity-Version": "2018.4.12f1",
    }
    try:
        ssl_ctx = ssl.create_default_context()
        ssl_ctx.check_hostname = False; ssl_ctx.verify_mode = ssl.CERT_NONE
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=30)) as s:
            async with s.post(url, headers=hdrs, data=payload, ssl=ssl_ctx) as resp:
                content = await resp.read()
                Zesty_print_info(f"[MAJOR-REG] status={resp.status} len={len(content)}")
                if resp.status != 200 or not content: return None
                for off in [0, 64, 48, 32, 16]:
                    if off >= len(content): continue
                    try:
                        r = Zesty_decode_protobuf_2(content[off:])
                        if r and 3 in r:
                            Zesty_print_success(f"[MAJOR-REG] decoded at offset {off}")
                            return {str(k): {"data": v} for k, v in r.items()}
                    except Exception: pass
                if len(content) % 16 == 0:
                    try:
                        pt = AES.new(AES_KEY, AES.MODE_CBC, AES_IV).decrypt(content)
                        pad_len = pt[-1]
                        if 1 <= pad_len <= 16 and all(b == pad_len for b in pt[-pad_len:]):
                            pt = pt[:-pad_len]
                        r = Zesty_decode_protobuf_2(pt)
                        if r and 3 in r:
                            Zesty_print_success(f"[MAJOR-REG] decrypted")
                            return {str(k): {"data": v} for k, v in r.items()}
                    except Exception: pass
                return None
    except Exception as e:
        Zesty_print_error(f"[MAJOR-REG] {e}"); return None

# ==================== CLAN INFO ====================
def _Zesty_enc_clan_req(clan_id: int) -> Optional[bytes]:
    try:
        msg = infoClan_pb2.GuildReq()
        msg.guildId = int(clan_id)
        msg.garena = 1
        raw = msg.SerializeToString()
        return AES.new(AES_KEY, AES.MODE_CBC, AES_IV).encrypt(pad(raw, AES.block_size))
    except Exception as e:
        Zesty_print_error(f"[CLAN-ENC] {e}")
        return None

def _Zesty_decode_repeated(data: bytes) -> list:
    results = []
    offset = 0
    data_len = len(data)
    while offset < data_len:
        header, offset = Zesty_decode_varint(data, offset)
        if header is None: break
        fn = header >> 3; wt = header & 0x7
        if wt == 2:
            length, offset = Zesty_decode_varint(data, offset)
            if length is None: break
            value = data[offset:offset+length]; offset += length
            if fn == 1:
                nested = Zesty_decode_protobuf_2(value)
                results.append(nested)
        elif wt == 0:
            _, offset = Zesty_decode_varint(data, offset)
        elif wt == 1: offset += 8
        elif wt == 5: offset += 4
        else: break
    return results

async def Zesty_get_clan_info(jwt_token: str, clan_id: str) -> Optional[Dict]:
    if not _CLAN_PB_AVAILABLE:
        return None

    payload = _Zesty_enc_clan_req(int(clan_id))
    if not payload:
        return None

    ssl_ctx = ssl.create_default_context()
    ssl_ctx.check_hostname = False
    ssl_ctx.verify_mode = ssl.CERT_NONE

    hdrs_main = {
        "User-Agent":      "UnityPlayer/2022.3.47f1 (UnityWebRequest/1.0, libcurl/8.5.0-DEV)",
        "Accept":          "*/*",
        "Accept-Encoding": "deflate, gzip",
        "Authorization":   f"Bearer {jwt_token}",
        "Content-Type":    "application/x-www-form-urlencoded",
        "X-GA":            "v1 1",
        "X-GA-SV":         str(int(time.time())),
        "ReleaseVersion":  "OB55",
        "X-Unity-Version": "2022.3.47f1",
        "Host":            "clientbp.ppmainecoonghj.com",
    }
    hdrs_members = {**hdrs_main,
        "User-Agent":      "UnityPlayer/2018.4.12f1 (UnityWebRequest/1.0, libcurl/8.5.0-DEV)",
        "X-Unity-Version": "2018.4.12f1",
    }

    try:
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=10)) as s:
            clan_info_result = {}
            async with s.post(
                "https://clientbp.ppmainecoonghj.com/GetClanMainPageInfo",
                headers=hdrs_main, data=payload, ssl=ssl_ctx
            ) as r:
                if r.status == 200:
                    binary = await r.read()
                    if binary and len(binary) >= 10:
                        raw = Zesty_decode_protobuf_2(binary)
                        guild = raw.get(1, {})
                        if isinstance(guild, dict):
                            clan_info_result = {
                                "clan_id":      int(guild.get(1, int(clan_id)) or int(clan_id)),
                                "clan_name":    str(guild.get(2, "") or ""),
                                "leader_uid":   int(guild.get(4, 0) or 0),
                                "region":       str(guild.get(13, "") or ""),
                                "level":        int(guild.get(5, 0) or 0),
                                "capacity":     int(guild.get(6, 0) or 0),
                                "member_count": int(guild.get(7, 0) or 0),
                                "honor_points": int(guild.get(39, 0) or 0),
                                "weekly_glory": int(guild.get(37, 0) or 0),
                                "total_glory":  int(guild.get(36, 0) or 0),
                            }

            members = []
            async with s.post(
                "https://clientbp.ppmainecoonghj.com/GetClanMembers",
                headers=hdrs_members, data=payload, ssl=ssl_ctx
            ) as r:
                if r.status == 200:
                    binary = await r.read()
                    if binary and len(binary) >= 10:
                        members_list = _Zesty_decode_repeated(binary)
                        for m in members_list:
                            if not isinstance(m, dict):
                                continue
                            try:
                                basic    = m.get(1, {})
                                if not isinstance(basic, dict): basic = {}
                                uid      = int(basic.get(1, 0) or 0)
                                nickname = str(basic.get(3, "") or "")
                                region   = str(basic.get(5, "") or "")
                                level    = int(basic.get(6, 0) or 0)
                                role_v   = int(m.get(4, 1) or 1)
                                weekly   = int(m.get(11, 0) or 0)
                                total    = int(m.get(10, 0) or 0)
                                role     = {3:"leader", 2:"co-leader", 1:"member"}.get(role_v, "member")
                                if uid:
                                    members.append({
                                        "uid":          uid,
                                        "nickname":     nickname,
                                        "level":        level,
                                        "region":       region,
                                        "weekly_glory": weekly,
                                        "total_glory":  total,
                                        "role":         role,
                                    })
                            except Exception as e:
                                Zesty_print_warning(f"[CLAN-MEMBER] {e}")
                                continue
                        members.sort(key=lambda x: x["weekly_glory"], reverse=True)

        if not clan_info_result:
            clan_info_result = {
                "clan_id":      int(clan_id),
                "clan_name":    "",
                "leader_uid":   0,
                "region":       "BD",
                "level":        0,
                "capacity":     0,
                "member_count": len(members),
                "honor_points": 0,
                "weekly_glory": 0,
                "total_glory":  0,
                "has_bot":      False,
                "bot_count":    0,
                "bots":         [],
            }

        bot_uids = set()
        try:
            teams = Zesty_load_all_team_files()
            for t in teams:
                if str(t["clan_id"]) == str(clan_id):
                    for a in t["accounts"]:
                        auth_uid = str(a["uid"])
                        game_uid = bot_state.auth_to_game_id.get(auth_uid, auth_uid)
                        try:
                            bot_uids.add(int(game_uid))
                        except Exception:
                            pass
        except Exception:
            pass

        bots_list = []
        for m in members:
            if m["uid"] in bot_uids:
                m["is_bot"] = True
                bots_list.append({
                    "uid":          m["uid"],
                    "nickname":     m["nickname"],
                    "level":        m["level"],
                    "region":       m["region"],
                    "role":         m["role"],
                    "weekly_glory": m["weekly_glory"],
                    "total_glory":  m["total_glory"],
                })
            else:
                m["is_bot"] = False

        clan_info_result["has_bot"] = len(bots_list) > 0
        clan_info_result["bot_count"] = len(bots_list)
        clan_info_result["bots"] = bots_list
        clan_info_result["member_count"] = len(members) or clan_info_result["member_count"]

        Zesty_print_success(
            f"[CLAN] {clan_info_result.get('clan_name')} | "
            f"Lvl {clan_info_result.get('level')} | "
            f"{clan_info_result['member_count']}/{clan_info_result.get('capacity')} | "
            f"Bots {len(bots_list)} | "
            f"Total Glory {clan_info_result.get('total_glory',0):,} "
            f"(Week {clan_info_result.get('weekly_glory',0):,})"
        )
        return clan_info_result

    except Exception as e:
        Zesty_print_error(f"[CLAN-INFO] {e}")
        return None

# ==================== TEAM FILE STORAGE ====================
def _Zesty_generate_group_id() -> str:
    return f"{random.randint(10000000, 99999999)}"

def _Zesty_team_file_path(group_id: str) -> str:
    safe_id = re.sub(r'[^0-9A-Za-z_]', '', str(group_id))
    return os.path.join(TEAMS_DIR, f"squad_{safe_id}.json")

def Zesty_save_team_file(clan_id: str, region: str, accounts: List[Dict],
                   group_id: Optional[str] = None) -> Optional[str]:
    try:
        os.makedirs(TEAMS_DIR, exist_ok=True)
        if not group_id:
            for _ in range(10):
                gid = _Zesty_generate_group_id()
                if not os.path.exists(_Zesty_team_file_path(gid)):
                    group_id = gid
                    break
            else:
                group_id = _Zesty_generate_group_id()

        data = {
            "group_id": str(group_id),
            "clan_id": str(clan_id),
            "region": str(region).upper(),
            "created_at": datetime.now().isoformat(),
            "accounts": [
                {
                    "nickname": str(a.get("nickname", "")),
                    "account_id": str(a.get("account_id", "")),
                    "uid": str(a["uid"]),
                    "password": str(a["password"]),
                }
                for a in accounts
            ],
        }
        path = _Zesty_team_file_path(group_id)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2)
        Zesty_print_success(f"[TEAM-FILE] Saved {path} ({len(accounts)} accounts)")
        return str(group_id)
    except Exception as e:
        Zesty_print_error(f"[TEAM-FILE] save error: {e}")
        return None

def Zesty_load_all_team_files() -> List[Dict]:
    teams = []
    if not os.path.isdir(TEAMS_DIR):
        return teams
    for fname in sorted(os.listdir(TEAMS_DIR)):
        if not fname.endswith(".json"):
            continue
        path = os.path.join(TEAMS_DIR, fname)
        try:
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if not isinstance(data, dict):
                continue
            clan_id = str(data.get("clan_id", "")).strip()
            group_id = str(data.get("group_id", "")).strip() or fname.replace("squad_", "").replace(".json", "")
            accounts = data.get("accounts", [])
            region = str(data.get("region", "BD")).upper()
            if not clan_id or not isinstance(accounts, list) or not accounts:
                Zesty_print_warning(f"[TEAM-FILE] Skipping malformed {fname}")
                continue
            clean_accounts = []
            for a in accounts:
                if not isinstance(a, dict):
                    continue
                u = str(a.get("uid", "")).strip()
                p = str(a.get("password", "")).strip()
                if u and p:
                    clean_accounts.append({"uid": u, "password": p})
            if not clean_accounts:
                Zesty_print_warning(f"[TEAM-FILE] No valid accounts in {fname}")
                continue
            teams.append({
                "clan_id": clan_id,
                "group_id": group_id,
                "region": region,
                "file": fname,
                "accounts": clean_accounts,
            })
            Zesty_print_info(f"[TEAM-FILE] Loaded {fname} | clan={clan_id} | group={group_id} | {len(clean_accounts)} bots")
        except Exception as e:
            Zesty_print_error(f"[TEAM-FILE] Failed to read {fname}: {e}")
    return teams

def Zesty_delete_team_file(group_id: str) -> bool:
    try:
        path = _Zesty_team_file_path(group_id)
        if os.path.exists(path):
            os.remove(path)
            Zesty_print_success(f"[TEAM-FILE] Deleted {path}")
            return True
        return False
    except Exception as e:
        Zesty_print_error(f"[TEAM-FILE] delete error: {e}")
        return False

