# ==================== CLAN ====================
def _Zesty_get_region_from_jwt(jwt_token):
    try:
        p = jwt_token.split('.')[1]
        p += '=' * (-len(p) % 4)
        d = json.loads(base64.urlsafe_b64decode(p))
        return (d.get('lock_region') or d.get('noti_region') or 'BD').upper()
    except Exception: return "BD"

def _Zesty_get_region_url(region):
    region = region.upper()
    if region == "IND": return "https://client.ind.freefiremobile.com"
    if region in ["BR","US","NA"]: return "https://client.us.freefiremobile.com"
    return "https://clientbp.ppmainecoonghj.com"

def _Zesty_create_clan_payload(clan_id):
    if not _CLAN_PB_AVAILABLE: return None
    try:
        msg = reqClan_pb2.MyMessage()
        msg.field_1 = int(clan_id)
        raw = msg.SerializeToString()
        return AES.new(AES_KEY, AES.MODE_CBC, AES_IV).encrypt(pad(raw, AES.block_size))
    except Exception as e:
        Zesty_print_error(f"[CLAN] payload: {e}"); return None

async def Zesty_join_clan(jwt_token, clan_id):
    if not _CLAN_PB_AVAILABLE:
        Zesty_print_warning("[CLAN] reqClan_pb2 not available"); return False
    try:
        region = _Zesty_get_region_from_jwt(jwt_token)
        base_url = _Zesty_get_region_url(region)
        url = base_url.rstrip("/") + "/RequestJoinClan"
        host = base_url.replace("https://","")
        payload = _Zesty_create_clan_payload(clan_id)
        if not payload: return False
        hdrs = {"Authorization":f"Bearer {jwt_token}",
            "X-Unity-Version":"2018.4.11f1","X-GA":"v1 1","ReleaseVersion":"OB55",
            "Content-Type":"application/octet-stream","Host":host,
            "Connection":"Keep-Alive","Accept-Encoding":"gzip"}
        ssl_ctx = ssl.create_default_context()
        ssl_ctx.check_hostname = False; ssl_ctx.verify_mode = ssl.CERT_NONE
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as s:
            async with s.post(url, headers=hdrs, data=payload, ssl=ssl_ctx) as r:
                if r.status == 200:
                    Zesty_print_success(f"[CLAN] ✅ Join sent for {clan_id}"); return True
                Zesty_print_warning(f"[CLAN] Join status {r.status}"); return False
    except Exception as e:
        Zesty_print_error(f"[CLAN] {e}"); return False

# ==================== TCP ====================
async def Zesty_build_tcp_startup_packet(account_id, token, Zesty_server_time, key, iv, region="BD", typ='OnLine'):
    uid_hex = f"{int(account_id):016x}"
    ts_hex = f"{int(Zesty_server_time):08x}"
    enc = (await Zesty_aes_encrypt(token.encode(), key, iv)).hex()
    enc_len = f"{len(enc)//2:08x}"
    reg = str(region).upper() if region else "BD"
    if typ == 'OnLine':
        pfx = '7219' if reg == 'BD' else ('7214' if reg == 'IND' else '7215')
        return f"{pfx}{uid_hex}{ts_hex}00000000{enc_len}{enc}"
    pfx = '8119' if reg == 'BD' else ('8114' if reg == 'IND' else '8115')
    return f"{pfx}{uid_hex}{ts_hex}{enc_len}{enc}"

async def Zesty_send_keep_alive(region="BD"):
    reg = str(region).upper() if region else "BD"
    return bytes.fromhex("0219" if reg == "BD" else ("0214" if reg == "IND" else "0215"))

# ==================== MATCH EXECUTOR ====================
import concurrent.futures as _cf
# Dedicated thread pool so parallel UDP matches don't starve each other
_Zesty_match_executor = _cf.ThreadPoolExecutor(
    max_workers=400,  # 35 per bot × 2 threads × 4 bots
    thread_name_prefix="udp_match"
)

# ==================== MATCH COUNTERS ====================
_match_counters: Dict[str, int] = {}
_match_counter_lock = asyncio.Lock()

async def _Zesty_inc_match(uid):
    async with _match_counter_lock:
        _match_counters[uid] = _match_counters.get(uid, 0) + 1
        return _match_counters[uid]

async def _Zesty_dec_match(uid):
    async with _match_counter_lock:
        if uid in _match_counters and _match_counters[uid] > 0:
            _match_counters[uid] -= 1
        return _match_counters.get(uid, 0)

async def _Zesty_get_match_count(uid):
    async with _match_counter_lock:
        return _match_counters.get(uid, 0)

# ==================== TOKEN CACHE ====================
_token_cache_memo: Dict[str, Any] = {}
_token_cache_memo_time: float = 0.0
_TOKEN_CACHE_MEMO_TTL = 5.0

def _Zesty_json_serializer(obj):
    if isinstance(obj, (bytes, bytearray)):
        return {"__bytes_hex__": bytes(obj).hex()}
    raise TypeError(f"Type {type(obj)} not serializable")

def _Zesty_json_deserializer(obj):
    if isinstance(obj, dict):
        if "__bytes_hex__" in obj and len(obj) == 1:
            try: return bytes.fromhex(obj["__bytes_hex__"])
            except Exception: return b""
        return {k: _Zesty_json_deserializer(v) for k, v in obj.items()}
    if isinstance(obj, list): return [_Zesty_json_deserializer(x) for x in obj]
    return obj

def _Zesty_load_token_cache() -> Dict[str, Any]:
    global _token_cache_memo, _token_cache_memo_time
    Zesty_now = time.time()
    if _token_cache_memo and (Zesty_now - _token_cache_memo_time) < _TOKEN_CACHE_MEMO_TTL:
        return _token_cache_memo
    if not os.path.exists(TOKEN_CACHE_FILE):
        return {}
    try:
        with open(TOKEN_CACHE_FILE,"r",encoding="utf-8") as f:
            content = f.read().strip()
        if not content: return {}
        data = json.loads(content)
        parsed = _Zesty_json_deserializer(data)
        _token_cache_memo = parsed
        _token_cache_memo_time = Zesty_now
        return parsed
    except Exception as e:
        Zesty_print_error(f"Token cache corrupt → deleting: {e}")
        try: os.remove(TOKEN_CACHE_FILE)
        except Exception: pass
        return {}

def _Zesty_save_token_cache(cache: Dict[str, Any]):
    global _token_cache_memo, _token_cache_memo_time
    try:
        tmp_file = TOKEN_CACHE_FILE + ".tmp"
        with open(tmp_file,"w",encoding="utf-8") as f:
            json.dump(cache, f, indent=2, default=_Zesty_json_serializer)
        os.replace(tmp_file, TOKEN_CACHE_FILE)
        _token_cache_memo = cache
        _token_cache_memo_time = time.time()
    except Exception as e:
        Zesty_print_error(f"Token cache save error: {e}")

def Zesty_cache_get(uid: str) -> Optional[Dict]:
    cache = _Zesty_load_token_cache()
    entry = cache.get(str(uid))
    if not entry: return None
    if time.time() - entry.get("cached_at",0) > TOKEN_CACHE_TTL:
        Zesty_print_info(f"[CACHE] UID {uid} expired. Re-login needed.")
        Zesty_cache_invalidate(uid); return None
    if str(entry.get("account_id","")).isdigit():
        entry["account_id"] = int(entry["account_id"])
    if not isinstance(entry.get("login_payload_data"), (bytes, bytearray)):
        Zesty_print_warning(f"[CACHE] UID {uid} missing payload → invalidating")
        Zesty_cache_invalidate(uid); return None
    return entry

def Zesty_cache_set(uid: str, data: Dict):
    try:
        cache = _Zesty_load_token_cache()
        entry = dict(data)
        entry["cached_at"] = time.time()
        cache[str(uid)] = entry
        _Zesty_save_token_cache(cache)
        Zesty_print_success(f"[CACHE] Saved credentials for UID {uid}")
    except Exception as e:
        Zesty_print_error(f"Zesty_cache_set error: {type(e).__name__}: {e}")

def Zesty_cache_invalidate(uid: str):
    cache = _Zesty_load_token_cache()
    if str(uid) in cache:
        del cache[str(uid)]
        _Zesty_save_token_cache(cache)
        Zesty_print_warning(f"[CACHE] Invalidated: {uid}")

# ==================== PLAY GAME ====================
async def Zesty_play_game(server_ip_port, udp_jwt, udp_key, match_code,
                    account_id, player_region, Zesty_client_version,
                    tcp_key, tcp_iv, match_index,
                    game_mode=1, map_id=1, match_mode=1, sleep_ms=0,
                    match_id=0, verbose=True, group_id="default"):
    uid_str = str(account_id)
    completed_cleanly = False
    try:
        if ":" not in server_ip_port:
            Zesty_print_error(f"[MATCH #{match_index}] bad server {server_ip_port!r}")
            return
        ip, port_s = server_ip_port.split(":", 1)
        port = int(port_s)

        Zesty_print_success(f"[MATCH #{match_index}] → Zesty_run_match {ip}:{port}")
        Zesty_print_info(f"    udp_jwt_len={len(udp_jwt) if udp_jwt else 0} "
                   f"udp_key={udp_key[:8] if udp_key else 'None'}... "
                   f"mask={match_code} mode={game_mode} map={map_id}")

        try:
            Zesty_set_base_url("https://clientbp.ppmainecoonghj.com")
        except Exception:
            pass

        Zesty_loop = asyncio.get_running_loop()

        def _Zesty_run():
            return Zesty_run_match(
                ip, port,
                int(account_id),
                udp_key,
                udp_jwt,
                match_code,
                "0",
                int(game_mode),
                int(map_id),
                int(match_mode),
                int(sleep_ms),
                3.0,
                None,
                int(match_id),
                bool(verbose),
            )

        try:
            result = await Zesty_loop.run_in_executor(_Zesty_match_executor, _Zesty_run)
        except Exception as exc:
            Zesty_print_error(f"[MATCH #{match_index}] Zesty_run_match: {exc}")
            traceback.print_exc()
        else:
            if result:
                completed_cleanly = True
                Zesty_print_success(f"[★] Match #{match_index} Finished")
            else:
                Zesty_print_warning(
                    f"[MATCH #{match_index}] handshake/join failed - slot released")
    except Exception as e:
        Zesty_print_error(f"[MATCH #{match_index}] {e}")
    finally:
        if completed_cleanly:
            try:
                bot_state.Zesty_increment_match(uid_str)
                Zesty_print_success(f"[★] Match #{match_index} Complete | UID: {uid_str}")
                async def _Zesty_post_exp(uid):
                    try:
                        for wait in (5.0, 8.0, 12.0):
                            await asyncio.sleep(wait)
                            await Zesty_refresh_account_profile(uid)
                    except Exception: pass
                asyncio.create_task(_Zesty_post_exp(uid_str))
            except Exception: pass
        remaining = await _Zesty_dec_match(uid_str)
        try:
            bot_state.Zesty_update_status(uid_str, "ONLINE" if remaining == 0 else "IN_MATCH", remaining)
        except Exception: pass
        
        # Only count toward restart limit when match actually completed
        if completed_cleanly:
            try:
                await _Zesty_on_match_complete(group_id, uid_str)
            except Exception as e:
                Zesty_print_error(f"[RESTART] track failed: {e}")

# ==================== FUNCTIONAL LONE WOLF ====================
async def Zesty_functional_lone_wolf(addrs, starter_packet, account_region, Zesty_client_version,
                                key, iv, account_id="", account_data=None, max_reconnects=10,
                                group_id: str = "default"):
    reconnects = 0
    ip, port = addrs.split(":")
    play_matches: List[asyncio.Task] = []
    no_response_count = 0
    search_attempts = 0
    uid_str = str(account_id)

    current_token = starter_packet
    current_key = key
    current_iv = iv
    current_account_data = account_data
    _writer_ref = {"w": None}
    _team_active = {"flag": True}
    _match_played = {"flag": False}

    _team_state = Zesty_get_team_state(group_id)

    # Arm the watchdog — no match start within MATCH_START_WATCHDOG → full restart
    try:
        _Zesty_ensure_watchdog(group_id)
    except Exception as _wd_err:
        Zesty_print_warning(f"[WATCHDOG] ensure failed: {_wd_err}")

    async def _Zesty_process_social_packet(raw_bytes, tag="MAIN"):
        try:
            hex_data = raw_bytes.hex()
            Zesty_print_info(f"[SOCIAL-{tag}] len={len(raw_bytes)} hex={hex_data[:60]}")
            candidates = []
            if len(raw_bytes) >= 6:
                plen = raw_bytes[4]
                if 0 < plen <= (len(raw_bytes) - 5):
                    try:
                        inner = bytes(raw_bytes[5:5 + plen])
                        d0 = Zesty_decode_protobuf_dict(inner)
                        if not d0:
                            a0 = Zesty_decode_protobuf_2(inner)
                            if a0:
                                d0 = {str(k): {"data": v} for k, v in a0.items()}
                        if d0:
                            candidates.append((5, d0))
                    except Exception:
                        pass
            for off in [5, 6, 10, 8, 12, 14, 4, 16, 0]:
                if off >= len(hex_data): continue
                try:
                    inner_bytes = bytes.fromhex(hex_data[off:])
                except Exception: continue
                decoded = None
                try:
                    d1 = Zesty_decode_protobuf_dict(inner_bytes)
                    if d1: decoded = d1
                except Exception: pass
                if not decoded:
                    try:
                        d2 = Zesty_decode_protobuf_2(inner_bytes)
                        if d2: decoded = {str(k): {"data": v} for k, v in d2.items()}
                    except Exception: pass
                if decoded:
                    candidates.append((off, decoded))
            if not candidates:
                Zesty_print_warning(f"[SOCIAL-{tag}] no decodable protobuf found"); return
            def _Zesty_score(item):
                _off, d = item
                s = len(d)
                if "0" in d or 0 in d: s -= 100
                if "5" in d: s += 6
                if "1" in d: s += 4
                if "2" in d: s += 2
                return s
            candidates.sort(key=_Zesty_score, reverse=True)
            best_off, decoded = candidates[0]
            Zesty_print_info(f"[SOCIAL-{tag}] decoded@{best_off} fields={list(decoded.keys())[:15]}")

            def _Zesty_val(container, k):
                if not isinstance(container, dict): return None
                v = container.get(k) if k in container else container.get(str(k))
                if isinstance(v, dict) and "data" in v: return v["data"]
                return v

            f5wrap = decoded.get("5") or decoded.get(5)
            f5 = None
            if isinstance(f5wrap, dict) and "data" in f5wrap: f5 = f5wrap["data"]
            elif isinstance(f5wrap, dict): f5 = f5wrap

            target_uid = None
            if isinstance(f5, dict):
                for fk in [1, 2, 3, 4, 6]:
                    cand = _Zesty_val(f5, fk)
                    if cand and str(cand).isdigit() and 6 <= len(str(cand)) <= 15:
                        target_uid = str(cand); break
            if not target_uid:
                for fk in [1, 2, 3]:
                    cand = _Zesty_val(decoded, fk)
                    if cand and str(cand).isdigit() and 6 <= len(str(cand)) <= 15:
                        target_uid = str(cand); break
            if not target_uid:
                Zesty_print_warning(f"[SOCIAL-{tag}] could not find target UID"); return

            own_acc = None
            if current_account_data:
                own_acc = str(current_account_data.get('account_id', ''))
            if own_acc and target_uid == own_acc:
                Zesty_print_info(f"[SOCIAL-{tag}] skip (self)"); return
            if not _accept_friend_request or not current_account_data: return

            jwt_l = current_account_data.get('token')
            srv_l = current_account_data.get('server_url')
            rel_l = current_account_data.get('Zesty_release_version')
            own_id = current_account_data.get('account_id')
            if not (jwt_l and srv_l and rel_l and own_id): return

            Zesty_print_info(f"[FRIEND-{tag}] ConfirmFriendRequest: target={target_uid} own={own_id}")
            url = f"{srv_l.rstrip('/')}/ConfirmFriendRequest"
            fields = {"1": int(target_uid), "2": int(own_id)}
            try:
                payload = bytes.fromhex(Zesty_encrypt_aes(Zesty_create_proto(fields).hex()))
                hdrs = {
                    "authorization": f"Bearer {jwt_l}",
                    "host": srv_l.replace("https://", "").replace("http://", "").split("/")[0],
                    "x-ga": "v1 1",
                    "content-type": "application/x-www-form-urlencoded",
                    "accept-encoding": "deflate, gzip",
                    "releaseversion": f"{rel_l}",
                    "user-agent": "UnityPlayer/2022.3.47f1 (UnityWebRequest/1.0, libcurl/8.5.0-DEV)",
                    "accept": "*/*", "x-unity-version": "2022.3.47f1",
                }
                ssl_ctx = ssl.create_default_context()
                ssl_ctx.check_hostname = False; ssl_ctx.verify_mode = ssl.CERT_NONE
                async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=8)) as s:
                    async with s.post(url, headers=hdrs, data=payload, ssl=ssl_ctx) as r:
                        body = await r.read()
                        if r.status == 200 and len(body) > 0:
                            Zesty_print_success(f"[FRIEND-{tag}] ✅ Accepted {target_uid}")
                        else:
                            Zesty_print_warning(f"[FRIEND-{tag}] HTTP {r.status} len={len(body)}")
            except Exception as e:
                Zesty_print_warning(f"[FRIEND-{tag}] {type(e).__name__}: {e}")
        except Exception as e:
            Zesty_print_warning(f"[SOCIAL-{tag}] exception: {type(e).__name__}: {e}")

    async def _Zesty_team_coordinator():
        try:
            while True:
                async with _team_state["lock"]:
                    n = len(_team_state["peers"])
                if n >= TEAM_SIZE: break
                if bot_state.Zesty_is_paused(uid_str): return
                if _match_played["flag"]: return
                await asyncio.sleep(0.5)

            await asyncio.sleep(TEAM_READY_DELAY)

            async with _team_state["lock"]:
                is_leader = (_team_state["leader_uid"] == uid_str)
                peers_snapshot = dict(_team_state["peers"])
            if not is_leader:
                Zesty_print_info(f"[TEAM] {uid_str} waiting as member..."); return

            live_peers = {
                p: v for p, v in peers_snapshot.items()
                if v.get("writer") and not v["writer"].is_closing()
            }
            if len(live_peers) < TEAM_SIZE:
                Zesty_print_warning(f"[TEAM] only {len(live_peers)}/{TEAM_SIZE} live peers after delay, aborting")
                return

            Zesty_print_success(f"[TEAM] 👑 {uid_str} — creating team ({len(live_peers)} live peers)")

            async with _team_state["lock"]:
                _team_state["team_code"] = None

            own_id_num = None
            if current_account_data: own_id_num = current_account_data.get('account_id')
            if not own_id_num:
                try: own_id_num = int(uid_str)
                except Exception: own_id_num = 0

            try:
                pkt = Zesty_create_team(current_key, current_iv, Zesty_client_version)
                if _writer_ref["w"] and not _writer_ref["w"].is_closing():
                    _writer_ref["w"].write(pkt); await _writer_ref["w"].drain()
            except Exception as e:
                Zesty_print_error(f"[TEAM] Zesty_create_team err: {e}")
            await asyncio.sleep(1.5)

            try:
                pkt = Zesty_team_fresh(int(own_id_num), current_key, current_iv)
                if _writer_ref["w"] and not _writer_ref["w"].is_closing():
                    _writer_ref["w"].write(pkt); await _writer_ref["w"].drain()
            except Exception as e:
                Zesty_print_warning(f"[TEAM] Zesty_team_fresh err: {e}")
            await asyncio.sleep(1.0)

            async def _Zesty_invite_uid(target_uid, label=""):
                for attempt in range(2):
                    try:
                        inv = Zesty_invite_player_in_team(int(target_uid), current_key, current_iv)
                        if _writer_ref["w"] and not _writer_ref["w"].is_closing():
                            _writer_ref["w"].write(inv); await _writer_ref["w"].drain()
                    except Exception as e:
                        Zesty_print_warning(f"[TEAM] invite err: {e}")
                    await asyncio.sleep(0.6)

            invited_uids = set()
            invite_count = 0
            for peer_uid, peer_info in live_peers.items():
                if peer_uid == uid_str: continue
                peer_acc_id = None
                try: peer_acc_id = peer_info["data"].get("account_id")
                except Exception: pass
                if not peer_acc_id: peer_acc_id = peer_uid
                Zesty_print_success(f"[TEAM] 📨 Inviting bot{invite_count+2} {peer_acc_id}...")
                await _Zesty_invite_uid(int(peer_acc_id), f" bot{invite_count+2}")
                invited_uids.add(peer_uid)
                invite_count += 1
            await asyncio.sleep(TEAM_INVITE_WAIT + 3.0)

            try:
                pkt = Zesty_team_fresh(int(own_id_num), current_key, current_iv)
                if _writer_ref["w"] and not _writer_ref["w"].is_closing():
                    _writer_ref["w"].write(pkt); await _writer_ref["w"].drain()
            except Exception as e:
                Zesty_print_warning(f"[TEAM] Zesty_team_fresh #2 err: {e}")
            await asyncio.sleep(1.0)

            Zesty_print_success(f"[TEAM] 🚀 {uid_str} Zesty_loop: ready → 1s → start (every 5s, full squad only)")

            while _team_active["flag"] and not _match_played["flag"]:
                try:
                    if bot_state.Zesty_is_paused(uid_str): break

                    async with _team_state["lock"]:
                        if _team_state["leader_uid"] != uid_str: break
                        current_peers = dict(_team_state["peers"])

                    live_current = {
                        p: v for p, v in current_peers.items()
                        if v.get("writer") and not v["writer"].is_closing()
                    }

                    new_peers = set(live_current.keys()) - invited_uids - {uid_str}
                    for peer_uid in new_peers:
                        peer_info = live_current[peer_uid]
                        peer_acc_id = None
                        try: peer_acc_id = peer_info["data"].get("account_id")
                        except Exception: pass
                        if not peer_acc_id: peer_acc_id = peer_uid
                        Zesty_print_success(f"[TEAM] 📨 Re-inviting late peer {peer_acc_id}")
                        await _Zesty_invite_uid(int(peer_acc_id))
                        invited_uids.add(peer_uid)

                    if len(live_current) < TEAM_SIZE:
                        Zesty_print_info(f"[TEAM] team {len(live_current)}/{TEAM_SIZE} live — waiting")
                        await asyncio.sleep(2.0)
                        continue

                    own_id = current_account_data.get('account_id', own_id_num) if current_account_data else own_id_num
                    try:
                        rdy = Zesty_ready_for_game(int(own_id), current_key, current_iv)
                        if _writer_ref["w"] and not _writer_ref["w"].is_closing():
                            _writer_ref["w"].write(rdy); await _writer_ref["w"].drain()
                    except Exception as e:
                        Zesty_print_warning(f"[TEAM] Zesty_ready_for_game err: {e}")
                    await asyncio.sleep(1.0)
                    sm = Zesty_start_match_team(int(own_id), current_key, current_iv, region=account_region)
                    if _writer_ref["w"] and not _writer_ref["w"].is_closing():
                        _writer_ref["w"].write(sm); await _writer_ref["w"].drain()
                except Exception as e:
                    Zesty_print_warning(f"[TEAM] start_match err: {e}")
                try: await asyncio.wait_for(asyncio.sleep(5.0), timeout=5.5)
                except asyncio.TimeoutError: pass
        except asyncio.CancelledError: raise
        except Exception as e:
            Zesty_print_error(f"[TEAM] coordinator error: {e}")

    async def _Zesty_member_match_trigger():
        try:
            while True:
                async with _team_state["lock"]:
                    if _team_state["leader_uid"] == uid_str: return
                    team_size = len(_team_state["peers"])
                if team_size >= TEAM_SIZE: break
                if bot_state.Zesty_is_paused(uid_str): return
                if _match_played["flag"]: return
                await asyncio.sleep(1.0)

            await asyncio.sleep(TEAM_READY_DELAY + 8.0)

            Zesty_print_success(f"[TEAM] 🚀 Member {uid_str} Zesty_loop (full squad)")
            my_id = current_account_data.get('account_id', uid_str) if current_account_data else uid_str
            while _team_active["flag"] and not _match_played["flag"]:
                try:
                    if bot_state.Zesty_is_paused(uid_str): break
                    async with _team_state["lock"]:
                        if _team_state["leader_uid"] == uid_str: break
                        current_peers = dict(_team_state["peers"])
                    live_current = {
                        p: v for p, v in current_peers.items()
                        if v.get("writer") and not v["writer"].is_closing()
                    }
                    if len(live_current) < TEAM_SIZE:
                        await asyncio.sleep(2.0)
                        continue
                    if _writer_ref["w"] and not _writer_ref["w"].is_closing():
                        try:
                            rdy = Zesty_ready_for_game(int(my_id), current_key, current_iv)
                            _writer_ref["w"].write(rdy); await _writer_ref["w"].drain()
                        except Exception as e:
                            Zesty_print_warning(f"[TEAM] member ready err: {e}")
                        await asyncio.sleep(1.0)
                        sm = Zesty_start_match_team(int(my_id), current_key, current_iv, region=account_region)
                        _writer_ref["w"].write(sm); await _writer_ref["w"].drain()
                except Exception as e:
                    Zesty_print_warning(f"[TEAM] member trigger: {e}")
                try: await asyncio.wait_for(asyncio.sleep(5.0), timeout=5.5)
                except asyncio.TimeoutError: pass
        except asyncio.CancelledError: raise
        except Exception as e:
            Zesty_print_warning(f"[TEAM] member trigger outer: {e}")

    try:
        while True:
            # Reset per-round flags so every reconnect starts a fresh match search
            _match_played["flag"] = False
            _team_active["flag"] = True

            while bot_state.Zesty_is_paused(uid_str):
                try: bot_state.Zesty_update_status(uid_str, "PAUSED", 0)
                except Exception: pass
                await asyncio.sleep(1.0)

            writer = None
            gateway_ping_task = None
            team_coord_task = None
            member_trigger_task = None
            try:
                if current_account_data:
                    fresh = None
                    if current_account_data.get('auth_type') == 'guest' and current_account_data.get('auth_uid'):
                        fresh = Zesty_cache_get(str(current_account_data['auth_uid']))
                    elif current_account_data.get('auth_type') == 'token' and current_account_data.get('auth_token'):
                        fresh = Zesty_cache_get(f"tok_{current_account_data['auth_token'][:20]}")
                    if fresh:
                        current_account_data = fresh
                        current_key = fresh['aes_ak']; current_iv = fresh['iv_i']
                        current_token = await Zesty_build_tcp_startup_packet(
                            fresh['account_id'], fresh['token'], fresh['Zesty_server_time'],
                            current_key, current_iv,
                            region=fresh.get('region', account_region), typ='OnLine')
                    else:
                        raise ConnectionError("Cache expired")

                resolved_ip = await Zesty_resolve_host_cloudflare(ip)
                reader, writer = await asyncio.open_connection(resolved_ip, int(port))
                bot_state.Zesty_register_writer(uid_str, writer)
                _writer_ref["w"] = writer
                raw_sock = writer.get_extra_info('socket')
                if raw_sock: Zesty_optimize_tcp_socket(raw_sock)
                writer.write(bytes.fromhex(current_token)); await writer.drain()
                try:
                    init_ka = await Zesty_send_keep_alive(account_region)
                    if init_ka and not writer.is_closing():
                        writer.write(init_ka)
                        await asyncio.wait_for(writer.drain(), timeout=3)
                except Exception: pass

                async def Zesty_func_gateway_keepalive():
                    ka_bytes = await Zesty_send_keep_alive(account_region)
                    while True:
                        await asyncio.sleep(5)
                        try:
                            if writer and not writer.is_closing():
                                writer.write(ka_bytes); await writer.drain()
                        except Exception: break

                gateway_ping_task = asyncio.create_task(Zesty_func_gateway_keepalive())
                Zesty_print_success(f"[✓] TCP Gateway Connected | UID: {uid_str}")
                reconnects = 0
                no_response_count = 0

                async with _team_state["lock"]:
                    _team_state["peers"][uid_str] = {
                        "writer": writer, "data": current_account_data,
                        "key": current_key, "iv": current_iv}
                    if _team_state["leader_uid"] is None:
                        _team_state["leader_uid"] = uid_str
                        Zesty_print_success(f"[TEAM] 👑 {uid_str} is first peer (leader)")

                if not _match_played["flag"]:
                    team_coord_task = asyncio.create_task(_Zesty_team_coordinator())
                    member_trigger_task = asyncio.create_task(_Zesty_member_match_trigger())
                else:
                    Zesty_print_info(f"[IDLE] {uid_str} resuming in idle mode")

                # ============ MAIN READ LOOP ============
                while True:
                    play_matches[:] = [m for m in play_matches if not m.done()]
                    if bot_state.Zesty_is_paused(uid_str): break

                    try:
                        data = await asyncio.wait_for(reader.read(8192), timeout=0.5)
                    except asyncio.TimeoutError:
                        no_response_count += 1; continue
                    if not data:
                        raise ConnectionError("Connection closed")
                    hex_data = data.hex()
                    packet_length = len(data)
                    no_response_count = 0

                    if DEBUG_ALL_PACKETS:
                        Zesty_print_info(f"[RAW-PKT] len={packet_length} prefix={hex_data[:20]}")

                    if hex_data.startswith("0600") and packet_length > 20:
                        await _Zesty_process_social_packet(data, tag="MAIN"); continue

                    if hex_data.startswith("0500") and packet_length > 10:
                        try:
                            inner = bytes.fromhex(hex_data[10:])
                            dec = Zesty_decode_protobuf_dict(inner)
                            if not dec:
                                alt = Zesty_decode_protobuf_2(inner)
                                if alt: dec = {str(k): {"data": v} for k, v in alt.items()}
                            f5w = dec.get("5") or dec.get(5)
                            f5 = f5w.get("data") if isinstance(f5w, dict) and "data" in f5w else f5w
                            if not isinstance(f5, dict): f5 = dec
                            def _Zesty_f5g(key):
                                if not isinstance(f5, dict): return None
                                v = f5.get(key) if key in f5 else f5.get(str(key))
                                if isinstance(v, dict) and "data" in v: return v["data"]
                                return v
                            tc = None
                            for fk in [11, 5, 1, 3]:
                                cand = _Zesty_f5g(fk)
                                if cand and str(cand).isdigit() and len(str(cand)) == 7:
                                    tc = str(cand); break
                            if tc:
                                async with _team_state["lock"]:
                                    _team_state["team_code"] = tc
                                Zesty_print_success(f"[TEAM] 📢 Team Code captured: {tc}")
                            group_id_pkt = _Zesty_f5g(8)
                            if group_id_pkt and isinstance(group_id_pkt, str) and 20 <= len(group_id_pkt) <= 40:
                                pass
                            else: group_id_pkt = None
                            own_acc = None
                            if current_account_data: own_acc = str(current_account_data.get('account_id'))
                            inviter = None
                            for fk in [1, 2, 3, 4, 6, 7, 13, 15, 20]:
                                cand = _Zesty_f5g(fk)
                                if cand and str(cand).isdigit() and 6 <= len(str(cand)) <= 15:
                                    if str(cand) != uid_str and str(cand) != own_acc:
                                        inviter = cand; break
                            if inviter and group_id_pkt and _team_state["leader_uid"] != uid_str:
                                Zesty_print_success(f"[TEAM] 📨 Invite from {inviter} → accepting...")
                                for _ in range(2):
                                    try:
                                        acc = Zesty_accept_team_invite(int(inviter), group_id_pkt, current_key, current_iv)
                                        if writer and not writer.is_closing():
                                            writer.write(acc); await writer.drain()
                                            Zesty_print_success(f"[TEAM] ✅ accept sent ({len(acc)}B)")
                                    except Exception as e:
                                        Zesty_print_warning(f"[TEAM] accept err: {e}")
                                    await asyncio.sleep(0.4)
                        except Exception as e:
                            Zesty_print_warning(f"[TEAM] 0500 parse: {e}")
                        continue

                    if hex_data.startswith("0300") and 10 < packet_length < 30:
                        continue

                    if hex_data.startswith("0300") and packet_length >= 300:
                        Zesty_print_success(f"[⚔] Match Found | UID: {uid_str}")
                        # WATCHDOG: timer Zesty_reset — squad is no longer stuck
                        try:
                            _Zesty_on_match_start(group_id, uid_str)
                        except Exception as _wd_err:
                            Zesty_print_warning(f"[WATCHDOG] on_start failed: {_wd_err}")
                        for tk in (team_coord_task, member_trigger_task):
                            if tk and not tk.done():
                                tk.cancel()
                        team_coord_task = None
                        member_trigger_task = None
                        _team_active["flag"] = False
                        _match_played["flag"] = True  # prevent re-trigger while in UDP match

                        async with _team_state["lock"]:
                            _team_state["peers"].pop(uid_str, None)
                            if _team_state["leader_uid"] == uid_str:
                                _team_state["leader_uid"] = None
                                _team_state["team_code"] = None
                        Zesty_print_info(f"[MATCH-START] {uid_str} left peer registry (in match)")

                        try:
                            res = json.loads(await Zesty_decode_protobuf_async(hex_data[10:]))
                            token = udp_key = match_code = server_ip_port = None
                            match_account_id = block_val = None
                            match_game_mode = 1
                            match_map_id = 1
                            match_match_mode = 1
                            match_sleep_ms = 0
                            match_id = 0

                            if '42' in res and 'data' in res['42']:
                                match_code = res['42']['data']
                            if '5' in res and 'data' in res['5']:
                                rf5 = res['5']['data']
                                server_ip_port = rf5.get('2', {}).get('data')
                                udp_key = rf5.get('3', {}).get('data')
                                token = rf5.get('4', {}).get('data')
                                if '42' in rf5:
                                    match_code = rf5['42']['data']
                                try: match_id = int(rf5.get('1', {}).get('data') or 0)
                                except Exception: match_id = 0
                                try: match_map_id = int(rf5.get('6', {}).get('data') or 1)
                                except Exception: match_map_id = 1
                                try: match_game_mode = int(rf5.get('7', {}).get('data') or 1)
                                except Exception: match_game_mode = 1
                                try: match_match_mode = int(rf5.get('8', {}).get('data') or 1)
                                except Exception: match_match_mode = 1
                                try: match_sleep_ms = int(rf5.get('5', {}).get('data') or 0)
                                except Exception: match_sleep_ms = 0
                            if '1' in res and 'data' in res['1']:
                                match_account_id = res['1']['data']
                            if '5' in res and 'data' in res['5']:
                                block_val = res['5']['data'].get('1', {}).get('data')

                            effective_acc_id = match_account_id or account_id or "BD_BOT"

                            if token and udp_key and match_code and server_ip_port:
                                active_now = await _Zesty_get_match_count(uid_str)
                                if active_now >= MAX_CONCURRENT_MATCHES:
                                    Zesty_print_warning(f"[⚔] {uid_str} at {MAX_CONCURRENT_MATCHES} matches — waiting for slot")
                                    while await _Zesty_get_match_count(uid_str) >= MAX_CONCURRENT_MATCHES:
                                        play_matches[:] = [m for m in play_matches if not m.done()]
                                        if not any(not m.done() for m in play_matches):
                                            _match_counters[uid_str] = 0
                                            break
                                        await asyncio.sleep(3.0)
                                match_index = await _Zesty_inc_match(uid_str)
                                Zesty_print_info(f"[⚔] Match #{match_index} → {server_ip_port} "
                                           f"(mode={match_game_mode} map={match_map_id})")
                                try:
                                    bot_state.Zesty_increment_match_started()
                                    bot_state.Zesty_update_status(uid_str, "IN_MATCH", active_now + 1)
                                except Exception: pass
                                new_match = asyncio.create_task(Zesty_play_game(server_ip_port,
                                    token,
                                    udp_key,
                                    match_code,
                                    effective_acc_id,
                                    account_region,
                                    Zesty_client_version,
                                    current_key,
                                    current_iv,
                                    match_index,
                                    game_mode=match_game_mode,
                                    map_id=match_map_id,
                                    match_mode=match_match_mode,
                                    sleep_ms=match_sleep_ms,
                                    match_id=match_id,
                                    verbose=True,
                                    group_id=group_id,))
                                play_matches.append(new_match)
                                Zesty_print_success(
                                    f"[⚔] Match #{match_index} launched → {server_ip_port} "
                                    f"(mode={match_game_mode} map={match_map_id})")
                                # Close TCP — UDP runs in background, bot reconnects for next match
                                try:
                                    writer.close()
                                    await writer.wait_closed()
                                except Exception: pass
                                await asyncio.sleep(NEW_MATCH_DELAY)
                                break  # back to outer reconnect loop — search next match
                        except Exception as e:
                            Zesty_print_warning(f"[MATCH] {e}"); continue

                    if 30 <= packet_length <= 40:
                        continue

            except asyncio.CancelledError: raise
            except Exception as e:
                if "Cache expired" in str(e):
                    Zesty_print_warning(f"[!] Token expired {uid_str}"); break
                reconnects += 1
                if reconnects > max_reconnects:
                    if current_account_data:
                        try:
                            if current_account_data.get('auth_uid'):
                                Zesty_cache_invalidate(str(current_account_data['auth_uid']))
                            if current_account_data.get('auth_token'):
                                Zesty_cache_invalidate(f"tok_{current_account_data['auth_token'][:20]}")
                        except Exception: pass
                    reconnects = 0; break
                Zesty_print_warning(f"[{uid_str}] Reconnect #{reconnects}: {e}")
                await asyncio.sleep(min(reconnects * 0.5, 2.0))
            finally:
                _team_active["flag"] = False
                async with _team_state["lock"]:
                    _team_state["peers"].pop(uid_str, None)
                    if _team_state["leader_uid"] == uid_str:
                        _team_state["leader_uid"] = None
                        _team_state["team_code"] = None
                for tk in (team_coord_task, member_trigger_task):
                    if tk and not tk.done():
                        tk.cancel()
                        try: await tk
                        except asyncio.CancelledError: pass
                if gateway_ping_task:
                    gateway_ping_task.cancel()
                    try: await gateway_ping_task
                    except asyncio.CancelledError: pass
                if writer:
                    bot_state.Zesty_unregister_writer(uid_str, writer)
                    await Zesty_safe_close_writer(writer)

                _team_active["flag"] = True
    except asyncio.CancelledError:
        Zesty_print_info(f"[FUNCTIONAL] Task cancelled for {uid_str}")
        raise
    finally:
        for m in play_matches:
            if not m.done(): m.cancel()

# ==================== INFORMATIONAL ====================
async def Zesty_informational(addrs, starter_packet, key, iv, region="BD",
                        account_id="", max_reconnects=3, account_data=None):
    uid_str = str(account_id); reconnects = 0
    ip, port = addrs.split(":")
    while True:
        while uid_str and bot_state.Zesty_is_paused(uid_str):
            await asyncio.sleep(1.0)
        writer = None; ping_task = None
        try:
            resolved_ip = await Zesty_resolve_host_cloudflare(ip)
            reader, writer = await asyncio.open_connection(resolved_ip, int(port))
            if uid_str: bot_state.Zesty_register_writer(uid_str, writer)
            raw_sock = writer.get_extra_info('socket')
            if raw_sock: Zesty_optimize_tcp_socket(raw_sock)
            writer.write(bytes.fromhex(starter_packet)); await writer.drain()
            reconnects = 0
            try:
                init_ka = await Zesty_send_keep_alive(region)
                if init_ka and not writer.is_closing():
                    writer.write(init_ka)
                    await asyncio.wait_for(writer.drain(), timeout=3)
            except Exception: pass
            async def Zesty_info_ka():
                ka = await Zesty_send_keep_alive(region)
                while True:
                    await asyncio.sleep(5)
                    try:
                        if writer and not writer.is_closing():
                            writer.write(ka); await writer.drain()
                    except Exception: break
            ping_task = asyncio.create_task(Zesty_info_ka())
            Zesty_print_success(f"[INFO] Connected | UID: {uid_str}")
            while True:
                if uid_str and bot_state.Zesty_is_paused(uid_str):
                    if ping_task: ping_task.cancel()
                    if uid_str: bot_state.Zesty_unregister_writer(uid_str, writer)
                    await Zesty_safe_close_writer(writer); writer = None
                    while bot_state.Zesty_is_paused(uid_str): await asyncio.sleep(1.0)
                    break
                try: data = await asyncio.wait_for(reader.read(8192), timeout=1.0)
                except asyncio.TimeoutError: continue
                if not data: raise ConnectionError("closed")
        except asyncio.CancelledError:
            if ping_task: ping_task.cancel()
            if uid_str: bot_state.Zesty_unregister_writer(uid_str, writer)
            await Zesty_safe_close_writer(writer); raise
        except Exception:
            if ping_task: ping_task.cancel()
            if uid_str: bot_state.Zesty_unregister_writer(uid_str, writer)
            await Zesty_safe_close_writer(writer)
            reconnects += 1
            if reconnects > max_reconnects:
                await asyncio.sleep(3); reconnects = 0
            else: await asyncio.sleep(1)

# ==================== ACCOUNT HELPERS ====================
def _Zesty_register_credentials(ad):
    try:
        bot_state.account_credentials[str(ad['account_id'])] = ad
        if ad.get('auth_uid'): bot_state.account_credentials[str(ad['auth_uid'])] = ad
    except Exception: pass

async def Zesty_refresh_account_profile(ad_or_uid):
    try:
        if isinstance(ad_or_uid, str):
            uid = str(ad_or_uid); ad = bot_state.account_credentials.get(uid)
        else:
            ad = ad_or_uid; uid = str(ad.get('account_id'))
        if not ad: return
        token = ad.get('token'); acc_id = ad.get('account_id')
        srv = ad.get('server_url'); rel = ad.get('Zesty_release_version')
        if not (token and acc_id and srv and rel): return
        data = await Zesty_get_player_personal_show(int(acc_id), token, srv, rel)
        if not data: return
        pd = data.get(1, {}) if isinstance(data.get(1), dict) else {}
        nickname = pd.get(3); lvl = pd.get(6); exp = pd.get(7)
        if exp is None: return
        try:
            exp = int(exp); lvl = int(lvl) if lvl else 1
        except Exception: return
        aid = str(acc_id)
        if aid not in bot_state.accounts:
            bot_state.Zesty_register_account(aid, nickname or f"Player_{aid}",
                region=ad.get('region','BD'), level=lvl, exp=exp,
                auth_uid=ad.get('auth_uid'))
            return
        old = bot_state.accounts[aid].get("current_exp", 0)
        bot_state.Zesty_update_exp(aid, exp, lvl)
        if nickname: bot_state.accounts[aid]["nickname"] = nickname
        if exp > old: Zesty_print_success(f"[★] +{exp-old:,} EXP | {aid}")
    except Exception: pass

async def Zesty_process_account_uid_pass(uid, password, region_override=None):
    cached = Zesty_cache_get(uid)
    if cached:
        aid = str(cached['account_id'])
        nick = cached.get('nickname', f"Player_{aid}")
        lvl = cached.get('level', 1); expv = cached.get('exp', 0)
        Zesty_print_success(f"[✓] Online (cache): {aid} | {nick}")
        bot_state.Zesty_register_account(aid, nick, cached.get('region','BD'),
            lvl, expv, cached.get('likes',0), auth_uid=str(uid))
        _Zesty_register_credentials(cached); return cached
    Zesty_print_info(f"[LOGIN] UID: {uid}")
    try:
        async with _LOGIN_SEMAPHORE:
            vc = await Zesty_version_config(region_override or "BD")
            if not vc: return None
            Zesty_release_version, Zesty_client_version, Zesty_server_url, gop_1, app_version = vc
            tg = await Zesty_get_access_token(uid, password)
            if not tg: return None
            open_id, access_token, platform = tg
            major_payload, login_payload = await Zesty_get_payload(
                access_token, open_id, platform, Zesty_client_version)
            res_json = await Zesty_major_login(major_payload, Zesty_server_url, Zesty_release_version)
            if not res_json: return None

            def _Zesty_gd(k):
                v = res_json.get(str(k))
                if isinstance(v, dict) and "data" in v: return v["data"]
                if k in res_json and not isinstance(res_json[k], dict): return res_json[k]
                if isinstance(v, dict): return v.get("data")
                return None

            acc_id_raw = _Zesty_gd(1); region_raw = _Zesty_gd(2) or "BD"
            jwt_token = _Zesty_gd(8); server_url_raw = _Zesty_gd(10); Zesty_server_time = _Zesty_gd(21)
            aes_ak, iv_i = _Zesty_extract_key_iv(res_json)
            if not jwt_token or not server_url_raw or not aes_ak: return None
            getlogin_json = await Zesty_get_login_data(
                login_payload, jwt_token, server_url_raw, Zesty_release_version)
            if not getlogin_json: return None

        def _Zesty_gf(f, d=None):
            v = getlogin_json.get(str(f), {}).get("data")
            return v if v is not None else d

        level = int(_Zesty_gf(6,1) or 1); exp = int(_Zesty_gf(7,0) or 0)
        likes = int(_Zesty_gf(8,0) or 0)
        nickname = _Zesty_gf(4, f"Player_{acc_id_raw}") or f"Player_{acc_id_raw}"
        region = region_raw or _Zesty_gf(3,"BD") or "BD"
        acc_id = str(acc_id_raw)

        bot_state.Zesty_register_account(acc_id, nickname, region, level, exp, likes, auth_uid=str(uid))
        Zesty_print_success(f"[✓] Login: {acc_id} | {nickname} | Lvl {level}")

        ad = {'account_id':acc_id_raw,'nickname':nickname,'region':region,
            'level':level,'exp':exp,'likes':likes,'open_id':open_id,
            'access_token':access_token,'platform':str(platform),
            'token':jwt_token,'Zesty_server_time':Zesty_server_time,
            'aes_ak':aes_ak,'iv_i':iv_i,
            'functional_addrs':_Zesty_gf(14),'informational_addrs':_Zesty_gf(32),
            'Zesty_release_version':Zesty_release_version,'Zesty_client_version':Zesty_client_version,
            'server_url':server_url_raw,'login_payload_data':login_payload,
            'auth_type':'guest','auth_uid':uid,'auth_password':password}
        _Zesty_register_credentials(ad); Zesty_cache_set(uid, ad); return ad
    except Exception as e:
        Zesty_print_error(f"login err: {e}"); return None

async def Zesty_run_account_worker(ad, label, region_override=None, clan_override=None,
                             group_id: str = "default"):
    acc_id = str(ad['account_id'])
    info_task = None; exp_task = None; clan_task = None
    try:
        reg = region_override or ad.get('region','BD')
        tcp_online = await Zesty_build_tcp_startup_packet(
            ad['account_id'], ad['token'], ad['Zesty_server_time'],
            ad['aes_ak'], ad['iv_i'], region=reg, typ='OnLine')
        tcp_chat = await Zesty_build_tcp_startup_packet(
            ad['account_id'], ad['token'], ad['Zesty_server_time'],
            ad['aes_ak'], ad['iv_i'], region=reg, typ='ChaT')

        if clan_override:
            try:
                await asyncio.sleep(1.0)
                await Zesty_join_clan(ad['token'], clan_override)
            except Exception as e:
                Zesty_print_warning(f"[CLAN] {e}")

            async def Zesty_clan_info_refresher():
                while True:
                    try:
                        fresh_ad = bot_state.account_credentials.get(acc_id) or ad
                        fresh_token = fresh_ad.get('token') or ad['token']
                        info = await Zesty_get_clan_info(fresh_token, clan_override)
                        if info:
                            bot_state.clan_info = info
                    except Exception as e:
                        Zesty_print_warning(f"[CLAN-INFO] {e}")
                    await asyncio.sleep(30)

            clan_task = asyncio.create_task(Zesty_clan_info_refresher())

        info_task = asyncio.create_task(Zesty_informational(
            ad['informational_addrs'], tcp_chat, ad['aes_ak'], ad['iv_i'],
            region=reg, account_id=acc_id, account_data=ad))

        async def Zesty_exp_refresher():
            while True:
                await asyncio.sleep(90 + random.uniform(-10,10))
                fresh = bot_state.account_credentials.get(acc_id)
                if fresh: await Zesty_refresh_account_profile(fresh)
        exp_task = asyncio.create_task(Zesty_exp_refresher())

        await Zesty_functional_lone_wolf(
            ad['functional_addrs'], tcp_online, reg, ad['Zesty_client_version'],
            ad['aes_ak'], ad['iv_i'], account_id=acc_id, account_data=ad,
            group_id=group_id)

    except asyncio.CancelledError: raise
    except Exception as e:
        Zesty_print_error(f"worker err {label}: {e}")
    finally:
        for t in (info_task, exp_task, clan_task):
            if t and not t.done(): t.cancel()
        for t in (info_task, exp_task, clan_task):
            if t:
                try: await t
                except Exception: pass

        try:
            if ad.get('auth_uid'):
                Zesty_cache_invalidate(str(ad['auth_uid']))
                Zesty_print_info(f"[RESTART] Cache cleared for {ad['auth_uid']} (group {group_id})")
        except Exception: pass

async def Zesty_account_loop_guest(uid, password, region_override=None, clan_override=None,
                              group_id: str = "default"):
    uid_str = str(uid)
    bot_state.account_workers[uid_str] = asyncio.current_task()
    acc_id = None
    while True:
        try:
            Zesty_cache_invalidate(uid_str)

            bot_state.Zesty_update_status(uid_str, "CONNECTING")
            ad = await Zesty_process_account_uid_pass(uid_str, password, region_override)
            if not ad:
                Zesty_print_error(f"Login failed {uid_str}. Retry 15s"); await asyncio.sleep(15); continue
            acc_id = str(ad['account_id'])
            bot_state.account_workers[acc_id] = asyncio.current_task()
            bot_state.auth_to_game_id[uid_str] = acc_id
            bot_state.game_to_auth_id[acc_id] = uid_str

            Zesty_print_success(f"[LOGIN ✓] {uid_str} → acc_id {acc_id} | group {group_id}")

            await Zesty_run_account_worker(ad, uid_str, region_override, clan_override,
                                     group_id=group_id)

            jitter = random.uniform(0, 4.0)
            Zesty_print_warning(f"[RESTART] {uid_str} → re-login in {3+jitter:.1f}s (group {group_id})")
            await asyncio.sleep(3 + jitter)

        except asyncio.CancelledError:
            try:
                bot_state.Zesty_update_status(uid_str, "OFFLINE")
                if acc_id: bot_state.Zesty_update_status(acc_id, "OFFLINE")
            except Exception: pass
            break
        except Exception as e:
            Zesty_print_error(f"err {uid_str}: {e}"); await asyncio.sleep(10)

# ==================== CREATE ACCOUNTS ====================
def _Zesty_gf_field(ld, key, default=None):
    if not ld: return default
    v = ld.get(str(key), {})
    if isinstance(v, dict): return v.get("data", default)
    return v if v is not None else default

def Zesty_generate_password() -> str:
    return hashlib.sha256(
        (str(uuid.uuid4()) + str(time.time())).encode()
    ).hexdigest().upper()

async def Zesty_choose_region(region, jwt_token, login_url, Zesty_release_version):
    region_code = region.upper()
    url = f"{login_url.rstrip('/')}/ChooseRegion"
    proto = Zesty_create_proto({1: region_code})
    payload = bytes.fromhex(Zesty_encrypt_aes(proto.hex()))
    hdrs = {
        "Accept-Encoding": "gzip",
        "Authorization": f"Bearer {jwt_token}",
        "Connection": "Keep-Alive",
        "Content-Type": "application/x-www-form-urlencoded",
        "ReleaseVersion": f"{Zesty_release_version}",
        "User-Agent": "UnityPlayer/2018.4.12f1 (UnityWebRequest/1.0, libcurl/8.5.0-DEV)",
        "X-GA": "v1 1", "X-GA-SV": str(int(time.time())),
        "X-Unity-Version": "2018.4.12f1",
    }
    try:
        ssl_ctx = ssl.create_default_context()
        ssl_ctx.check_hostname = False; ssl_ctx.verify_mode = ssl.CERT_NONE
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=15)) as s:
            async with s.post(url, data=payload, headers=hdrs, ssl=ssl_ctx) as r:
                body = await r.read()
                Zesty_print_info(f"[CHOOSE-REGION] {region} → HTTP {r.status}")
                return r.status
    except Exception as e:
        Zesty_print_error(f"[CHOOSE-REGION] {e}"); return None

async def Zesty_create_four_accounts(region: str, clan_id: str, count: int = 4):
    bot_state.creating = True
    bot_state.create_progress = []

    def _Zesty_prog(s):
        try:
            print(f"[CREATE] {s}")
            bot_state.Zesty_log(s, "info")
        except Exception: pass
        bot_state.create_progress.append(s)

    try:
        _Zesty_prog(f"⌛ Fetching version config for {region}...")
        vc = await Zesty_version_config(region)
        if not vc:
            _Zesty_prog("❌ version config failed"); return []
        release_v, remote_v, login_url, gop_1, app_version = vc
        if not login_url.endswith("/"): login_url += "/"
        lang = REGION_LANG.get(region.upper(), "en")
        game_version = remote_v or app_version
        _Zesty_prog(f"✅ Version OK | release={release_v} | game={game_version}")

        created = []
        for i in range(count):
            _Zesty_prog(f"⌛ Creating bot {i+1}/{count}...")

            password = Zesty_generate_password()
            _Zesty_prog(f"   → Password: {password[:16]}...{password[-8:]}")

            try:
                uid = await Zesty_register_account(password, gop_1, app_version)
                if not uid:
                    _Zesty_prog(f"❌ bot {i+1}: register failed"); continue
                _Zesty_prog(f"   → registered UID {uid}")

                tok = await Zesty_grant_token(uid, password, gop_1, app_version)
                if not tok:
                    _Zesty_prog(f"❌ bot {i+1}: grant failed"); continue
                open_id = tok["open_id"]; access_token = tok["access_token"]
                platform = tok.get("platform", 4)

                major_payload, login_payload = await Zesty_get_payload(
                    access_token, open_id, platform, game_version, lang)
                if not major_payload or not login_payload:
                    _Zesty_prog(f"❌ bot {i+1}: payload build failed"); continue

                nickname_final = f"Zesty_{''.join(random.choices(string.ascii_letters + string.digits, k=5))}"
                mr = await Zesty_major_register(release_v, access_token, open_id,
                                          nickname_final, game_version, login_url, lang)
                if not mr:
                    _Zesty_prog(f"❌ bot {i+1}: MajorRegister failed"); continue

                def _Zesty_mrg(k, d=None):
                    v = mr.get(str(k))
                    if isinstance(v, dict) and "data" in v: return v["data"]
                    return v if v is not None else d

                mr_acc_id = _Zesty_mrg(3)
                _Zesty_prog(f"   → MajorRegister OK | acc_id={mr_acc_id}")
                _Zesty_prog(f"   → waiting 3s for provisioning...")
                await asyncio.sleep(3.0)

                res_json = None
                for attempt in range(3):
                    mp, lp = await Zesty_get_payload(access_token, open_id, platform, game_version, lang)
                    _Zesty_prog(f"   → MajorLogin #1 attempt {attempt+1}/3...")
                    res_json = await Zesty_major_login(mp, login_url, release_v)
                    if res_json and (("8" in res_json) or (8 in res_json)):
                        major_payload = mp; login_payload = lp; break
                    res_json = None
                    await asyncio.sleep(2.0)

                if not res_json:
                    _Zesty_prog(f"❌ bot {i+1}: MajorLogin #1 failed"); continue

                def _Zesty_gd(k):
                    v = res_json.get(str(k))
                    if isinstance(v, dict) and "data" in v: return v["data"]
                    if k in res_json and not isinstance(res_json[k], dict): return res_json[k]
                    if isinstance(v, dict): return v.get("data")
                    return None

                jwt_token = _Zesty_gd(8); server_url_raw = _Zesty_gd(10)
                Zesty_server_time = _Zesty_gd(21); acc_id_raw = _Zesty_gd(1)

                if not jwt_token:
                    _Zesty_prog(f"❌ bot {i+1}: no JWT"); continue

                if not server_url_raw:
                    _Zesty_prog(f"   → Zesty_server_url missing — ChooseRegion({region})...")
                    try:
                        cr_status = await Zesty_choose_region(region, jwt_token, login_url, release_v)
                    except Exception as e:
                        cr_status = None; _Zesty_prog(f"   ❌ ChooseRegion error: {e}")
                    if cr_status != 200:
                        _Zesty_prog(f"❌ bot {i+1}: ChooseRegion failed ({cr_status})"); continue
                    _Zesty_prog(f"   ✅ ChooseRegion OK — re-running MajorLogin...")
                    await asyncio.sleep(2.0)
                    res_json2 = None
                    for attempt in range(3):
                        mp2, lp2 = await Zesty_get_payload(access_token, open_id, platform, game_version, lang)
                        res_json2 = await Zesty_major_login(mp2, login_url, release_v)
                        if res_json2 and (("10" in res_json2) or (10 in res_json2)):
                            res_json = res_json2; login_payload = lp2; break
                        res_json2 = None
                        await asyncio.sleep(2.0)
                    if not res_json2:
                        _Zesty_prog(f"❌ bot {i+1}: MajorLogin #2 no Zesty_server_url"); continue
                    res_json = res_json2

                    def _Zesty_gd2(k):
                        v = res_json.get(str(k))
                        if isinstance(v, dict) and "data" in v: return v["data"]
                        if k in res_json and not isinstance(res_json[k], dict): return res_json[k]
                        if isinstance(v, dict): return v.get("data")
                        return None
                    jwt_token = _Zesty_gd2(8); server_url_raw = _Zesty_gd2(10)
                    Zesty_server_time = _Zesty_gd2(21); acc_id_raw = _Zesty_gd2(1)
                    if not server_url_raw:
                        _Zesty_prog(f"❌ bot {i+1}: no Zesty_server_url"); continue

                _Zesty_prog(f"   ✅ Zesty_server_url = {server_url_raw}")

                aes_ak, iv_i = _Zesty_extract_key_iv(res_json)
                if not aes_ak or not iv_i:
                    _Zesty_prog(f"❌ bot {i+1}: AES key/IV fail"); continue

                ld = await Zesty_get_login_data(login_payload, jwt_token, server_url_raw, release_v)
                level = 1; exp = 0; likes = 0
                if ld:
                    def _Zesty_gf(f, d=None):
                        v = ld.get(str(f), {}).get("data")
                        return v if v is not None else d
                    level = int(_Zesty_gf(6, 1) or 1); exp = int(_Zesty_gf(7, 0) or 0)
                    likes = int(_Zesty_gf(8, 0) or 0)
                    nickname_final = _Zesty_gf(4, nickname_final) or nickname_final

                ad = {
                    'account_id': acc_id_raw, 'nickname': nickname_final,
                    'region': region, 'level': level, 'exp': exp, 'likes': likes,
                    'open_id': open_id, 'access_token': access_token,
                    'platform': str(platform), 'token': jwt_token,
                    'Zesty_server_time': Zesty_server_time, 'aes_ak': aes_ak, 'iv_i': iv_i,
                    'functional_addrs': _Zesty_gf_field(ld, 14),
                    'informational_addrs': _Zesty_gf_field(ld, 32),
                    'Zesty_release_version': release_v, 'Zesty_client_version': game_version,
                    'server_url': server_url_raw, 'login_payload_data': login_payload,
                    'auth_type': 'guest', 'auth_uid': uid, 'auth_password': password,
                }
                _Zesty_register_credentials(ad); Zesty_cache_set(uid, ad); created.append(ad)
                _Zesty_prog(f"✅ bot {i+1}: {nickname_final} | UID {acc_id_raw} | Lvl {level}")
                await asyncio.sleep(0.6)
            except Exception as e:
                _Zesty_prog(f"❌ bot {i+1}: {e}")
                traceback.print_exc()

        if not created:
            _Zesty_prog("❌ No accounts created."); return []

        group_id = None
        try:
            team_accounts = [
                {
                    "uid": str(a['auth_uid']),
                    "password": str(a['auth_password']),
                    "account_id": str(a.get('account_id', '')),
                    "nickname": str(a.get('nickname', '')),
                }
                for a in created
            ]
            group_id = Zesty_save_team_file(clan_id, region, team_accounts)
            if group_id:
                _Zesty_prog(f"📦 Group saved → {TEAMS_DIR}/squad_{group_id}.json ({len(created)} bots)")
            else:
                _Zesty_prog(f"⚠️ Group file save failed")
        except Exception as e:
            _Zesty_prog(f"⚠️ save group file failed: {e}")

        _Zesty_prog(f"🚀 Starting {len(created)} bot workers...")
        for i, a in enumerate(created):
            try:
                task = asyncio.create_task(Zesty_account_loop_guest(
                    str(a['auth_uid']), a['auth_password'],
                    region_override=region, clan_override=clan_id,
                    group_id=group_id))
                bot_state.account_workers[str(a['auth_uid'])] = task
                _Zesty_prog(f"   → worker started ({i+1}/{len(created)})")
                await asyncio.sleep(0.35)
            except Exception as e:
                _Zesty_prog(f"   ❌ worker {i+1} failed: {e}")

        _Zesty_prog(f"✅ All {len(created)} bots launched.")
        return created
    except Exception as e:
        _Zesty_prog(f"❌ Zesty_create_four_accounts error: {e}")
        traceback.print_exc(); return []
    finally:
        bot_state.creating = False

# ==================== AUTO-LOAD ON STARTUP ====================
async def _Zesty_autoload_teams():
    try:
        teams = Zesty_load_all_team_files()
        if not teams:
            Zesty_print_info(f"[BOOT] no teams in {TEAMS_DIR}/ — waiting for API calls")
            return
        total_accounts = sum(len(t["accounts"]) for t in teams)
        Zesty_print_info(f"[BOOT] {len(teams)} team(s) found in {TEAMS_DIR}/ | {total_accounts} total bots")

        for team in teams:
            clan_id = team["clan_id"]
            region = team["region"]
            group_id = team.get("group_id", "default")
            Zesty_print_success(f"[BOOT] Team clan={clan_id} group={group_id} region={region} — launching {len(team['accounts'])} bots")

            for acc in team["accounts"]:
                uid = acc["uid"]
                password = acc["password"]

                if uid in bot_state.account_workers and not bot_state.account_workers[uid].done():
                    Zesty_print_info(f"[BOOT] UID {uid} already running — skipped")
                    continue

                task = asyncio.create_task(Zesty_account_loop_guest(
                    uid, password,
                    region_override=region,
                    clan_override=clan_id,
                    group_id=group_id,
                ))
                bot_state.account_workers[uid] = task
                Zesty_print_success(f"[BOOT] worker started → UID {uid} | clan={clan_id} | group={group_id}")
                await asyncio.sleep(0.4)
    except Exception as e:
        Zesty_print_error(f"[BOOT] team load failed: {e}")

# ==================== HTTP SERVER ====================
@aiohttp.web.middleware
async def _Zesty_req_logger(request, handler):
    print(f"\033[90m[REQ] {request.method} {request.path}\033[0m")
    try:
        resp = await handler(request)
        print(f"\033[90m[RES] {request.method} {request.path} → {resp.status}\033[0m")
        return resp
    except aiohttp.web.HTTPException as e:
        print(f"\033[91m[ERR] {request.method} {request.path} → HTTP {e.status}\033[0m")
        if request.path.startswith("/api/"):
            return aiohttp.web.json_response(
                {"ok": False, "status": "error", "error": e.reason or str(e)},
                status=e.status)
        raise
    except Exception as e:
        print(f"\033[91m[ERR] {request.method} {request.path} → {e}\033[0m")
        traceback.print_exc()
        if request.path.startswith("/api/"):
            return aiohttp.web.json_response(
                {"ok": False, "status": "error", "error": str(e)}, status=500)
        raise

async def Zesty_serve_index(request):
    for path in (INDEX_HTML_PATH, "index.html"):
        try:
            with open(path, "r", encoding="utf-8") as f:
                return aiohttp.web.Response(text=f.read(), content_type="text/html")
        except Exception:
            continue
    return aiohttp.web.Response(
        text="<h1>Zestyx64</h1><p>index.html not found</p>",
        content_type="text/html")

async def Zesty_api_ping(request):
    return aiohttp.web.json_response({"pong": True, "app": "Zestyx64", "version": "2.0"})

async def Zesty_api_stats(request):
    try:
        accs = list(bot_state.accounts.values())
        online = sum(1 for a in accs if a.get("status") in ("ONLINE","IN_MATCH","SEARCHING"))
        active_matches = sum(a.get("active_matches", 0) for a in accs)
        uptime = max(1, int(time.time() - bot_state.start_time))
        uptime_h = max(0.016, uptime / 3600.0)
        exp_rate = int(bot_state.total_exp_gained / uptime_h) if uptime_h > 0 else 0
        matches_rate = int(bot_state.matches_started / uptime_h) if uptime_h > 0 else 0
        logs_out = []
        for l in bot_state.logs[-200:]:
            try:
                logs_out.append({"time": str(l.get("time","")),
                                 "message": str(l.get("message","")),
                                 "level": str(l.get("level","info"))})
            except Exception: continue
        data = {
            "accounts": accs, "logs": logs_out,
            "total_accounts": len(accs), "total_online": online,
            "total_matches": bot_state.total_matches,
            "total_matches_started": bot_state.matches_started,
            "total_active_matches": active_matches,
            "total_gained_exp": bot_state.total_exp_gained,
            "uptime": uptime, "exp_per_hour": exp_rate,
            "matches_per_hour": matches_rate,
            "creating": bool(bot_state.creating),
            "create_progress": [str(x) for x in bot_state.create_progress[-40:]],
            "team_code": {gid: ts.get("team_code") for gid, ts in _team_states.items()},
            "leader_uid": {gid: ts.get("leader_uid") for gid, ts in _team_states.items()},
            "team_size": sum(len(ts["peers"]) for ts in _team_states.values()),
            "restart_finished": 0,
            "restart_target": 0,
            "restarting": False,
        }
        return aiohttp.web.Response(text=json.dumps(data, default=str, ensure_ascii=False),
                                    content_type="application/json", charset="utf-8")
    except Exception as e:
        traceback.print_exc()
        return aiohttp.web.Response(text=json.dumps({
            "error": str(e), "accounts": [], "logs": [], "create_progress": [],
            "creating": False, "total_accounts": 0, "total_matches_started": 0,
            "total_matches": 0, "total_active_matches": 0, "total_gained_exp": 0,
            "uptime": 1, "exp_per_hour": 0,
        }), content_type="application/json", charset="utf-8")

async def Zesty_api_state(request):
    try:
        return aiohttp.web.Response(text=json.dumps({
            "creating": bool(bot_state.creating),
            "create_progress": [str(x) for x in bot_state.create_progress[-40:]],
            "accounts": list(bot_state.accounts.values()),
            "team_size": sum(len(ts["peers"]) for ts in _team_states.values()),
            "team_groups": list(_team_states.keys()),
        }, default=str, ensure_ascii=False), content_type="application/json", charset="utf-8")
    except Exception as e:
        return aiohttp.web.Response(text=json.dumps({"error": str(e), "creating": False,
                                    "create_progress": []}),
                                    content_type="application/json", charset="utf-8")

async def Zesty_api_progress(request):
    try:
        lines = []
        for x in bot_state.create_progress[-60:]:
            try: lines.append(str(x).encode("ascii","backslashreplace").decode("ascii"))
            except Exception: continue
        Zesty_text = '{"creating":' + ("true" if bot_state.creating else "false") + \
               ',"create_progress":' + json.dumps(lines) + '}'
        return aiohttp.web.Response(text=Zesty_text, content_type="application/json")
    except Exception:
        return aiohttp.web.Response(text='{"creating":false,"create_progress":[]}',
                                    content_type="application/json")

async def Zesty_api_create_team(request):
    try:
        body = await request.json()
        region = str(body.get("region", "BD")).upper()
        clan_id = str(body.get("clan_id", "")).strip()
        count = int(body.get("count", 4))
        if not clan_id:
            return aiohttp.web.json_response({"ok": False, "error": "clan_id required"})
        if bot_state.creating:
            return aiohttp.web.json_response({"ok": False, "error": "already creating"})
        count = max(1, min(4, count))
        asyncio.create_task(Zesty_create_four_accounts(region, clan_id, count))
        return aiohttp.web.json_response({"ok": True, "msg": f"creating {count} bots for {region}"})
    except Exception as e:
        traceback.print_exc()
        return aiohttp.web.json_response({"ok": False, "error": str(e)})

async def Zesty_api_account_add(request):
    try:
        body = await request.json()
        if body.get("token"):
            token = str(body["token"]).strip()
            if not token:
                return aiohttp.web.json_response({"status": "error", "error": "empty token"})
            asyncio.create_task(Zesty_account_loop_token(token))
            return aiohttp.web.json_response({"status": "ok"})
        uid = str(body.get("uid", "")).strip()
        password = str(body.get("password", "")).strip()
        if not uid or not password:
            return aiohttp.web.json_response({"status": "error", "error": "uid and password required"})
        asyncio.create_task(Zesty_account_loop_guest(uid, password))
        return aiohttp.web.json_response({"status": "ok"})
    except Exception as e:
        return aiohttp.web.json_response({"status": "error", "error": str(e)})

async def Zesty_api_account_delete(request):
    try:
        body = await request.json()
        uid = str(body.get("uid", "")).strip()
        auth_uid = str(body.get("auth_uid", "")).strip()
        targets = {uid, auth_uid} - {""}
        for u in list(targets):
            if u in bot_state.account_workers:
                try: bot_state.account_workers[u].cancel()
                except Exception: pass
                bot_state.account_workers.pop(u, None)
            if u in bot_state.accounts:
                del bot_state.accounts[u]
            Zesty_cache_invalidate(u)
            bot_state.Zesty_toggle_pause(u, False)
        return aiohttp.web.json_response({"status": "ok"})
    except Exception as e:
        return aiohttp.web.json_response({"status": "error", "error": str(e)})

async def Zesty_api_account_refresh(request):
    try:
        body = await request.json()
        uid = str(body.get("uid", "")).strip()
        asyncio.create_task(Zesty_refresh_account_profile(uid))
        return aiohttp.web.json_response({"status": "ok"})
    except Exception as e:
        return aiohttp.web.json_response({"status": "error", "error": str(e)})

async def Zesty_api_account_restart(request):
    try:
        body = await request.json()
        uid = str(body.get("uid", "")).strip()
        resolved = {uid}
        if uid in bot_state.game_to_auth_id: resolved.add(str(bot_state.game_to_auth_id[uid]))
        if uid in bot_state.auth_to_game_id: resolved.add(str(bot_state.auth_to_game_id[uid]))
        for u in resolved:
            if u in bot_state.account_workers:
                try: bot_state.account_workers[u].cancel()
                except Exception: pass
                bot_state.account_workers.pop(u, None)

        try:
            teams = Zesty_load_all_team_files()
            for team in teams:
                for a in team["accounts"]:
                    if str(a["uid"]) in resolved and a.get("password"):
                        t = asyncio.create_task(Zesty_account_loop_guest(
                            str(a["uid"]), a["password"],
                            region_override=team["region"],
                            clan_override=team["clan_id"],
                            group_id=team.get("group_id", "default"),
                        ))
                        bot_state.account_workers[str(a["uid"])] = t
                        break
        except Exception:
            pass
        return aiohttp.web.json_response({"status": "ok"})
    except Exception as e:
        return aiohttp.web.json_response({"status": "error", "error": str(e)})

async def Zesty_api_account_pause(request):
    try:
        body = await request.json()
        uid = str(body.get("uid", "")).strip()
        new_state = not bot_state.Zesty_is_paused(uid)
        bot_state.Zesty_toggle_pause(uid, new_state)
        if new_state: bot_state.Zesty_close_writers_for_account(uid)
        return aiohttp.web.json_response({"status": "ok", "Zesty_is_paused": new_state})
    except Exception as e:
        return aiohttp.web.json_response({"status": "error", "error": str(e)})

async def Zesty_api_account_pause_all(request):
    try:
        accs = list(bot_state.accounts.keys())
        if not accs:
            return aiohttp.web.json_response({"status": "ok", "all_paused": False})
        all_paused = all(bot_state.Zesty_is_paused(u) for u in accs)
        new_state = not all_paused
        for u in accs:
            bot_state.Zesty_toggle_pause(u, new_state)
            if new_state: bot_state.Zesty_close_writers_for_account(u)
        return aiohttp.web.json_response({"status": "ok", "all_paused": new_state})
    except Exception as e:
        return aiohttp.web.json_response({"status": "error", "error": str(e)})

async def Zesty_api_account_credentials(request):
    """Return all stored guest credentials for the IDs tab in the dashboard."""
    try:
        seen = set()
        out = []
        for uid, ad in list(bot_state.account_credentials.items()):
            if not isinstance(ad, dict): continue
            auth_uid = str(ad.get('auth_uid') or ad.get('account_id') or uid)
            if auth_uid in seen: continue
            seen.add(auth_uid)
            tok = ad.get('token', '')
            out.append({
                "auth_uid":        str(ad.get('auth_uid', '')),
                "auth_password":   str(ad.get('auth_password', '')),
                "account_id":      str(ad.get('account_id', '')),
                "nickname":        str(ad.get('nickname', '')),
                "region":          str(ad.get('region', 'BD')),
                "level":           int(ad.get('level', 1) or 1),
                "open_id":         str(ad.get('open_id', '')),
                "access_token":    str(ad.get('access_token', '')),
                "jwt_token":       str(tok),
                "jwt_preview":     str(tok)[:60] + ("..." if len(str(tok)) > 60 else ""),
                "server_url":      str(ad.get('server_url', '')),
                "Zesty_server_time":     str(ad.get('Zesty_server_time', '')),
                "Zesty_release_version": str(ad.get('Zesty_release_version', '')),
                "Zesty_client_version":  str(ad.get('Zesty_client_version', '')),
                "platform":        str(ad.get('platform', '4')),
                "auth_type":       str(ad.get('auth_type', 'guest')),
            })
        return aiohttp.web.json_response({"ok": True, "credentials": out})
    except Exception as e:
        return aiohttp.web.json_response({"ok": False, "error": str(e)})

async def Zesty_api_logs_clear(request):
    bot_state.logs = []
    return aiohttp.web.json_response({"status": "ok"})

async def Zesty_account_loop_token(token):
    Zesty_print_info(f"[TOKEN] Login with token {token[:20]}...")
    try:
        vc = await Zesty_version_config("BD")
        if not vc: return
        Zesty_release_version, Zesty_client_version, Zesty_server_url, gop_1, app_version = vc
        url = f"https://100067.connect.garena.com/oauth/token/inspect?token={token}"
        hdrs = {"User-Agent":"GarenaMSDK/4.0.19P4(G011A ;Android 9;en;US;)"}
        r = await client.get(url, headers=hdrs)
        if r.status_code != 200: return
        data = r.json()
        if 'error' in data: return
        open_id = data.get('open_id')
        platform = data.get('platform', 4)
        if not open_id: return

        major_payload, login_payload = await Zesty_get_payload(
            token, open_id, platform, Zesty_client_version)
        res_json = await Zesty_major_login(major_payload, Zesty_server_url, Zesty_release_version)
        if not res_json: return

        def _Zesty_gd(k):
            v = res_json.get(str(k))
            if isinstance(v, dict) and "data" in v: return v["data"]
            return v

        acc_id_raw = _Zesty_gd(1); jwt_token = _Zesty_gd(8)
        server_url_raw = _Zesty_gd(10); Zesty_server_time = _Zesty_gd(21)
        region_raw = _Zesty_gd(2) or "BD"
        aes_ak, iv_i = _Zesty_extract_key_iv(res_json)
        if not (jwt_token and server_url_raw and aes_ak): return

        ld = await Zesty_get_login_data(login_payload, jwt_token, server_url_raw, Zesty_release_version)

        def _Zesty_gf(f, d=None):
            v = (ld or {}).get(str(f), {}).get("data")
            return v if v is not None else d

        level = int(_Zesty_gf(6,1) or 1); exp = int(_Zesty_gf(7,0) or 0)
        nickname = _Zesty_gf(4, f"Player_{acc_id_raw}") or f"Player_{acc_id_raw}"

        ad = {'account_id':acc_id_raw,'nickname':nickname,'region':region_raw,
            'level':level,'exp':exp,'likes':int(_Zesty_gf(8,0) or 0),
            'open_id':open_id,'access_token':token,'platform':str(platform),
            'token':jwt_token,'Zesty_server_time':Zesty_server_time,
            'aes_ak':aes_ak,'iv_i':iv_i,
            'functional_addrs':_Zesty_gf_field(ld, 14),
            'informational_addrs':_Zesty_gf_field(ld, 32),
            'Zesty_release_version':Zesty_release_version,'Zesty_client_version':Zesty_client_version,
            'server_url':server_url_raw,'login_payload_data':login_payload,
            'auth_type':'token','auth_token':token}
        _Zesty_register_credentials(ad)
        Zesty_cache_set(f"tok_{token[:20]}", ad)
        await Zesty_run_account_worker(ad, str(acc_id_raw))
    except Exception as e:
        Zesty_print_error(f"[TOKEN] {e}")

async def Zesty_api_teams(request):
    try:
        teams = Zesty_load_all_team_files()
        return aiohttp.web.json_response({
            "ok": True,
            "teams": [
                {
                    "group_id": t.get("group_id", ""),
                    "clan_id": t["clan_id"],
                    "region": t["region"],
                    "file": t["file"],
                    "count": len(t["accounts"]),
                    "uids": [a["uid"] for a in t["accounts"]],
                }
                for t in teams
            ],
        })
    except Exception as e:
        return aiohttp.web.json_response({"ok": False, "error": str(e)})

async def Zesty_api_team_delete(request):
    try:
        body = await request.json()
        group_id = str(body.get("group_id", "")).strip()
        if not group_id:
            return aiohttp.web.json_response({"ok": False, "error": "group_id required"})

        teams = Zesty_load_all_team_files()
        for t in teams:
            if str(t.get("group_id", "")) != group_id:
                continue
            for a in t["accounts"]:
                u = a["uid"]
                if u in bot_state.account_workers:
                    try: bot_state.account_workers[u].cancel()
                    except Exception: pass
                    bot_state.account_workers.pop(u, None)
                if u in bot_state.accounts:
                    del bot_state.accounts[u]
                Zesty_cache_invalidate(u)
            break

        Zesty_delete_team_file(group_id)
        return aiohttp.web.json_response({"ok": True})
    except Exception as e:
        return aiohttp.web.json_response({"ok": False, "error": str(e)})

async def Zesty_api_clan_info(request):
    try:
        force = request.rel_url.query.get("force", "0") == "1"
        req_clan_id = request.rel_url.query.get("clan_id", "").strip()

        if not hasattr(bot_state, '_clan_cache'):
            bot_state._clan_cache = {}

        teams = Zesty_load_all_team_files()

        async def _Zesty_fetch_clan(team):
            clan_id = team["clan_id"]
            cached_key = f"clan_{clan_id}"

            if not force and cached_key in bot_state._clan_cache:
                return bot_state._clan_cache[cached_key]

            token = None
            for acc in team["accounts"]:
                auth_uid = str(acc["uid"])
                game_uid = bot_state.auth_to_game_id.get(auth_uid, auth_uid)
                creds = (bot_state.account_credentials.get(game_uid) or
                         bot_state.account_credentials.get(auth_uid))
                if creds and creds.get('token'):
                    token = creds['token']
                    break

            if not token:
                Zesty_print_warning(f"[CLAN-API] No token for clan {clan_id}")
                return None

            Zesty_print_info(f"[CLAN-API] Fetching clan {clan_id}")
            info = await Zesty_get_clan_info(token, clan_id)
            if info:
                bot_state._clan_cache[cached_key] = info
            return info

        if req_clan_id:
            target_team = next((t for t in teams if t["clan_id"] == req_clan_id), None)
            if not target_team:
                return aiohttp.web.json_response({"ok": False, "error": f"No team file for clan {req_clan_id}"})
            info = await _Zesty_fetch_clan(target_team)
            if not info:
                return aiohttp.web.json_response({"ok": False, "error": "fetch failed"})
            return aiohttp.web.json_response({"ok": True, **info})

        results = []
        for team in teams:
            info = await _Zesty_fetch_clan(team)
            if info:
                results.append(info)

        return aiohttp.web.json_response({"ok": True, "clans": results})

    except Exception as e:
        traceback.print_exc()
        return aiohttp.web.json_response({"ok": False, "error": str(e)})


async def Zesty_api_teams_clear_all(request):
    """Delete ALL squad JSON files from GEN_IDS and stop their workers."""
    try:
        teams = Zesty_load_all_team_files()
        removed = 0
        for t in teams:
            for a in t["accounts"]:
                u = a["uid"]
                if u in bot_state.account_workers:
                    try: bot_state.account_workers[u].cancel()
                    except Exception: pass
                    bot_state.account_workers.pop(u, None)
                bot_state.accounts.pop(u, None)
                Zesty_cache_invalidate(u)
            Zesty_delete_team_file(t.get("group_id", ""))
            removed += 1
        # Also wipe any leftover files directly
        try:
            for fname in os.listdir(TEAMS_DIR):
                if fname.startswith("squad_") and fname.endswith(".json"):
                    try: os.remove(os.path.join(TEAMS_DIR, fname))
                    except Exception: pass
        except Exception: pass
        return aiohttp.web.json_response({"ok": True, "removed": removed})
    except Exception as e:
        return aiohttp.web.json_response({"ok": False, "error": str(e)})


async def Zesty_api_reset_all(request):
    """Nuke everything — squad files, token cache, stats, bot state — fresh start."""
    try:
        errors = []

        # 1. Cancel all running account workers
        for uid, task in list(bot_state.account_workers.items()):
            try:
                if task and not task.done():
                    task.cancel()
            except Exception: pass
        bot_state.account_workers.clear()

        # 2. Wipe in-memory bot state
        bot_state.accounts.clear()
        bot_state.account_credentials.clear()
        bot_state.auth_to_game_id.clear()
        bot_state.game_to_auth_id.clear()
        bot_state.total_matches = 0
        bot_state.matches_started = 0
        bot_state.total_exp_gained = 0
        bot_state.clan_info = None
        if hasattr(bot_state, '_persisted_account_stats'):
            bot_state._persisted_account_stats = {}

        # 3. Delete all squad JSON files from GEN_IDS/
        try:
            if os.path.isdir(TEAMS_DIR):
                for fname in os.listdir(TEAMS_DIR):
                    if fname.endswith(".json"):
                        try: os.remove(os.path.join(TEAMS_DIR, fname))
                        except Exception as e: errors.append(f"squad/{fname}: {e}")
        except Exception as e:
            errors.append(f"GEN_IDS scan: {e}")

        # 4. Delete token cache
        for f in [TOKEN_CACHE_FILE, TOKEN_CACHE_FILE + ".tmp"]:
            try:
                if os.path.exists(f): os.remove(f)
            except Exception as e: errors.append(f"{f}: {e}")

        # 5. Delete stats file
        try:
            if os.path.exists(STATS_FILE): os.remove(STATS_FILE)
        except Exception as e: errors.append(f"stats: {e}")

        # 6. Delete restart marker
        try:
            if os.path.exists(RESTART_MARKER): os.remove(RESTART_MARKER)
        except Exception as e: errors.append(f"marker: {e}")

        # 7. Reset group match tracking
        global _group_match_done, _restart_scheduled, _match_counters, _group_launched
        _group_match_done.clear()
        _restart_scheduled.clear()
        _match_counters.clear()
        _group_launched.clear()

        return aiohttp.web.json_response({
            "ok": True,
            "message": "All data cleared. Fresh start.",
            "errors": errors
        })
    except Exception as e:
        return aiohttp.web.json_response({"ok": False, "error": str(e)})

async def Zesty_start_web_server():
    app = aiohttp.web.Application(middlewares=[_Zesty_req_logger])
    app.router.add_get("/", Zesty_serve_index)
    app.router.add_get("/index.html", Zesty_serve_index)
    app.router.add_get("/api/ping", Zesty_api_ping)
    app.router.add_get("/api/stats", Zesty_api_stats)
    app.router.add_get("/api/state", Zesty_api_state)
    app.router.add_post("/api/create_team", Zesty_api_create_team)
    app.router.add_post("/api/account/add", Zesty_api_account_add)
    app.router.add_post("/api/account/delete", Zesty_api_account_delete)
    app.router.add_post("/api/account/refresh", Zesty_api_account_refresh)
    app.router.add_post("/api/account/restart", Zesty_api_account_restart)
    app.router.add_post("/api/account/pause", Zesty_api_account_pause)
    app.router.add_post("/api/account/pause_all", Zesty_api_account_pause_all)
    app.router.add_post("/api/logs/clear", Zesty_api_logs_clear)
    app.router.add_get("/api/progress", Zesty_api_progress)
    app.router.add_get("/api/account/credentials", Zesty_api_account_credentials)
    app.router.add_get("/api/teams", Zesty_api_teams)
    app.router.add_get("/api/clan/info", Zesty_api_clan_info)
    app.router.add_post("/api/team/delete", Zesty_api_team_delete)
    app.router.add_post("/api/teams/clear-all", Zesty_api_teams_clear_all)
    app.router.add_post("/api/reset-all", Zesty_api_reset_all)
    runner = aiohttp.web.AppRunner(app)
    await runner.setup()
    site = aiohttp.web.TCPSite(runner, WEB_HOST, WEB_PORT)
    await site.start()
    Zesty_print_success(f"[WEB] Zestyx64 Dashboard → http://localhost:{WEB_PORT}")
    for r in app.router.routes():
        method = ",".join(r.method)
        print(f"      {method:5} {r.resource}")
    return runner

# ==================== MAIN ====================
async def Zesty_main():
    _Zesty_load_stats()
    if os.path.exists(RESTART_MARKER):
        try:
            with open(RESTART_MARKER, "r", encoding="utf-8") as f:
                content = f.read().strip()
            Zesty_print_info(f"[BOOT] ⚡ Previous restart: {content}")
            os.remove(RESTART_MARKER)
        except Exception:
            pass

    try:
        await Zesty_start_web_server()
    except Exception as e:
        Zesty_print_error(f"[WEB] {e}")
        return

    try:
        await _Zesty_autoload_teams()
    except Exception as e:
        Zesty_print_error(f"[BOT] autoload failed: {e}")

    try:
        while True:
            await asyncio.sleep(1)
    except (KeyboardInterrupt, asyncio.CancelledError):
        Zesty_print_warning("Shutting down...")
        for t in list(bot_state.account_workers.values()):
            t.cancel()
        await asyncio.gather(*bot_state.account_workers.values(), return_exceptions=True)
        try: await client.aclose()
        except Exception: pass

if __name__ == "__main__":
    try:
        asyncio.run(Zesty_main())
    except KeyboardInterrupt:
        Zesty_print_warning("stopped")

